def _desktop_startup_crash_log(exc_type, exc_value, exc_tb) -> None:
    """Write unexpected startup/runtime crashes to the Windows desktop for support."""
    try:
        desktop = Path.home() / "Desktop"
        desktop.mkdir(parents=True, exist_ok=True)
        log_path = desktop / "error_log.txt"
        with log_path.open("a", encoding="utf-8", errors="replace") as f:
            f.write("\n" + "=" * 80 + "\n")
            f.write(datetime.now().isoformat(timespec="seconds") + "\n")
            traceback.print_exception(exc_type, exc_value, exc_tb, file=f)
    except Exception:
        pass
    sys.__excepthook__(exc_type, exc_value, exc_tb)


sys.excepthook = _desktop_startup_crash_log

