def effective_update_version_url() -> str:
    """UPDATE_VERSION_URL oder Firebase-…/version.json oder IONOS-API (Produktion)."""
    u = (UPDATE_VERSION_URL or "").strip()
    if u:
        return u
    fb = firebase_p2p_base_url()
    if fb:
        listings = fb if fb.lower().endswith(".json") else f"{fb}/listings.json"
        return firebase_sibling_json_url(listings, "version.json")
    return f"{IONOS_FALLBACK_SERVER_URL.rstrip('/')}/api/v1/public/version.json"


