def resource_path(relative: str) -> Path:
    """PyInstaller: Dateien unter sys._MEIPASS; sonst Projektordner."""
    rel = relative.replace("/", os.sep).lstrip(os.sep)
    base = getattr(sys, "_MEIPASS", None)
    if base:
        p = Path(base) / rel
        if p.exists():
            return p
    p2 = BASE_DIR / rel
    if p2.exists():
        return p2
    return Path(base) / rel if base else p2


def _bootstrap_bundled_assets() -> None:
    """Stellt sicher, dass Icon/Sounds/Locales in EXE und Dev-Modus auffindbar sind."""
    for rel in ("app_icon.ico", "assets", "locales", "assets/sounds"):
        try:
            resource_path(rel)
        except Exception:
            pass


def get_resource_path(relative: str) -> Path:
    """Öffentlicher Alias für gebündelte Assets (.exe / locales / Logos / Handbuch-PDF)."""
    return resource_path(relative)


