def _norm_hangar_name(name: str) -> str:
    return " ".join(str(name).upper().split())


def _title_matches_hangar_model(title_upper: str, model_name: str) -> bool:
    """Sim-TITLE (upper) passt zu Hangar-model_name (Marktplatz-String)."""
    t = title_upper
    mn = _norm_hangar_name(model_name)
    if not mn:
        return False
    if mn in t or (len(mn) > 6 and t in mn):
        return True
    frags = TITLE_OWNERSHIP_FRAGMENTS.get(mn)
    if frags and any(f.upper() in t for f in frags):
        return True
    # Fenix A320: MSFS-TITLE oft nur „Airbus A320-214 …“ ohne Wort „Fenix“
    if mn == "FENIX A320":
        if any(
            x in t
            for x in ("FENIX", "FNX_320", "FNX320", "FNX-320", "FNX 320")
        ):
            return True
        fbw_markers = (
            "FLYBYWIRE",
            "FBW",
            "A32NX",
            "WORKING TITLE",
            "HEADWIND",
            "INI BUILD",
        )
        if not any(x in t for x in fbw_markers) and "A320" in t:
            return True
    if mn == "FLYBYWIRE A32NX":
        return any(x in t for x in ("A32NX", "FBW", "FLYBYWIRE", "FLY BYWIRE"))
    if mn.startswith("PMDG"):
        if "PMDG" not in t:
            return False
        parts = mn.split()
        for p in parts[1:]:
            if len(p) >= 3 and p in t.replace("_", "-").replace(" ", ""):
                return True
        return "PMDG" in t
    toks = [
        x
        for x in re.split(r"[^A-Z0-9]+", mn)
        if (len(x) >= 3 and not x.isdigit()) or (x.isdigit() and len(x) >= 2)
    ]
    if len(toks) >= 2:
        hits = sum(1 for x in toks if x in t)
        if hits >= max(2, len(toks) - 1):
            return True
    return False


def haversine_nm(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    r = 3440.065  # Erdradius nm
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlmb = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dlmb / 2) ** 2
    c = 2 * math.atan2(math.sqrt(a), math.sqrt(max(0.0, 1.0 - a)))
    return r * c


def nearest_airport_nm(lat: float, lon: float) -> tuple[str, float]:
    best_icao = "EDDF"
    best_d = 1e9
    for icao, (la, lo) in AIRPORT_COORDS.items():
        d = haversine_nm(lat, lon, la, lo)
        if d < best_d:
            best_d = d
            best_icao = icao
    return best_icao, best_d


def nearest_main_world_hub_icao(lat: float, lon: float, max_nm: float = 3.0) -> str | None:
    """SimConnect-GPS: nächster Haupt-Hub innerhalb max_nm (Standard 3 NM)."""
    best_icao: str | None = None
    best_d = max_nm + 1.0
    for icao in MAIN_WORLD_HUB_ICAOS:
        coords = AIRPORT_COORDS.get(icao)
        if not coords:
            continue
        d = haversine_nm(lat, lon, coords[0], coords[1])
        if d < best_d:
            best_d = d
            best_icao = icao
    if best_icao is not None and best_d <= max_nm:
        return best_icao
    return None


def rank_pilot_level(xp: float) -> int:
    if xp < LEVEL2_XP:
        return 1
    if xp < LEVEL3_XP:
        return 2
    return 3


