def backup_career_database(path: Path, max_keep: int = BACKUP_MAX_KEEP) -> None:
    """Kopiert career.db nach backups/ und rotiert auf max_keep Dateien."""
    if not path.is_file():
        return
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    ts = time.strftime("%Y%m%d_%H%M%S")
    dest = BACKUP_DIR / f"career_{ts}.db"
    try:
        shutil.copy2(path, dest)
    except OSError:
        return
    backups = sorted(
        BACKUP_DIR.glob("career_*.db"),
        key=lambda p: p.stat().st_mtime,
        reverse=True,
    )
    for old in backups[max_keep:]:
        try:
            old.unlink()
        except OSError:
            pass


def _strip_xml_ns(root: ET.Element) -> None:
    for el in root.iter():
        if isinstance(el.tag, str) and "}" in el.tag:
            el.tag = el.tag.split("}", 1)[1]


def fetch_simbrief_ofp_xml(user_id: str) -> bytes:
    uid = quote(user_id.strip(), safe="")
    if not uid:
        raise ValueError("SimBrief Pilot ID fehlt.")
    url = f"https://www.simbrief.com/api/xml.fetcher.php?userid={uid}"
    r = requests.get(url, timeout=45)
    r.raise_for_status()
    return r.content


def parse_simbrief_ofp(xml_bytes: bytes) -> dict[str, str | float | int]:
    """Liest Kernfelder aus dem SimBrief-OFP-XML (robust gegen kleine Schema-Änderungen)."""
    root = ET.fromstring(xml_bytes)
    _strip_xml_ns(root)
    err_el = root.find("Error")
    if err_el is not None and (err_el.text or "").strip():
        raise ValueError((err_el.text or "").strip())

    def _t(el: ET.Element | None, default: str = "") -> str:
        if el is None or el.text is None:
            return default
        return str(el.text).strip()

    origin = root.find("origin")
    dest = root.find("destination")
    general = root.find("general")
    aircraft = root.find("aircraft")
    fuel = root.find("fuel")
    weights = root.find("weights")

    dep = _t(origin.find("icao_code")) if origin is not None else ""
    arr = _t(dest.find("icao_code")) if dest is not None else ""

    flight_num = _t(general.find("flight_number")) if general is not None else ""
    if not flight_num and general is not None:
        flight_num = _t(general.find("callsign"))

    ac_typ = _t(aircraft.find("icao_code")) if aircraft is not None else ""
    if not ac_typ and aircraft is not None:
        ac_typ = _t(aircraft.find("name"))

    fuel_ramp = 0.0
    if fuel is not None:
        for tag in ("plan_ramp", "ramp", "taxi", "plan_takeoff"):
            v = _t(fuel.find(tag))
            if v:
                try:
                    fuel_ramp = float(v.replace(",", "."))
                    break
                except ValueError:
                    continue

    pax = 0
    cargo = 0.0
    tow_kg = 0.0
    zfw_kg = 0.0
    if weights is not None:
        for tag in ("pax_count", "est_passengers", "passengers"):
            v = _t(weights.find(tag))
            if v:
                try:
                    pax = int(float(v.replace(",", ".")))
                    break
                except ValueError:
                    continue
        for tag in ("cargo", "est_load", "freight"):
            v = _t(weights.find(tag))
            if v:
                try:
                    cargo = float(v.replace(",", "."))
                    break
                except ValueError:
                    continue
        tow_kg = 0.0
        for tag in ("est_tow", "max_tow", "planned_tow", "tow"):
            v = _t(weights.find(tag))
            if v:
                try:
                    tow_kg = float(v.replace(",", "."))
                    break
                except ValueError:
                    continue
        zfw_kg = 0.0
        for tag in ("est_zfw", "zfw"):
            v = _t(weights.find(tag))
            if v:
                try:
                    zfw_kg = float(v.replace(",", "."))
                    break
                except ValueError:
                    continue

    route_txt = ""
    nav_coords: list[list[float]] = []
    navlog = root.find("navlog")
    if navlog is not None:
        fixes: list[str] = []
        for fix in navlog.findall("fix"):
            ident = _t(fix.find("ident"))
            if ident and ident not in fixes:
                fixes.append(ident)
            la_s = _t(fix.find("latitude")) or _t(fix.find("lat"))
            lo_s = _t(fix.find("longitude")) or _t(fix.find("lon"))
            if la_s and lo_s:
                try:
                    la_v = float(la_s.replace(",", "."))
                    lo_v = float(lo_s.replace(",", "."))
                    if -90.0 <= la_v <= 90.0 and -180.0 <= lo_v <= 180.0:
                        nav_coords.append([la_v, lo_v])
                except ValueError:
                    pass
        route_txt = " ".join(fixes[:24])
    if not route_txt:
        route_txt = f"{dep} … {arr}" if dep and arr else ""

    arr_eta_iso = ""
    ofp_pdf_url = ""
    xml_text = (
        xml_bytes.decode("utf-8", errors="ignore")
        if isinstance(xml_bytes, (bytes, bytearray))
        else str(xml_bytes)
    )
    for m in re.finditer(r"https?://[^\s\"'<>]+\.pdf", xml_text, flags=re.I):
        u = m.group(0)
        if "simbrief" in u.lower():
            ofp_pdf_url = u
            break
    if not ofp_pdf_url:
        files_el = root.find("files")
        if files_el is not None:
            for fel in files_el.findall("file"):
                tpe = _t(fel.find("type")).lower()
                if "pdf" in tpe or _t(fel.find("name")).lower().endswith(".pdf"):
                    for tag in ("link", "url", "href"):
                        u = _t(fel.find(tag))
                        if u.startswith("http"):
                            ofp_pdf_url = u
                            break
                    if ofp_pdf_url:
                        break

    if dest is not None:
        for tag in ("eta", "eta_utc", "sta", "sta_utc", "scheduled_time"):
            el = dest.find(tag)
            if el is not None and (el.text or "").strip():
                arr_eta_iso = str(el.text).strip()[:40]
                break

    return {
        "dep": dep,
        "arr": arr,
        "flight_number": flight_num,
        "aircraft": ac_typ,
        "fuel_ramp_kg": fuel_ramp,
        "pax": pax,
        "cargo_kg": cargo,
        "route": route_txt,
        "est_tow_kg": tow_kg,
        "est_zfw_kg": zfw_kg,
        "nav_coords": nav_coords,
        "arr_eta_iso": arr_eta_iso,
        "ofp_pdf_url": ofp_pdf_url,
    }


def insert_flight_report(path: Path, payload: dict) -> None:
    conn = _conn(path)
    try:
        conn.execute(
            "INSERT INTO flight_reports (payload_json) VALUES (?);",
            (json.dumps(payload, ensure_ascii=False),),
        )
        conn.commit()
    finally:
        conn.close()


def format_airline_stars(rating: float) -> str:
    r = max(0.0, min(5.0, float(rating)))
    n = int(round(r))
    return ("⭐" * n) + ("☆" * (5 - n))


def get_airline_rating_stars(path: Path) -> float:
    try:
        return max(0.0, min(5.0, float(app_meta_get(path, "airline_rating_stars", "3.5") or "3.5")))
    except ValueError:
        return 3.5


def update_airline_rating_after_flight(path: Path, flight_quality_01: float) -> float:
    """Bewegt globales Airline-Rating (0–5) leicht Richtung Qualität (0–1)."""
    fq = max(0.0, min(1.0, float(flight_quality_01)))
    old = get_airline_rating_stars(path)
    target_star = fq * 5.0
    new = old * 0.82 + target_star * 0.18
    new = max(0.0, min(5.0, new))
    app_meta_set(path, "airline_rating_stars", f"{new:.4f}")
    return new


def _parse_simbrief_eta_to_utc(eta_s: str) -> datetime | None:
    """SimBrief-Ziel-ETA (verschiedene Formate) als UTC-Zeitpunkt."""
    s = (eta_s or "").strip()
    if not s:
        return None
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except ValueError:
        pass
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%d.%m.%Y %H:%M"):
        try:
            return datetime.strptime(s, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            continue
    m = re.match(r"^(\d{1,2}):(\d{2})(?::(\d{2}))?$", s)
    if m:
        h, mi = int(m.group(1)), int(m.group(2))
        now = datetime.now(timezone.utc)
        return now.replace(hour=h, minute=mi, second=0, microsecond=0)
    if re.fullmatch(r"\d{4}", s):
        h, mi = int(s[:2]), int(s[2:])
        now = datetime.now(timezone.utc)
        return now.replace(hour=h, minute=mi, second=0, microsecond=0)
    return None


def punctuality_for_simbrief_eta(path: Path, tol_min: float = 30.0) -> bool | None:
    """True/False wenn SimBrief-ETA gesetzt und Abweichung zur aktuellen UTC-Zeit klein."""
    eta_s = (app_meta_get(path, "simbrief_arr_eta_iso", "") or "").strip()
    if not eta_s:
        return None
    tgt = _parse_simbrief_eta_to_utc(eta_s)
    if tgt is None:
        return None
    now = datetime.now(timezone.utc)
    diff = abs((now - tgt).total_seconds())
    return diff <= tol_min * 60.0


def compute_flight_quality_01(
    *,
    sat_pct: float,
    vs_fpm: float | None,
    leg_max_g: float,
    seatbelt_violation: bool,
    on_time: bool | None,
) -> float:
    """Skalare Flugqualität 0–1 für Airline-Rating-Update."""
    q = 0.55
    q += (sat_pct / 100.0 - 0.78) * 0.35
    if vs_fpm is not None:
        if vs_fpm > -150.0:
            q += 0.12
        elif vs_fpm < -500.0:
            q -= 0.18
        elif vs_fpm < -350.0:
            q -= 0.07
    mxg = max(float(leg_max_g), 0.0)
    if mxg > 1.85 and seatbelt_violation:
        q -= 0.2
    elif mxg > 2.2:
        q -= 0.08
    if on_time is True:
        q += 0.06
    elif on_time is False:
        q -= 0.07
    return max(0.0, min(1.0, q))


def generate_passenger_reviews(
    lang: str,
    *,
    sat_pct: float,
    vs_fpm: float | None,
    max_g: float,
    seatbelt_bad: bool,
    on_time: bool | None,
) -> list[str]:
    """Drei kurze Passagier-Kommentare passend zur Flugqualität."""
    en = (lang or "de").lower().startswith("en")
    pool: list[str] = []

    if vs_fpm is not None and vs_fpm > -150:
        pool.append(
            "Butter soft – I didn't even feel the touchdown!"
            if en
            else "Butterweich, ich habe die Landung kaum gemerkt!"
        )
    elif vs_fpm is not None and vs_fpm < -500:
        pool.append(
            "That landing hurt my back."
            if en
            else "Mein Rücken tut jetzt noch weh – harte Landung."
        )
    else:
        pool.append(
            "Decent landing, thanks."
            if en
            else "Solide Landung, danke."
        )

    if max_g > 1.85 and seatbelt_bad:
        pool.append(
            "That felt dangerous – seatbelts should have been on."
            if en
            else "Lebensgefährlich! Fast aus dem Sitz – Anschnallzeichen war Pflicht."
        )
    elif max_g > 2.0:
        pool.append(
            "Very rough air – please warn us earlier."
            if en
            else "Sehr holprig – bitte nächstes Mal früher warnen."
        )
    else:
        pool.append(
            "Flight was smooth overall."
            if en
            else "Insgesamt ruhiger Flug."
        )

    if on_time is True:
        pool.append(
            "Right on schedule – appreciated!"
            if en
            else "Pünktlich angekommen – top!"
        )
    elif on_time is False:
        pool.append(
            "We were late – not great for connections."
            if en
            else "Zu spät – schlecht für Anschlüsse."
        )
    else:
        pool.append(
            "Crew seemed professional."
            if en
            else "Crew wirkte professionell."
        )

    if sat_pct >= 88:
        pool.append(
            "Would fly this airline again."
            if en
            else "Würde ich wieder buchen."
        )
    elif sat_pct < 60:
        pool.append(
            "Service felt below expectations."
            if en
            else "Service unter Erwartung."
        )
    else:
        pool.append(
            "OK experience for the price."
            if en
            else "Okay fürs Geld."
        )

    rng = random.Random(int(sat_pct * 1000) + int((vs_fpm or 0)) + int(max_g * 100))
    picks: list[str] = []
    shuf = list(pool)
    rng.shuffle(shuf)
    for s in shuf:
        if s not in picks:
            picks.append(s)
        if len(picks) >= 3:
            break
    while len(picks) < 3:
        picks.append(
            "Thanks, captain."
            if en
            else "Danke, Kapitän."
        )
    return picks[:3]


def list_flight_reports(path: Path, limit: int = 200) -> list[dict]:
    conn = _conn(path)
    try:
        cur = conn.execute(
            """
            SELECT id, created_at, payload_json
            FROM flight_reports
            ORDER BY id DESC
            LIMIT ?;
            """,
            (limit,),
        )
        out: list[dict] = []
        for rid, created, raw in cur.fetchall():
            try:
                out.append(
                    {
                        "id": int(rid),
                        "created_at": str(created),
                        "payload": json.loads(str(raw)),
                    }
                )
            except (json.JSONDecodeError, TypeError, ValueError):
                continue
        return out
    finally:
        conn.close()


