def fuel_price_zone_eur_per_kg(icao: str) -> float:
    """Basis-€/kg je Flughafen-Kategorie (ohne Tages-Würfel)."""
    c = (icao or "").strip().upper()
    if c in FUEL_HUB_ICAOS:
        return FUEL_HUB_EUR_PER_KG
    if c in AIRPORT_COORDS:
        return FUEL_STANDARD_EUR_PER_KG
    return FUEL_REMOTE_EUR_PER_KG


def get_global_fuel_credits_mult(path: Path) -> float:
    """News-Events (z. B. Ölkrise): temporär höhere Spritpreise."""
    m = 1.0
    try:
        exp = float(app_meta_get(path, "news_oil_crisis_until", "0"))
        if time.time() < exp:
            m *= 1.30
    except ValueError:
        pass
    try:
        exp2 = float(app_meta_get(path, "news_fuel_discount_until", "0"))
        if time.time() < exp2:
            m *= 0.92
    except ValueError:
        pass
    try:
        m *= cloud_global_fuel_price_mult()
    except Exception:
        pass
    try:
        evm = float(app_meta_get(path, "cloud_active_event_fuel_mult", "1") or 1.0)
        if evm > 0:
            m *= max(0.05, min(4.0, evm))
    except ValueError:
        pass
    return max(0.5, m)


def jet_world_market_state(path: Path) -> tuple[float, float]:
    """Simulierter Kerosin-Weltmarkt: Faktor mit 12h-Takt leicht driftend; (aktuell, vorher)."""
    now = time.time()
    last = float(app_meta_get(path, "jet_market_last_ts", "0") or "0")
    cur = float(app_meta_get(path, "jet_market_mult", "1.0") or "1.0")
    prev = float(app_meta_get(path, "jet_market_prev_mult", "1.0") or "1.0")
    if last <= 0 or now - last >= JET_MARKET_REFRESH_S:
        app_meta_set(path, "jet_market_prev_mult", f"{cur:.6f}")
        rng = random.Random(int(now // max(1, JET_MARKET_REFRESH_S)))
        cur = max(0.86, min(1.17, cur * (1.0 + rng.uniform(-0.024, 0.024))))
        app_meta_set(path, "jet_market_mult", f"{cur:.6f}")
        app_meta_set(path, "jet_market_last_ts", str(int(now)))
        prev = float(app_meta_get(path, "jet_market_prev_mult", "1.0") or "1.0")
    return cur, prev


def hub_slot_icaos_in_job(job: dict | None) -> list[str]:
    if not job:
        return []
    out: list[str] = []
    for k in ("dep", "arr"):
        ic = str(job.get(k, "") or "").strip().upper()[:4]
        if len(ic) == 4 and ic in HUB_SLOT_ICAOS:
            out.append(ic)
    return sorted(set(out))


def hub_slots_granted_set(path: Path) -> set[str]:
    raw = (app_meta_get(path, "hub_slots_granted", "") or "").strip()
    return {x.strip().upper() for x in raw.split(",") if len(x.strip().upper()) == 4}


def grant_hub_slots_for_job(path: Path, job: dict) -> None:
    s = hub_slots_granted_set(path)
    for ic in hub_slot_icaos_in_job(job):
        s.add(ic)
    app_meta_set(path, "hub_slots_granted", ",".join(sorted(s)))


def hub_slots_missing_for_job(path: Path, job: dict | None) -> list[str]:
    if not job or app_meta_get(path, "realism_airport_slots", "0") != "1":
        return []
    have = hub_slots_granted_set(path)
    return [ic for ic in hub_slot_icaos_in_job(job) if ic not in have]


