def _firebase_patch_json(url: str, payload: dict, timeout: float = 12.0) -> tuple[bool, str]:
    try:
        r = requests.patch(url, json=payload, timeout=timeout)
        if r.status_code >= 400:
            return False, f"HTTP {r.status_code}"
        return True, ""
    except Exception as exc:
        return False, str(exc)


def _firebase_put_json(url: str, payload, timeout: float = 12.0) -> tuple[bool, str]:
    try:
        r = requests.put(url, json=payload, timeout=timeout)
        if r.status_code >= 400:
            return False, f"HTTP {r.status_code}"
        return True, ""
    except Exception as exc:
        return False, str(exc)


def _firebase_get_json(url: str, timeout: float = 12.0):
    try:
        r = requests.get(url, timeout=timeout)
        if r.status_code >= 400:
            return None
        return r.json()
    except Exception:
        return None


def get_fuel_price(icao: str, path: Path | None = None) -> float:
    """
    Credits pro US-Gallon am Standort-ICAO.
    Hubs günstiger, Remote teurer; leichte tägliche Streuung (deterministisch pro Tag+ICAO).
    """
    dbp = path or DB_PATH
    c = (icao or "").strip().upper() or "EDDF"
    day = int(time.time() // 86_400)
    seed = (day * 1_000_003) ^ (hash(c) % 1_000_003) ^ 17_389
    rng = random.Random(seed)
    base_kg = fuel_price_zone_eur_per_kg(c)
    per_gal = base_kg * KG_JETA_PER_US_GALLON
    jitter = rng.uniform(0.91, 1.14)
    jw, _ = jet_world_market_state(dbp)
    return max(0.05, per_gal * jitter * get_global_fuel_credits_mult(dbp) * jw)


def fuel_price_eur_per_kg(icao: str) -> float:
    """Kompatibilität: effektiver €/kg-Äquivalentwert aus get_fuel_price."""
    return get_fuel_price(icao) / KG_JETA_PER_US_GALLON


def fuel_cost_eur_for_us_gallons(icao: str, gallons: float) -> float:
    """Treibstoffkosten (Credits) aus geplantem Verbrauch in US-Gallonen."""
    return max(0.0, float(gallons)) * get_fuel_price(icao)


def mtow_kg_for_model(model: str) -> float:
    m = (model or "").upper()
    for key, kg in AIRCRAFT_MTOW_KG.items():
        if key.upper() in m:
            return float(kg)
    return 78000.0


def synthetic_tcas_traffic(plat: float, plon: float, seed: int) -> list[dict]:
    """Plausible Nah-Verkehr für die Karte (SimConnect liefert KI-Traffic hier selten)."""
    rng = random.Random(seed)
    out: list[dict] = []
    for i in range(TCAS_SIM_TARGETS):
        bearing = rng.random() * 360.0
        dnm = rng.uniform(TCAS_RADIUS_NM_MIN, TCAS_RADIUS_NM_MAX)
        dlat = (dnm / 60.0) * math.cos(math.radians(bearing))
        dlon = (
            (dnm / 60.0)
            * math.sin(math.radians(bearing))
            / max(0.15, math.cos(math.radians(plat)))
        )
        alt = int(rng.uniform(2500, 41000))
        out.append(
            {
                "lat": plat + dlat,
                "lon": plon + dlon,
                "alt_ft": alt,
                "call": f"TCAS{i + 1:02d}",
                "kind": "sim",
            }
        )
    return out


def osm_static_route_preview_url(dep: str, arr: str) -> str:
    d = (dep or "").strip().upper()
    a = (arr or "").strip().upper()
    if d not in AIRPORT_COORDS or a not in AIRPORT_COORDS:
        return ""
    la1, lo1 = AIRPORT_COORDS[d]
    la2, lo2 = AIRPORT_COORDS[a]
    clat = (la1 + la2) / 2.0
    clon = (lo1 + lo2) / 2.0
    return (
        "https://staticmap.openstreetmap.de/staticmap.php?"
        f"center={clat:.4f},{clon:.4f}&zoom=4&size=520x220&maptype=mapnik"
        f"&markers={la1:.4f},{lo1:.4f},red1|{la2:.4f},{lo2:.4f},green2"
    )


def export_flight_aar_pdf(payload: dict, dest: Path) -> None:
    if not _FPDF_AVAILABLE or FPDF is None:
        raise RuntimeError('Paket "fpdf2" fehlt (pip install fpdf2).')
    pdf = FPDF()
    pdf.set_auto_page_break(auto=True, margin=12)
    pdf.add_page()
    pdf.set_font("Helvetica", size=12)
    pdf.cell(0, 8, "MSFS Career – After-Action Report", new_x="LMARGIN", new_y="NEXT")
    pdf.ln(2)
    pdf.set_font("Helvetica", size=10)
    for key in sorted(payload.keys()):
        val = payload.get(key)
        if isinstance(val, (dict, list)):
            val = json.dumps(val, ensure_ascii=False)[:1800]
        for line in str(f"{key}: {val}").splitlines()[:80]:
            pdf.multi_cell(0, 5, line)
    pdf.output(str(dest))


