def sync_aircraft_health_mirror(conn: sqlite3.Connection) -> None:
    _ensure_schema_aircraft_health(conn)
    sync_aircraft_parts_rows(conn)
    conn.execute("DELETE FROM aircraft_health;")
    conn.execute(
        """
        INSERT INTO aircraft_health (model_name, part, condition_pct)
        SELECT model_name, part, condition_pct FROM aircraft_parts;
        """
    )


