def assets_sounds_dir() -> Path:
    p = _writable_app_root() / "assets" / "sounds"
    p.mkdir(parents=True, exist_ok=True)
    return p


def cabin_sound_roots() -> list[Path]:
    """Suchpfade: PyInstaller _MEIPASS, Projektordner, beschreibbarer User-Ordner."""
    seen: set[str] = set()
    out: list[Path] = []
    for p in (
        get_resource_path("assets/sounds"),
        BASE_DIR / "assets" / "sounds",
        assets_sounds_dir(),
    ):
        try:
            key = str(p.resolve())
        except OSError:
            key = str(p)
        if key in seen:
            continue
        seen.add(key)
        if p.is_dir() or p.parent.is_dir():
            p.mkdir(parents=True, exist_ok=True)
            out.append(p)
    return out


def cabin_resolve_announcement_file(key: str, lang: str, gender: str) -> Path | None:
    lo = "en" if str(lang).lower().startswith("en") else "de"
    g = "male" if str(gender).lower() in ("male", "m", "männlich", "man") else "female"
    stem = f"{key}_{lo}_{g}"
    for root in cabin_sound_roots():
        for ext in (".wav", ".mp3", ".ogg"):
            p = root / f"{stem}{ext}"
            if p.is_file() and p.stat().st_size > 64:
                return p
    return None


def cabin_sounds_all_present() -> bool:
    for key, _, _ in CABIN_MANUAL_ANNOUNCEMENTS:
        for lang in ("de", "en"):
            for gender in ("female", "male"):
                if cabin_resolve_announcement_file(key, lang, gender) is None:
                    return False
    return True


def ensure_cabin_announcements_download(*, background: bool = False) -> None:
    """Lädt/generiert alle 12×DE/EN×Stimme-Dateien (blockierend oder Daemon-Thread)."""

    def _run() -> None:
        try:
            ensure_builtin_sound_wavs()
            import download_cabin_sounds as dcs

            targets = {assets_sounds_dir(), *cabin_sound_roots()}
            for root in targets:
                try:
                    dcs.download_all(root)
                except Exception:
                    pass
        except Exception:
            pass

    if background:
        import threading

        threading.Thread(target=_run, daemon=True).start()
    else:
        _run()


def _pcm_silence(rate: int, dur_s: float) -> bytes:
    n = max(0, int(rate * dur_s))
    return b"\x00\x00" * n


def _pcm_sine(rate: int, freq: float, dur_s: float, vol: float = 0.22) -> bytes:
    n = max(0, int(rate * dur_s))
    out = bytearray()
    for i in range(n):
        s = int(32767 * vol * math.sin(2 * math.pi * freq * i / rate))
        out.extend(struct.pack("<h", s))
    return bytes(out)


def _pcm_noise(rate: int, dur_s: float, vol: float = 0.12, seed: int = 1) -> bytes:
    rng = random.Random(seed)
    n = max(0, int(rate * dur_s))
    out = bytearray()
    for _ in range(n):
        s = int(32767 * vol * (rng.random() * 2.0 - 1.0))
        out.extend(struct.pack("<h", s))
    return bytes(out)


def _wav_write_mono16(path: Path, pcm: bytes, rate: int = 22050) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with wave.open(str(path), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(rate)
        wf.writeframes(pcm)


def ensure_builtin_sound_wavs() -> None:
    """Erzeugt kurze Platzhalter-WAVs ohne Netzwerk (vermeidet 403 / gesperrte CDNs)."""
    root = assets_sounds_dir()
    rate = 22050
    ding = (
        _pcm_sine(rate, 880.0, 0.11, 0.2)
        + _pcm_silence(rate, 0.06)
        + _pcm_sine(rate, 660.0, 0.14, 0.2)
    )
    boarding = _pcm_sine(rate, 523.25, 0.38, 0.18)
    n_ap = int(rate * 1.15)
    rng = random.Random(7)
    apl = bytearray()
    for i in range(n_ap):
        env = min(1.0, i / max(1, rate * 0.07)) * max(
            0.0, 1.0 - max(0, i - int(n_ap * 0.55)) / max(1, int(n_ap * 0.42))
        )
        s = int(32767 * 0.17 * env * (rng.random() * 2.0 - 1.0))
        apl.extend(struct.pack("<h", s))
    turb = _pcm_noise(rate, 0.32, 0.11, seed=3) + _pcm_silence(
        rate, 0.04
    ) + _pcm_noise(rate, 0.22, 0.09, seed=9)
    amb_board = _pcm_noise(rate, 2.8, 0.05, seed=42) + _pcm_noise(
        rate, 2.8, 0.05, seed=77
    )
    cabin_chime = (
        _pcm_sine(rate, 740.0, 0.08, 0.18)
        + _pcm_silence(rate, 0.04)
        + _pcm_sine(rate, 880.0, 0.08, 0.18)
        + _pcm_silence(rate, 0.04)
        + _pcm_sine(rate, 988.0, 0.1, 0.18)
    )
    mapping = {
        "dingdong.wav": ding,
        "boarding_chime.wav": boarding,
        "cabin_chime.wav": cabin_chime,
        "applause.wav": bytes(apl),
        "turbulence_rattle.wav": turb,
        "ambient_boarding.wav": amb_board,
    }
    for name, pcm in mapping.items():
        p = root / name
        if not p.is_file() or p.stat().st_size < 128:
            _wav_write_mono16(p, pcm, rate)


def download_sound_assets(
    force: bool = False,
    progress_cb: Callable[[int, int, str], None] | None = None,
) -> list[str]:
    """Stellt lokale WAVs sicher; optional zusätzliche Einträge aus SOUND_ASSET_MANIFEST."""
    errors: list[str] = []
    ensure_builtin_sound_wavs()
    manifest = list(SOUND_ASSET_MANIFEST)
    total = max(1, len(manifest) + 1)
    if progress_cb:
        progress_cb(1, total, "builtin")
    for mi, (fname, url) in enumerate(manifest, 2):
        dest = assets_sounds_dir() / fname
        if dest.is_file() and dest.stat().st_size > 64 and not force:
            if progress_cb:
                progress_cb(mi, total, fname)
            continue
        try:
            r = requests.get(url, timeout=60, headers={"User-Agent": f"MSFS-Career-Tool/{APP_VERSION}"})
            r.raise_for_status()
            dest.write_bytes(r.content)
        except Exception as ex:
            errors.append(f"{fname}: {ex!s}")
        if progress_cb:
            progress_cb(mi, total, fname)
    return errors


def tts_export_wav(text: str, out_wav: Path, rate: int = 178) -> bool:
    """Schreibt TTS als WAV (pyttsx3 save_to_file, falls verfügbar)."""
    if not _PYTTSX3_AVAILABLE or pyttsx3 is None:
        return False
    try:
        eng = pyttsx3.init()
        eng.setProperty("rate", rate)
        out_wav.parent.mkdir(parents=True, exist_ok=True)
        if not hasattr(eng, "save_to_file"):
            return False
        eng.save_to_file(text, str(out_wav))
        eng.runAndWait()
        return out_wav.is_file() and out_wav.stat().st_size > 40
    except Exception:
        return False


def tts_speak_async(text: str) -> None:
    if not _PYTTSX3_AVAILABLE or pyttsx3 is None:
        return

    def run() -> None:
        try:
            eng = pyttsx3.init()
            eng.setProperty("rate", 178)
            eng.say(text)
            eng.runAndWait()
        except Exception:
            pass

    threading.Thread(target=run, daemon=True).start()


def app_meta_get(path: Path, key: str, default: str = "") -> str:
    conn = _conn(path)
