def fetch_metar_aviationweather(icao: str) -> tuple[str | None, str]:
    """
    Liefert (rohes METAR oder None, Fehlertext).
    Quelle: NOAA aviationweather (ohne API-Key).
    """
    icao = "".join(c for c in icao.upper() if c.isalnum())[:4]
    if len(icao) != 4:
        return None, "Ungültiger ICAO-Code."
    url = (
        "https://aviationweather.gov/cgi-bin/data/dataserver.php?"
        "requestType=retrieve&dataSource=metars&stationString="
        f"{icao}&hoursBeforeNow=3&format=xml"
    )
    try:
        r = requests.get(
            url,
            timeout=12,
            headers={"User-Agent": "MSFS-Career-Tool/1.0"},
        )
        r.raise_for_status()
        root = ET.fromstring(r.content)
        for rt in root.iter("raw_text"):
            if rt.text:
                return rt.text.strip(), ""
        return None, "Keine METAR-Daten in der Antwort."
    except Exception as exc:  # noqa: BLE001
        return None, f"Wetterdaten momentan nicht verfügbar ({exc})."


def metar_hard_conditions(metar_raw: str) -> tuple[bool, str]:
    """
    Grobe Heuristik: Wind > 20 kt oder Sicht < 1 SM / 1600 m → schwierig.
    Gibt (schwierig, kurzbeschreibung) zurück.
    """
    s = metar_raw.upper()
    wind_kt = 0
    m = re.search(
        r"\b(VRB|\d{3})(\d{2,3})(G(\d{2,3}))?KT\b",
        s,
    )
    if m:
        wind_kt = int(m.group(2))
        if m.group(4):
            wind_kt = max(wind_kt, int(m.group(4)))
    wind_hard = wind_kt > 20
    vis_bad = False
    if re.search(r"\b(M?1/4|M?1/2)\s*SM\b", s) or re.search(r"\b0\s*SM\b", s):
        vis_bad = True
    msm = re.search(r"\b(M?\d+)SM\b", s)
    if msm:
        try:
            smv = float(msm.group(1).replace("M", "").replace("P", ""))
            if smv < 1.0:
                vis_bad = True
        except ValueError:
            pass
    if "9999" not in s and "CAVOK" not in s:
        mv = re.search(r"\b(0[0-2][0-9]{2}|0[3-9][0-9]{2}|[1][0-5][0-9]{2})\b", s)
        if mv:
            try:
                if int(mv.group(1)) < 1600:
                    vis_bad = True
            except ValueError:
                pass
    hard = wind_hard or vis_bad
    parts = []
    if wind_kt:
        parts.append(f"Wind-Spitze ca. {wind_kt} kt")
    parts.append("Sicht eingeschränkt" if vis_bad else "Sicht plausibel OK")
    return hard, "; ".join(parts)


def metar_surface_wind_peak_kt(metar_raw: str) -> float:
    """Größter Wert aus Wind + optionaler Böe (kt), sonst 0."""
    s = (metar_raw or "").upper()
    m = re.search(r"\b(VRB|\d{3})(\d{2,3})(G(\d{2,3}))?KT\b", s)
    if not m:
        return 0.0
    try:
        base = float(m.group(2))
    except ValueError:
        base = 0.0
    gust = 0.0
    if m.group(4):
        try:
            gust = float(m.group(4))
        except ValueError:
            gust = 0.0
    return max(base, gust)


def metar_est_max_crosswind_kt(metar_raw: str) -> float:
    """
    Konservative Schätzung der maximal möglichen Komponente (kt) ohne Pisten-Heading:
    Spitzenwind × sin(60°) ≈ 0,866 × Peak.
    """
    peak = metar_surface_wind_peak_kt(metar_raw)
    return peak * 0.8660254037844386


def sim_wind_total_and_crosswind_kt(aq: object | None) -> tuple[float | None, float | None]:
    """SimConnect: WIND VELOCITY TRUE X/Z (ft/s), Heading TRUE → Total- und Querwind (kt)."""
    if aq is None:
        return None, None
    try:
        hdg = _as_float(aq.get("PLANE HEADING DEGREES TRUE"))
        wx = _as_float(aq.get("WIND VELOCITY TRUE X"))
        wz = _as_float(aq.get("WIND VELOCITY TRUE Z"))
    except Exception:
        return None, None
    if wx is None or wz is None:
        return None, None
    we = wx * FTPS_TO_KT
    wn = -wz * FTPS_TO_KT
    mag = float(math.hypot(we, wn))
    if hdg is None:
        return mag, abs(we)
    rad = math.radians(float(hdg))
    cross = abs(we * math.cos(rad) - wn * math.sin(rad))
    return mag, float(cross)


def metar_human_summary(metar_raw: str) -> str:
    s = metar_raw.strip()
    if not s:
        return "–"
    wind = "Wind: (nicht erkannt)"
    m = re.search(
        r"\b(VRB|\d{3})(\d{2,3})(G(\d{2,3}))?KT\b",
        s.upper(),
    )
    if m:
        d, sp = m.group(1), m.group(2)
        gust = f", Böen {m.group(4)} kt" if m.group(4) else ""
        wind = f"Wind: {d}° / {sp} kt{gust}"
    qnh = "QNH: –"
    mq = re.search(r"\b(Q\d{4}|A\d{4})\b", s.upper())
    if mq:
        qnh = f"Luftdruck: {mq.group(1)}"
    vis = "Sicht: (siehe RAW)"
    if " CAVOK " in f" {s.upper()} ":
        vis = "Sicht: CAVOK"
    cloud = "Wolken: (siehe RAW)"
    if " NSC " in f" {s.upper()} ":
        cloud = "Wolken: NSC"
    return f"{wind} | {vis} | {cloud} | {qnh}"


def list_airline_branch_icaos(path: Path) -> list[str]:
    conn = _conn(path)
    try:
        cur = conn.execute("SELECT icao FROM airline_branches ORDER BY icao;")
        return [str(r[0]).strip().upper() for r in cur.fetchall() if r and r[0]]
    finally:
        conn.close()


def fetch_airline_branches_realty_rows(path: Path) -> list[dict[str, object]]:
    conn = _conn(path)
    try:
        cur = conn.execute(
            """
            SELECT icao, level, opened_at, total_invested_credits, last_visit_ts
            FROM airline_branches ORDER BY icao;
            """
        )
        out: list[dict[str, object]] = []
        for icao, lvl, opened, inv, lvts in cur.fetchall():
            out.append(
                {
                    "icao": str(icao),
                    "level": int(lvl or 1),
                    "opened_at": str(opened or ""),
                    "invested": float(inv or 0.0),
                    "last_visit_ts": float(lvts or 0.0),
                }
            )
        return out
    finally:
        conn.close()


def touch_branch_last_visit(path: Path, icao: str) -> None:
    c = (icao or "").strip().upper()[:4]
    if len(c) != 4 or not has_airline_branch(path, c):
        return
    conn = _conn(path)
    try:
        conn.execute(
            "UPDATE airline_branches SET last_visit_ts = ? WHERE icao = ?;",
            (time.time(), c),
        )
        conn.commit()
    finally:
        conn.close()


def has_airline_branch(path: Path, icao: str) -> bool:
    c = (icao or "").strip().upper()
    if not c:
        return False
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT 1 FROM airline_branches WHERE icao = ?;", (c,)
        ).fetchone()
        return row is not None
    finally:
        conn.close()


def airline_branch_office_level(path: Path, icao: str) -> int:
    """Büro-Stufe 1–5 am ICAO (Spalte ``level`` in ``airline_branches``)."""
    c = (icao or "").strip().upper()[:4]
    if len(c) != 4:
        return 0
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT level FROM airline_branches WHERE icao = ?;", (c,)
        ).fetchone()
        if not row or row[0] is None:
            return 0
        return max(1, min(5, int(float(row[0]))))
    except (TypeError, ValueError):
        return 1
    finally:
        conn.close()


def max_airline_branch_office_level(path: Path) -> int:
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT MAX(level) FROM airline_branches;"
        ).fetchone()
        if not row or row[0] is None:
            return 0
        return max(0, min(5, int(float(row[0]))))
    except (TypeError, ValueError):
        return 0
    finally:
        conn.close()


OFFICE_UPGRADE_COSTS: dict[int, float] = {
    2: 5_000.0,
    3: 15_000.0,
    4: 30_000.0,
    5: 75_000.0,
}


def upgrade_airline_branch_office(path: Path, icao: str) -> tuple[bool, str, int]:
    """
    Erhöht ``level`` um 1 (max. 5). Zieht Credits laut OFFICE_UPGRADE_COSTS ab.
    Rückgabe: (ok, message_key_or_text, neues_level).
    """
    c = (icao or "").strip().upper()[:4]
    if len(c) != 4 or not c.isalpha():
        return False, "office.err_icao", 0
    if not has_airline_branch(path, c):
        return False, "office.err_no_branch", 0
    cur = airline_branch_office_level(path, c)
    if cur >= 5:
        return False, "office.err_max", 5
    nxt = cur + 1
    cost = float(OFFICE_UPGRADE_COSTS.get(nxt, 0.0))
    if cost <= 0:
        return False, "office.err_cost", cur
    cr = load_credits(path)
    if cr < cost:
        return False, "office.err_credits", cur
    conn = _conn(path)
    try:
        conn.execute(
            "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
            (float(cost),),
        )
        conn.execute(
            """
            UPDATE airline_branches
            SET level = ?, total_invested_credits = total_invested_credits + ?
            WHERE icao = ?;
            """,
            (int(nxt), float(cost), c),
        )
        conn.commit()
    finally:
        conn.close()
    try:
        economy_sync_shadow(path)
    except Exception:
        pass
    return True, "office.ok_upgraded", int(nxt)


def backfill_airline_branch_invested_column(path: Path) -> None:
    """Setzt fehlende ``total_invested_credits`` für ältere Saves (Öffnung + bekannte Upgrades)."""
    conn = _conn(path)
    try:
        rows = conn.execute(
            "SELECT icao, level, COALESCE(total_invested_credits,0) FROM airline_branches;"
        ).fetchall()
        for icao, lvl, inv in rows:
            if float(inv or 0) > 1e-6:
                continue
            l = max(1, min(5, int(float(lvl or 1))))
            tot = float(BRANCH_OFFICE_OPEN_COST)
            for step in range(2, l + 1):
                tot += float(OFFICE_UPGRADE_COSTS.get(step, 0.0))
            conn.execute(
                "UPDATE airline_branches SET total_invested_credits = ? WHERE icao = ?;",
                (tot, str(icao)),
            )
        conn.commit()
    finally:
        conn.close()


def ionos_server_url() -> str:
    """IONOS-Basis-URL (ohne trailing slash).

    Reihenfolge: ``SKYTYCOON_IONOS_SERVER_URL``, ``SKYTYCOON_IONOS_API_BASE``,
    sonst Produktions-Fallback ``IONOS_FALLBACK_SERVER_URL`` (skytycoon.info).
    """
    for key in ("SKYTYCOON_IONOS_SERVER_URL", "SKYTYCOON_IONOS_API_BASE"):
        u = (os.environ.get(key) or "").strip().rstrip("/")
        if u:
            return u
    return IONOS_FALLBACK_SERVER_URL.rstrip("/")


def ionos_api_base_url() -> str:
    """Rückwärtskompatibler Alias (Meilenstein 131)."""
    return ionos_server_url()


def auth_requests_verify_tls() -> bool:
    """TLS-Zertifikatsprüfung für Lizenz-HTTP-Requests (ENV: SKYTYCOON_TLS_VERIFY=0 zum Abschalten)."""
    v = (os.environ.get("SKYTYCOON_TLS_VERIFY") or "1").strip().lower()
    return v not in ("0", "false", "no")


def online_network_enabled(path: Path) -> bool:
    return app_meta_get(path, "online_network_enabled", "0") == "1"


def _job_payload_weight_lbs(job: dict) -> float:
    """Schätzt Gesamt-Payload in Pfund für MSFS SET_PAYLOAD_WEIGHT."""
    if not isinstance(job, dict):
        return 0.0
    cargo_kg = float(job.get("cargo_kg", job.get("cargo", 0)) or 0)
    pax = int(float(job.get("pax", 0) or 0))
    return max(0.0, cargo_kg * 2.20462 + pax * 210.0)


def ionos_post_aircraft_save_state(
    path: Path,
    *,
    aircraft_model: str,
    fuel_gallons: float,
    gate_icao: str,
    gate_label: str = "",
    lat: float | None = None,
    lon: float | None = None,
) -> bool:
    """Persistiert Treibstoff + Gate in der Cloud (/api/v1/aircraft/save_state)."""
    base = ionos_api_base_url().strip().rstrip("/")
    if not base or not online_network_enabled(path):
        return False
    hid = p2p_hardware_id(path)
    pw = cloud_password_get(path)
    if not hid or not pw:
        return False
    body = {
        "hardware_id": hid,
        "password": pw,
        "aircraft_model": (aircraft_model or "")[:80],
        "fuel_gallons": round(float(fuel_gallons), 4),
        "gate_icao": (gate_icao or "")[:4].upper(),
        "gate_label": (gate_label or "")[:64],
    }
    if lat is not None and lon is not None:
        body["lat"] = float(lat)
        body["lon"] = float(lon)
    try:
        r = requests.post(
            f"{base}/api/v1/aircraft/save_state",
            json=body,
            timeout=18,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            verify=auth_requests_verify_tls(),
        )
        if r.status_code == 200:
            data = r.json()
            return bool(isinstance(data, dict) and data.get("ok"))
    except Exception:
        pass
    return False


def ionos_fetch_aircraft_persist_state(path: Path, aircraft_model: str) -> dict | None:
    """Lädt Cloud-Persistenz für ein Flugzeugmodell."""
    base = ionos_api_base_url().strip().rstrip("/")
    if not base or not online_network_enabled(path):
        return None
    hid = p2p_hardware_id(path)
    pw = cloud_password_get(path)
    if not hid or not pw:
        return None
    q = urlencode(
        {
            "hardware_id": hid,
            "password": pw,
            "aircraft_model": (aircraft_model or "")[:80],
        }
    )
    try:
        r = requests.get(
            f"{base}/api/v1/aircraft/load_state?{q}",
            timeout=18,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            verify=auth_requests_verify_tls(),
        )
        if r.status_code != 200:
            return None
        data = r.json()
        if isinstance(data, dict) and data.get("ok"):
            return data.get("state") if isinstance(data.get("state"), dict) else data
    except Exception:
        pass
    return None


def _crash_report_payload_dict(traceback_str: str) -> dict[str, str] | None:
    base = ionos_api_base_url().strip().rstrip("/")
    if not base:
        return None
    hid = p2p_hardware_id(DB_PATH)
    pilot = (
        app_meta_get(DB_PATH, "pilot_display_name", "").strip()
        or app_meta_get(DB_PATH, "pilot_name", "").strip()
        or ""
    )
    return {
        "hardware_id": hid,
        "pilot_name": pilot[:200],
        "app_version": APP_VERSION,
        "traceback": (traceback_str or "")[:24_000],
        "_base": base,
    }


def _crash_report_post_requests_background(traceback_str: str) -> None:
    """POST per requests im globalen QThreadPool (Worker-Threads / Excepthook ohne GUI-Thread)."""
    data = _crash_report_payload_dict(traceback_str)
    if not data:
        return
    base = data.pop("_base", "")

    def _run() -> None:
        try:
            requests.post(
                f"{base}/api/v1/admin/reports/crash",
                json={
                    "hardware_id": data["hardware_id"],
                    "pilot_name": data["pilot_name"],
                    "app_version": data["app_version"],
                    "traceback": data["traceback"],
                },
                timeout=20,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
                verify=auth_requests_verify_tls(),
            )
        except Exception:
            pass

    QThreadPool.globalInstance().start(HeavyTaskWorker(_run))


def send_crash_report_to_ionos(traceback_str: str) -> None:
    """Crash-Telemetrie: bevorzugt ``QNetworkAccessManager`` (MainWindow, GUI-Thread), sonst requests im Pool."""
    app = QApplication.instance()
    w = _MAIN_WIN_REF() if _MAIN_WIN_REF is not None else None
    if (
        w is not None
        and app is not None
        and QThread.currentThread() == app.thread()
        and getattr(w, "_nam", None) is not None
    ):
        try:
            w._post_crash_report_ionos_nam(traceback_str)
            return
        except Exception:
            pass
    _crash_report_post_requests_background(traceback_str)


_profile_cloud_sync_bridge_ref: list[_ProfileCloudSyncBridge | None] = [None]


def register_profile_cloud_sync_bridge(bridge: _ProfileCloudSyncBridge | None) -> None:
    """MainWindow registriert die Qt-Bridge für thread-sichere GUI-Updates."""
    _profile_cloud_sync_bridge_ref[0] = bridge


def _schedule_profile_cloud_emit(snapshot: dict) -> None:
    br = _profile_cloud_sync_bridge_ref[0]
    if br is None or not isinstance(snapshot, dict):
        return
    QTimer.singleShot(0, lambda d=dict(snapshot), b=br: b.profile_updated.emit(d))


def career_cloud_profile_pull_post_async(
    path: Path,
    on_done: Callable[[dict | None], None] | None = None,
) -> None:
    """Profil-Pull im Thread-Pool — blockiert die GUI nicht."""

    def _work() -> dict | None:
        try:
            return career_cloud_profile_pull_post(path)
        except Exception:
            return None

    def _finish(pulled: dict | None) -> None:
        if on_done is not None:
            try:
                on_done(pulled)
            except Exception:
                pass

    def _run() -> None:
        pulled = _work()
        QTimer.singleShot(0, lambda p=pulled: _finish(p))

    QThreadPool.globalInstance().start(HeavyTaskWorker(_run))


def career_cloud_profile_pull_post(path: Path) -> dict | None:
    """Nur Server → Desktop (Autoritative Credits/XP, kein Überschreiben der Cloud)."""
    base = ionos_api_base_url()
    pw = cloud_password_get(path)
    if not base or not pw:
        return None
    body = build_ionos_cloud_sync_body(path, pull_only=True)
    try:
        r = requests.post(
            f"{base.rstrip('/')}/api/v1/user/sync_profile",
            json=body,
            timeout=22,
            headers=ionos_auth_headers(path),
        )
        if r.status_code != 200 or not r.text.strip():
            return None
        j = r.json()
        if not isinstance(j, dict) or not profile_cloud_payload_ok(j):
            return None
        apply_server_profile_authority(path, j)
        return j
    except Exception:
        return None


def career_cloud_profile_sync_post(path: Path, *, push_local: bool = False) -> None:
    """IONOS: Standard = Pull (Server ist Master). Push nur bei explizitem Backup."""
    base = ionos_api_base_url()
    pw = cloud_password_get(path)
    if not base or not pw:
        return
    if not push_local:

        def _on_pulled(pulled: dict | None) -> None:
            if not pulled:
                return
            snap = {
                k: pulled[k]
                for k in (
                    "credits",
                    "xp",
                    "reputation",
                    "bank_loans",
                    "anti_cheat_strikes",
                    "credit_score",
                    "active_global_news",
                )
                if k in pulled
            }
            if snap:
                _schedule_profile_cloud_emit(snap)

        career_cloud_profile_pull_post_async(path, _on_pulled)
        return
    pulled = career_cloud_profile_pull_post(path)
    hid = p2p_hardware_id(path)
    branches = fetch_airline_branches_realty_rows(path)
    branch_payload: list[dict[str, object]] = []
    for b in branches:
        if not isinstance(b, dict):
            continue
        c = str(b.get("icao", "") or "").strip().upper()[:4]
        if len(c) != 4:
            continue
        try:
            lv = int(float(b.get("level", 1) or 1))
        except (TypeError, ValueError):
            lv = 1
        branch_payload.append({"icao": c, "level": max(1, min(5, lv))})
    conn = _conn(path)
    try:
        rmods = [
            str(r[0])
            for r in conn.execute(
                "SELECT model_name FROM pilot_type_ratings ORDER BY model_name;"
            ).fetchall()
            if r and r[0]
        ]
    finally:
        conn.close()
    credits = float(load_credits(path))
    xp = float(get_pilot_meta(path).get("xp", 0.0) or 0.0)
    reputation = float(get_company_reputation(path))
    credit_score_f = float(pilot_credit_score(path))
    try:
        strikes = int(float(app_meta_get(path, "acs_strike_count", "0") or "0"))
    except ValueError:
        strikes = 0
    loan_pr = 0.0
    if LoanManager.has_loan(path):
        try:
            loan_pr = float(app_meta_get(path, LoanManager.K_PRINCIPAL, "0") or "0")
        except ValueError:
            loan_pr = 0.0
    body: dict[str, object] = {
        "hardware_id": hid,
        "password": pw,
        "credits": credits,
        "xp": xp,
        "reputation": reputation,
        "credit_score": credit_score_f,
        "bank_loans": loan_pr,
        "anti_cheat_strikes": strikes,
        "branches": branch_payload,
        "type_ratings": rmods,
    }
    try:
        r = requests.post(
            f"{base}/api/v1/user/sync_profile",
            json=body,
            timeout=35,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code == 200 and r.text.strip():
            j = r.json()
            if isinstance(j, dict) and profile_cloud_payload_ok(j):
                apply_server_profile_authority(path, j)
                snap = {
                    k: j[k]
                    for k in (
                        "credits",
                        "xp",
                        "reputation",
                        "bank_loans",
                        "anti_cheat_strikes",
                        "credit_score",
                        "active_global_news",
                    )
                    if k in j
                }
                al = j.get("alliance")
                if isinstance(al, dict) and al.get("in_alliance"):
                    try:
                        app_meta_set(
                            path,
                            "alliance_snapshot_json",
                            json.dumps(
                                {
                                    "in_alliance": True,
                                    "alliance_id": al.get("alliance_id"),
                                    "alliance_name": al.get("alliance_name"),
                                    "role": al.get("role"),
                                    "alliance_credits": al.get(
                                        "alliance_credits", al.get("credits", 0)
                                    ),
                                    "tax_pct": al.get(
                                        "tax_pct", al.get("tax_rate", 0)
                                    ),
                                },
                                ensure_ascii=False,
                            )[:8000],
                        )
                    except OSError:
                        pass
                if snap and apply_cloud_profile_snapshot_to_career_db(path, snap):
                    _schedule_profile_cloud_emit(snap)
    except Exception:
        pass


def apply_cloud_profile_snapshot_to_career_db(path: Path, j: dict) -> bool:
    """Schreibt Cloud-``users``-Kennzahlen (Server) in lokale ``pilot_stats`` / ``app_meta``."""
    if not isinstance(j, dict):
        return False
    try:
        credits = float(j.get("credits", 0) or 0)
        xp = float(j.get("xp", 0) or 0)
        reputation = float(j.get("reputation", 0) or 0)
    except (TypeError, ValueError):
        return False
    reputation = max(0.0, min(100.0, reputation))
    conn = _conn(path)
    try:
        conn.execute(
            "UPDATE pilot_stats SET credits = ?, xp = ? WHERE id = 1;",
            (credits, xp),
        )
        conn.commit()
    except sqlite3.Error:
        try:
            conn.rollback()
        except sqlite3.Error:
            pass
        return False
    finally:
        conn.close()
    try:
        app_meta_set(path, "company_reputation", f"{reputation:.2f}")
    except OSError:
        pass
    try:
        st = int(float(j.get("anti_cheat_strikes", j.get("strikes", 0)) or 0))
        app_meta_set(path, "acs_strike_count", str(max(0, st)))
    except (TypeError, ValueError, OSError):
        pass
    news = str(j.get("active_global_news", "") or "").strip()
    if news:
        app_meta_set(path, "active_global_news_cached", news)
    alliance = j.get("alliance")
    if isinstance(alliance, dict):
        try:
            app_meta_set(
                path,
                "alliance_snapshot_json",
                json.dumps(alliance, ensure_ascii=False)[:8000],
            )
        except (TypeError, OSError):
            pass
        aid = str(alliance.get("alliance_id") or alliance.get("id") or "").strip()
        aname = str(
            alliance.get("alliance_name") or alliance.get("name") or ""
        ).strip()
        in_al = bool(alliance.get("in_alliance")) or bool(aid)
        try:
            if in_al and aid:
                app_meta_set(path, "career_active_alliance_id", aid[:128])
                if aname:
                    app_meta_set(path, "career_active_alliance_name", aname[:80])
            else:
                app_meta_set(path, "career_active_alliance_id", "")
                app_meta_set(path, "career_active_alliance_name", "")
        except OSError:
            pass
    tok = str(j.get("access_token", "") or "").strip()
    if tok:
        try:
            app_meta_set(path, "ionos_jwt", tok[:4096])
        except OSError:
            pass
    inv = j.get("spare_parts_inventory_json")
    if inv is not None:
        try:
            if isinstance(inv, list):
                app_meta_set(
                    path,
                    "spare_parts_inventory_json",
                    json.dumps(inv, ensure_ascii=False)[:50000],
                )
            elif isinstance(inv, str):
                app_meta_set(path, "spare_parts_inventory_json", inv[:50000])
        except (TypeError, OSError):
            pass
    try:
        economy_sync_shadow(path)
    except Exception:
        pass
    return True


def career_cloud_backup_upload_async(path: Path) -> None:
    """Asynchroner Upload der career.db (optional, wenn Basis-URL + Passwort gesetzt)."""
    base = ionos_api_base_url()
    pw = cloud_password_get(path)
    if not base or not path.is_file() or not pw:
        return
    hid = p2p_hardware_id(path)

    def _run() -> None:
        try:
            with path.open("rb") as f:
                files = {"file": ("career.db", f, "application/octet-stream")}
                data = {"hardware_id": hid, "password": pw}
                requests.post(
                    f"{base}/api/v1/user/backup/upload",
                    data=data,
                    files=files,
                    timeout=120,
                    headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
                )
        except Exception:
            pass
        try:
            career_cloud_profile_pull_post(path)
        except Exception:
            pass

    QThreadPool.globalInstance().start(HeavyTaskWorker(_run))


