def career_cloud_fetch_branches_snapshot(path: Path) -> list[dict[str, object]] | None:
    base = ionos_api_base_url()
    pw = cloud_password_get(path)
    if not base or not pw:
        return None
    hid = p2p_hardware_id(path)
    try:
        r = requests.get(
            f"{base}/api/v1/user/branches/list",
            params={"hardware_id": hid, "password": pw},
            timeout=45,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200:
            return None
        data = r.json()
        raw = data.get("branches")
        if not isinstance(raw, list):
            return []
        return [b for b in raw if isinstance(b, dict)]
    except Exception:
        return None


def career_cloud_pull_branches_to_local(path: Path) -> tuple[bool, str]:
    """M140: Zieht ``branches_json`` vom Server und schreibt ``airline_branches`` lokal."""
    base = ionos_api_base_url()
    pw = cloud_password_get(path)
    if not base or not pw:
        return False, "no_cloud"
    hid = p2p_hardware_id(path)
    try:
        r = requests.post(
            f"{base}/api/v1/user/branches/pull",
            json={"hardware_id": hid, "password": pw},
            timeout=45,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200:
            return False, f"http_{r.status_code}"
        data = r.json()
        branches = data.get("branches") if isinstance(data, dict) else []
        if not isinstance(branches, list):
            return False, "bad_payload"
        if not branches:
            remote = career_cloud_fetch_branches_snapshot(path)
            if remote:
                branches = remote
    except Exception as exc:
        return False, str(exc)
    try:
        n = _apply_cloud_branches_to_local(path, branches)
    except sqlite3.Error:
        return False, "db_error"
    return True, str(n)


def career_cloud_verify_branches_local_vs_remote(path: Path) -> tuple[str, str]:
    """Rückgabe: (i18n_key, default_english)."""
    base = ionos_api_base_url()
    pw = cloud_password_get(path)
    if not base or not pw:
        return (
            "broker.cloud_disabled",
            "Cloud URL or backup password not configured.",
        )
    remote = career_cloud_fetch_branches_snapshot(path)
    if remote is None:
        return (
            "broker.cloud_unreachable",
            "Could not verify branch list with the cloud server.",
        )
    local_rows = fetch_airline_branches_realty_rows(path)
    loc_lvl: dict[str, int] = {}
    loc_inv: dict[str, float] = {}
    loc_vis: dict[str, float] = {}
    for r in local_rows:
        ic = str(r.get("icao") or "").strip().upper()[:4]
        if len(ic) == 4:
            loc_lvl[ic] = max(1, min(5, int(r.get("level") or 1)))
            loc_inv[ic] = float(r.get("invested") or r.get("total_invested_credits") or 0)
            loc_vis[ic] = float(r.get("last_visit_ts") or 0)
    rem_lvl: dict[str, int] = {}
    rem_inv: dict[str, float] = {}
    rem_vis: dict[str, float] = {}
    for b in remote:
        ic = str(b.get("icao") or "").strip().upper()[:4]
        if len(ic) == 4 and ic.isalpha():
            rem_lvl[ic] = max(1, min(5, int(b.get("level") or 1)))
            rem_inv[ic] = _branch_invested_credits_from_cloud(b)
            rem_vis[ic] = float(b.get("last_visit_ts", 0) or 0)
    if loc_lvl == rem_lvl and loc_inv == rem_inv and loc_vis == rem_vis:
        return (
            "broker.cloud_synced",
            "All purchased offices match the cloud registry.",
        )
    return (
        "broker.cloud_mismatch",
        "Local offices and cloud registry differ (ICAO, level, investment or visit).",
    )


def _ui_scroll_wrap(content: QWidget) -> QWidget:
    """Vertikal scrollbarer Seitenrahmen (wie Hangar „12-Checks Wartung“)."""
    shell = QWidget()
    outer = QVBoxLayout(shell)
    outer.setContentsMargins(0, 0, 0, 0)
    outer.setSpacing(0)
    scroll = QScrollArea()
    scroll.setWidgetResizable(True)
    scroll.setFrameShape(QFrame.Shape.NoFrame)
    scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    scroll.setWidget(content)
    outer.addWidget(scroll, 1)
    return shell


def _branch_invested_credits_from_cloud(branch: dict) -> float:
    for key in ("total_invested_credits", "invested_capital", "invested"):
        if key not in branch:
            continue
        try:
            return float(branch.get(key) or 0)
        except (TypeError, ValueError):
            continue
    return 0.0


def _apply_cloud_branches_to_local(path: Path, branches: list) -> int:
    conn = _conn(path)
    n = 0
    try:
        conn.execute("DELETE FROM airline_branches;")
        for b in branches:
            if not isinstance(b, dict):
                continue
            ic = str(b.get("icao") or "").strip().upper()[:4]
            if len(ic) != 4:
                continue
            lv = max(1, min(5, int(b.get("level") or 1)))
            inv = _branch_invested_credits_from_cloud(b)
            lvt = float(b.get("last_visit_ts", 0) or 0)
            conn.execute(
                """
                INSERT INTO airline_branches (icao, level, total_invested_credits, last_visit_ts)
                VALUES (?, ?, ?, ?);
                """,
                (ic, lv, inv, lvt),
            )
            n += 1
        conn.commit()
    except sqlite3.Error:
        try:
            conn.rollback()
        except sqlite3.Error:
            pass
        raise
    finally:
        conn.close()
    return n


class HeavyTaskWorker(QRunnable):
    """Schwere Arbeiten im globalen QThreadPool (M142, kein Blockieren des GUI-Threads)."""

    __slots__ = ("_fn", "_args", "_kwargs")

    def __init__(
        self,
        task_callable: Callable[..., object],
        *args: object,
        **kwargs: object,
    ) -> None:
        super().__init__()
        self._fn = task_callable
        self._args = args
        self._kwargs = kwargs

    def run(self) -> None:
        self._fn(*self._args, **self._kwargs)


class RealtyBranchesTableModel(QAbstractTableModel):
    """QAbstractTableModel für Immobilien-Makler (M140/M142)."""

    ICAO_ROLE = Qt.ItemDataRole.UserRole + 220

    def __init__(self, parent: QObject | None = None) -> None:
        super().__init__(parent)
        self._icao: list[str] = []
        self._loc: list[str] = []
        self._level: list[int] = []
        self._bonus: list[str] = []
        self._invested: list[str] = []
        self._last: list[str] = []

    def rowCount(self, parent: QModelIndex = QModelIndex()) -> int:  # type: ignore[assignment]
        if parent.isValid():
            return 0
        return len(self._icao)

    def columnCount(self, parent: QModelIndex = QModelIndex()) -> int:  # type: ignore[assignment]
        if parent.isValid():
            return 0
        return 5

    def data(self, index: QModelIndex, role: int = int(Qt.ItemDataRole.DisplayRole)):
        if not index.isValid() or index.row() >= len(self._icao):
            return None
        r = index.row()
        c = index.column()
        if role in (int(Qt.ItemDataRole.DisplayRole), int(Qt.ItemDataRole.EditRole)):
            if c == 0:
                return self._loc[r]
            if c == 1:
                return str(self._level[r])
            if c == 2:
                return self._bonus[r]
            if c == 3:
                return self._invested[r]
            return self._last[r]
        if role == int(self.ICAO_ROLE) and c == 0:
            return self._icao[r]
        return None

    def headerData(
        self,
        section: int,
        orientation: Qt.Orientation,
        role: int = int(Qt.ItemDataRole.DisplayRole),
    ):
        if (
            role == int(Qt.ItemDataRole.DisplayRole)
            and orientation == Qt.Orientation.Horizontal
            and 0 <= section < 5
        ):
            win = self.parent()
            tr = getattr(win, "_tr", None)
            keys = (
                "broker.col_location",
                "broker.col_level",
                "broker.col_bonus",
                "broker.col_invested",
                "broker.col_last_visit",
            )
            defaults = (
                "Standort",
                "Büro-Level",
                "Aktiver Bonus",
                "Investiertes Kapital",
                "Letzter Besuch",
            )
            if callable(tr):
                return tr(keys[section], defaults[section])
            return defaults[section]
        return None

    def icao_at_row(self, row: int) -> str | None:
        if 0 <= row < len(self._icao):
            return self._icao[row]
        return None

    def reload_from_db(self, win: object, db_path: Path) -> None:
        rows = fetch_airline_branches_realty_rows(db_path)
        tr = win._tr
        bonus_fn = win._broker_bonus_active_text
        self.beginResetModel()
        self._icao.clear()
        self._loc.clear()
        self._level.clear()
        self._bonus.clear()
        self._invested.clear()
        self._last.clear()
        for rec in rows:
            ic = str(rec.get("icao") or "")
            lv = int(rec.get("level") or 1)
            invested = float(rec.get("invested") or 0.0)
            lvt = float(rec.get("last_visit_ts") or 0.0)
            self._icao.append(ic)
            self._loc.append(airport_route_label(ic))
            self._level.append(lv)
            self._bonus.append(bonus_fn(lv))
            self._invested.append(format_eur_de(invested))
            if lvt > 1.0:
                ds = datetime.fromtimestamp(lvt).strftime("%Y-%m-%d")
            else:
                ds = tr("broker.last_visit_never", "—")
            self._last.append(ds)
        self.endResetModel()


