def open_airline_branch(path: Path, icao: str) -> tuple[bool, str]:
    c = (icao or "").strip().upper()
    if len(c) != 4 or not c.isalpha():
        return False, "ICAO muss 4 Buchstaben sein."
    if c not in AIRPORT_COORDS:
        return False, "Unbekannter Flughafen (nicht in der Koordinaten-Liste)."
    if has_airline_branch(path, c):
        return False, "Büro an diesem ICAO existiert bereits."
    conn = _conn(path)
    try:
        row = conn.execute("SELECT credits FROM pilot_stats WHERE id = 1;").fetchone()
        cr = float(row[0]) if row else 0.0
        if cr < BRANCH_OFFICE_OPEN_COST:
            return False, f"Zu wenig Credits (benötigt {format_eur_de(BRANCH_OFFICE_OPEN_COST)})."
        conn.execute(
            "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
            (BRANCH_OFFICE_OPEN_COST,),
        )
        conn.execute(
            "INSERT INTO airline_branches (icao, level, total_invested_credits) VALUES (?, 1, ?);",
            (c, float(BRANCH_OFFICE_OPEN_COST)),
        )
        conn.commit()
    except sqlite3.IntegrityError:
        conn.rollback()
        return False, "Büro an diesem ICAO existiert bereits."
    finally:
        conn.close()
    return True, f"Niederlassung {c} eröffnet."


def get_company_reputation(path: Path) -> float:
    try:
        return max(
            0.0,
            min(100.0, float(app_meta_get(path, "company_reputation", "72") or "72")),
        )
    except ValueError:
        return 72.0


def add_company_reputation(path: Path, delta: float) -> float:
    v = get_company_reputation(path) + float(delta)
    v = max(0.0, min(100.0, v))
    app_meta_set(path, "company_reputation", f"{v:.2f}")
    return v


def set_press_news_line(path: Path, text: str, duration_s: float = 14_400.0) -> None:
    app_meta_set(path, "news_press_until", str(time.time() + max(300.0, duration_s)))
    app_meta_set(path, "news_press_text", (text or "")[:240])


def generate_passenger_manifest(
    pax_count: int,
    departure_icao: str,
    path: Path | None = None,
) -> list[dict]:
    """Zufällige Passagierliste inkl. VIP/FC; Büro ≥3 am Abflug-ICAO erhöht Chancen (~+40 %)."""
    n = max(0, int(pax_count))
    dep = (departure_icao or "EDDF").strip().upper()[:4]
    rng = random.Random((hash(dep) % 1_000_003) ^ (n * 17) ^ int(time.time()) % 86_400)
    pfx = dep[:2] if len(dep) >= 2 else "ED"
    if pfx in ("ED", "ET", "LO", "LK", "LS", "EH", "EB", "LF", "LE", "LI"):
        pool_f = (
            "Anna,Lena,Sophie,Marie,Lukas,Tim,Felix,Jonas,Paul,Nina,Elena,David".split(",")
        )
        pool_l = (
            "Müller,Schmidt,Schneider,Fischer,Weber,Meyer,Wagner,Becker,Hoffmann,Koch"
        ).split(",")
        nation = (
            "Deutschland,Schweiz,Österreich,Niederlande,Belgien,Frankreich,Italien,Spanien"
        ).split(",")
    elif dep.startswith("K") and len(dep) == 4:
        pool_f = "James,Michael,Emily,Jessica,David,Sarah,Robert,Jennifer,William,Ashley".split(
            ","
        )
        pool_l = "Smith,Johnson,Williams,Brown,Jones,Garcia,Miller,Davis,Wilson,Taylor".split(
            ","
        )
        nation = "USA,Kanada,Mexiko".split(",")
    elif dep.startswith("EG"):
        pool_f = "Oliver,Harry,Emma,Charlotte,George,Jack,Amelia,Isla,Noah,Leo".split(",")
        pool_l = "Smith,Jones,Taylor,Brown,Davies,Wilson,Evans,Thomas,Roberts,Walker".split(
            ","
        )
        nation = "UK,Irland".split(",")
    else:
        pool_f = (
            "Yuki,Hiro,Chen,Wei,Min,Sven,Erik,Lars,Ingrid,Sofia,Marco,Luisa,Nadia,Omar"
        ).split(",")
        pool_l = (
            "Tanaka,Suzuki,Sato,Kim,Park,Nguyen,Patel,Khan,Andersen,Nielsen,Rossi,Silva"
        ).split(",")
        nation = (
            "Japan,Südkorea,China,Singapur,Indien,UAE,Schweden,Norwegen,Italien,Brasilien"
        ).split(",")

    vip_lane = (
        path is not None and airline_branch_office_level(path, dep) >= 3
    )
    vip_boost = 1.4 if vip_lane else 1.0

    def pclip(p: float) -> float:
        return min(1.0, float(p) * vip_boost)

    n_vip = 0
    if n >= 90:
        n_vip = rng.randint(1, 2)
        if vip_lane and rng.random() < pclip(0.35):
            n_vip = min(3, n_vip + 1)
    elif n >= 35:
        n_vip = 1
        if vip_lane and rng.random() < pclip(0.25):
            n_vip = 2
    elif n >= 12:
        n_vip = 1 if rng.random() < pclip(0.45) else 0

    vip_idx: set[int] = set()
    while len(vip_idx) < n_vip and n > 0:
        vip_idx.add(rng.randrange(n))

    n_fc = 0
    if n >= 60:
        n_fc = rng.randint(2, 4)
        if vip_lane:
            n_fc = min(n, n_fc + (1 if rng.random() < pclip(0.3) else 0))
    elif n >= 28:
        n_fc = rng.randint(1, 2)
        if vip_lane and rng.random() < pclip(0.35):
            n_fc = min(n, n_fc + 1)
    elif n >= 14:
        n_fc = 1 if rng.random() < pclip(0.55) else 0
    fc_idx: set[int] = set()
    tries = 0
    while len(fc_idx) < n_fc and n > 0 and tries < n * 4:
        tries += 1
        j = rng.randrange(n)
        if j not in vip_idx:
            fc_idx.add(j)

    out: list[dict] = []
    for i in range(n):
        out.append(
            {
                "first": rng.choice(pool_f),
                "last": rng.choice(pool_l),
                "nationality": rng.choice(nation),
                "vip": i in vip_idx,
                "first_class": i in fc_idx,
            }
        )
    return out


def apply_smuggling_if_cargo(path: Path, job: dict) -> None:
    """Markiert optional Schmuggel-Fracht (3× Lohn) gemäß Realismus-Modul."""
    if app_meta_get(path, "realism_customs_smuggling", "0") != "1":
        return
    if str(job.get("typ")) != "CARGO":
        return
    if job.get("smuggle_cargo"):
        return
    if random.random() >= SMUGGLING_JOB_CHANCE:
        return
    rb = float(job.get("reward_base", job.get("reward", 0)) or 0)
    rw = float(job.get("reward", rb) or 0)
    job["reward_base"] = round(rb * SMUGGLING_PAY_MULT, 0)
    job["reward"] = round(rw * SMUGGLING_PAY_MULT, 0)
    job["smuggle_cargo"] = True


def vip_lounge_cargo_roll(path: Path, job: dict) -> None:
    """Büro ≥3 am Abflug: erhöhte Chance auf lukrative VIP-Charter-Fracht."""
    if str(job.get("typ")) != "CARGO":
        return
    dep = str(job.get("dep", "") or "").strip().upper()[:4]
    if airline_branch_office_level(path, dep) < 3:
        return
    if job.get("smuggle_cargo"):
        return
    if random.random() >= min(1.0, 0.11 * 1.4):
        return
    rb = float(job.get("reward_base", job.get("reward", 0)) or 0)
    rw = float(job.get("reward", rb) or 0)
    m = 1.42
    job["reward_base"] = round(rb * m, 0)
    job["reward"] = round(rw * m, 0)
    job["vip_charter_cargo"] = True
    nar = str(job.get("narrative", "") or "")
    suf = " · VIP-Charter"
    job["narrative"] = (nar + suf).strip(" ·") if nar else suf.strip(" ·")


def generate_random_jobs(
    path: Path,
    count: int,
    filter_typ: str,
    origin_hint_icao: str | None,
) -> list[dict]:
    owned = list_owned_models(path)
    if not owned:
        owned = ["Cessna 172 Skyhawk"]
    icas = list(AIRPORT_COORDS.keys())
    jobs: list[dict] = []
    hubs = [h for h in list_airline_branch_icaos(path) if h in AIRPORT_COORDS]
    for ic in active_alliance_leased_icaos(path):
        if ic in AIRPORT_COORDS and ic not in hubs:
            hubs.append(ic)

    if filter_typ == JOB_FILTER_HUBS:
        if not hubs:
            return []
        rng = random.Random(int(time.time()) // 7200)
        for _ in range(count):
            dep = rng.choice(hubs)
            arr = dep
            tries = 0
            while arr == dep and tries < 40:
                arr = rng.choice(hubs)
                tries += 1
            if arr == dep:
                others = [x for x in hubs if x != dep]
                arr = rng.choice(others) if others else dep
            la1, lo1 = AIRPORT_COORDS[dep]
            la2, lo2 = AIRPORT_COORDS[arr]
            dist = haversine_nm(la1, lo1, la2, lo2)
            pax = rng.randint(55, 210)
            reward_base = (650.0 + dist * 16.0) * HUB_EXCLUSIVE_PAY_MULT
            express = rng.random() < 0.12
            exm = EXPRESS_PAY_MULT if express else 1.0
            reward = reward_base * exm
            try:
                ar = float(app_meta_get(path, "airline_rating_stars", "3.5") or "3.5")
            except ValueError:
                ar = 3.5
            if ar > 4.5:
                reward *= 1.15
                reward_base *= 1.15
            lvl = 1 if dist < 800 else 2 if dist < 3500 else 3
            req = rng.choice(owned)
            jid = f"J-H{rng.randint(10000, 99999)}"
            jobs.append(
                {
                    "id": jid,
                    "typ": "PAX",
                    "dep": dep,
                    "arr": arr,
                    "dist_nm": round(dist, 1),
                    "pax": pax,
                    "cargo_kg": 0.0,
                    "reward_base": round(reward_base, 0),
                    "reward": round(reward, 0),
                    "express": express,
                    "express_mult": exm,
                    "express_deadline_s": EXPRESS_DEADLINE_S,
                    "min_level": lvl,
                    "req_model": req,
                    "narrative": f"VIP-Hub-Auftrag ({dep}): {pax} Gäste · +{int((HUB_EXCLUSIVE_PAY_MULT - 1.0) * 100)} % Basis-Lohn",
                    "start_lat": la1,
                    "start_lon": lo1,
                    "hub_exclusive": True,
                }
            )
        return jobs

    if filter_typ == JOB_FILTER_LOCAL:
        dep_base = (origin_hint_icao or "").strip().upper()[:4]
        if not dep_base or dep_base not in AIRPORT_COORDS:
            return []
        rng = random.Random(int(time.time()) // 1800)
        la0, lo0 = AIRPORT_COORDS[dep_base]
        others = [x for x in icas if x != dep_base]

        def dist_nm_to(a: str) -> float:
            la, lo = AIRPORT_COORDS[a]
            return haversine_nm(la0, lo0, la, lo)

        def pick_band(dmin: float, dmax: float) -> str:
            cand = [x for x in others if dmin <= dist_nm_to(x) <= dmax]
            if cand:
                return rng.choice(cand)
            ranked = sorted(others, key=dist_nm_to)
            for x in ranked:
                if dist_nm_to(x) >= dmin:
                    return x
            return rng.choice(ranked) if ranked else dep_base

        target_n = max(int(count), 15)
        specs: list[tuple[str, bool]] = (
            [("short", False)] * 3
            + [("short", True)] * 2
            + [("med", False)] * 3
            + [("med", True)] * 2
            + [("long", False)] * 3
            + [("long", True)] * 2
        )
        while len(specs) < target_n:
            specs.append(("med", rng.random() < 0.45))

        dep = dep_base
        la1, lo1 = AIRPORT_COORDS[dep]
        for band, is_cargo in specs[:target_n]:
            if band == "short":
                arr = pick_band(50.0, 250.0)
            elif band == "med":
                arr = pick_band(251.0, 1000.0)
            else:
                arr = pick_band(2000.0, 12_000.0)
            if arr == dep:
                arr = pick_band(30.0, 4000.0)
            if arr == dep:
                continue
            la2, lo2 = AIRPORT_COORDS[arr]
            dist = haversine_nm(la1, lo1, la2, lo2)
            express = rng.random() < 0.28
            exm = LOCAL_EXPRESS_PAY_MULT if express else 1.0
            if is_cargo:
                cargo_kg = float(rng.randint(1200, 18000))
                pax = 0
                reward_base = 380.0 + dist * 10.5
                typ = "CARGO"
                narrative = i18n_db(
                    path,
                    "job.narr.local.cargo",
                    "{kg} kg Fracht · {dep} → {arr}",
                ).format(
                    kg=int(cargo_kg),
                    dep=airport_route_label(dep),
                    arr=airport_route_label(arr),
                )
            else:
                cargo_kg = 0.0
                pax = rng.randint(35, 170)
                reward_base = 620.0 + dist * 15.0
                typ = "PAX"
                narrative = i18n_db(
                    path,
                    "job.narr.local.pax",
                    "{pax} PAX · {dep} → {arr}",
                ).format(
                    pax=pax,
                    dep=airport_route_label(dep),
                    arr=airport_route_label(arr),
                )
            reward = reward_base * exm
            try:
                ar = float(app_meta_get(path, "airline_rating_stars", "3.5") or "3.5")
            except ValueError:
                ar = 3.5
            if typ == "PAX" and ar > 4.5:
                reward *= 1.12
                reward_base *= 1.12
            lvl = 1 if dist < 800 else 2 if dist < 3500 else 3
            req = rng.choice(owned)
            jid = f"J-L{rng.randint(10000, 99999)}"
            subsidized_dest = arr.strip().upper()[:4] in SUBSIDIZED_DEST_ICAOS
            jobs.append(
                {
                    "id": jid,
                    "typ": typ,
                    "dep": dep,
                    "arr": arr,
                    "dist_nm": round(dist, 1),
                    "pax": pax,
                    "cargo_kg": cargo_kg,
                    "reward_base": round(reward_base, 0),
                    "reward": round(reward, 0),
                    "express": express,
                    "express_mult": exm,
                    "express_deadline_s": (
                        LOCAL_EXPRESS_DEADLINE_S if express else EXPRESS_DEADLINE_S
                    ),
                    "min_level": lvl,
                    "req_model": req,
                    "narrative": narrative,
                    "start_lat": la1,
                    "start_lon": lo1,
                    "local_pickup": True,
                    "subsidized_dest": subsidized_dest,
                }
            )
            apply_smuggling_if_cargo(path, jobs[-1])
            vip_lounge_cargo_roll(path, jobs[-1])
        return jobs

    origin = origin_hint_icao if origin_hint_icao in AIRPORT_COORDS else random.choice(icas)
    for _ in range(count):
        dep = origin if random.random() < 0.7 else random.choice(icas)
        arr = dep
        while arr == dep:
            arr = random.choice(icas)
        la1, lo1 = AIRPORT_COORDS[dep]
        la2, lo2 = AIRPORT_COORDS[arr]
        dist = haversine_nm(la1, lo1, la2, lo2)
        is_cargo = random.random() < 0.45
        if filter_typ == JOB_FILTER_PAX:
            is_cargo = False
        elif filter_typ == JOB_FILTER_CARGO:
            is_cargo = True
        lvl = 1 if dist < 800 else 2 if dist < 3500 else 3
        req = random.choice(owned)
        express = random.random() < 0.18
        exm = EXPRESS_PAY_MULT if express else 1.0
        if is_cargo:
            cargo_kg = float(random.randint(1800, 24000))
            pax = 0
            reward_base = 400.0 + dist * 11.0
            narrative = f"{int(cargo_kg)} kg Maschinenteile / Elektronik"
            typ = "CARGO"
        else:
            cargo_kg = 0.0
            pax = random.randint(45, 220)
            reward_base = 650.0 + dist * 16.0
            narrative = f"{pax} Passagiere (Economy Class)"
            typ = "PAX"
        reward = reward_base * exm
        try:
            ar = float(app_meta_get(path, "airline_rating_stars", "3.5") or "3.5")
        except ValueError:
            ar = 3.5
        if typ == "PAX" and ar > 4.5:
            reward *= 1.15
            reward_base *= 1.15
        jid = f"J-{random.randint(10000, 99999)}"
        jobs.append(
            {
                "id": jid,
                "typ": typ,
                "dep": dep,
                "arr": arr,
                "dist_nm": round(dist, 1),
                "pax": pax,
                "cargo_kg": cargo_kg,
                "reward_base": round(reward_base, 0),
                "reward": round(reward, 0),
                "express": express,
                "express_mult": exm,
                "express_deadline_s": EXPRESS_DEADLINE_S,
                "min_level": lvl,
                "req_model": req,
                "narrative": narrative,
                "start_lat": la1,
                "start_lon": lo1,
            }
        )
        apply_smuggling_if_cargo(path, jobs[-1])
        vip_lounge_cargo_roll(path, jobs[-1])
    return jobs

