def _conn(path: Path) -> sqlite3.Connection:
    """Lokaler Offline-Cache (career.db). Cloud-Live-Daten: get_db_connection()."""
    return sqlite3.connect(path)


def _pg_conn():
    """PostgreSQL skytycoon_prod — DictCursor (Kompatibilität mit user['credits'])."""
    return get_db_connection()


def _career_db_quick_check_ok(path: Path) -> bool:
    """PRAGMA quick_check – False bei fehlender/korrupt career.db."""
    if not path.is_file():
        return True
    try:
        conn = sqlite3.connect(str(path), timeout=10.0)
    except sqlite3.Error:
        return False
    try:
        row = conn.execute("PRAGMA quick_check;").fetchone()
        return bool(row) and str(row[0]).lower() == "ok"
    except sqlite3.Error:
        return False
    finally:
        conn.close()


def _restore_career_from_latest_backup(path: Path) -> bool:
    """Stellt career.db aus last_safe_exit.db oder dem neuesten career_*.db wieder her."""
    if not BACKUP_DIR.is_dir():
        return False
    candidates: list[Path] = []
    last_safe = BACKUP_DIR / "last_safe_exit.db"
    if last_safe.is_file():
        candidates.append(last_safe)
    candidates.extend(
        sorted(
            BACKUP_DIR.glob("career_*.db"),
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )
    )
    for bp in candidates:
        if not _career_db_quick_check_ok(bp):
            continue
        try:
            shutil.copy2(bp, path)
            return True
        except OSError:
            continue
    return False


def init_database(path: Path) -> None:
    if path.is_file() and not _career_db_quick_check_ok(path):
        _restore_career_from_latest_backup(path)
    backup_career_database(path, BACKUP_MAX_KEEP)
    conn = _conn(path)
    try:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS pilot_stats (
                id INTEGER PRIMARY KEY CHECK (id = 1),
                credits REAL NOT NULL DEFAULT 6000000.0,
                flight_hours REAL NOT NULL DEFAULT 0.0
            );
            INSERT OR IGNORE INTO pilot_stats (id, credits, flight_hours)
            VALUES (1, 6000000.0, 0.0);

            CREATE TABLE IF NOT EXISTS app_meta (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS market (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                model_name TEXT NOT NULL UNIQUE,
                price REAL NOT NULL
            );

            CREATE TABLE IF NOT EXISTS owned_aircraft (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                model_name TEXT NOT NULL UNIQUE,
                condition REAL NOT NULL DEFAULT 100.0,
                purchase_price REAL NOT NULL DEFAULT 0.0
            );
            """
        )
        _migrate_owned_aircraft_if_needed(conn)
        _apply_wallet_minimum_million(conn)
        _apply_wallet_floor_6m(conn)
        _ensure_market_listings(conn)
        _ensure_schema_m11_m12(conn)
        _ensure_schema_m13_m16(conn)
        _ensure_schema_m25_m26(conn)
        _ensure_schema_m27(conn)
        _ensure_schema_m32_parts(conn)
        _ensure_column(
            conn, "aircraft_parts", "used_part", "INTEGER NOT NULL DEFAULT 0"
        )
        _ensure_column(
            conn,
            "aircraft_parts",
            "black_market_engine",
            "INTEGER NOT NULL DEFAULT 0",
        )
        sync_aircraft_parts_rows(conn)
        _ensure_schema_aircraft_health(conn)
        sync_aircraft_health_mirror(conn)
        _ensure_schema_m56_branches_manifest(conn)
        _ensure_schema_hr_crew(conn)
        _ensure_schema_finance_m78(conn)
        _ensure_schema_type_ratings(conn)
        _ensure_schema_accepted_jobs(conn)
        conn.commit()
    finally:
        conn.close()
    backfill_airline_branch_invested_column(path)
    accepted_jobs_migrate_from_active(path)
    _migrate_setup_wizard_v2_flag(path)


def _apply_wallet_minimum_million(conn: sqlite3.Connection) -> None:
    """Einmalig: Kontostand mindestens 1.000.000 Credits (für bestehende career.db)."""
    if conn.execute(
        "SELECT 1 FROM app_meta WHERE key = 'portal_starter_account_v1'"
    ).fetchone():
        return
    row = conn.execute(
        "SELECT 1 FROM app_meta WHERE key = 'wallet_min_million_v1'"
    ).fetchone()
    if row:
        return
    conn.execute(
        """
        UPDATE pilot_stats
        SET credits = CASE
            WHEN credits < 1000000.0 THEN 1000000.0
            ELSE credits
        END
        WHERE id = 1;
        """
    )
    conn.execute(
        "INSERT INTO app_meta (key, value) VALUES ('wallet_min_million_v1', '1');"
    )


def _apply_wallet_floor_6m(conn: sqlite3.Connection) -> None:
    """Einmalig: Kontostand mindestens 6.000.000 Credits."""
    if conn.execute(
        "SELECT 1 FROM app_meta WHERE key = 'portal_starter_account_v1'"
    ).fetchone():
        return
    row = conn.execute(
        "SELECT 1 FROM app_meta WHERE key = 'wallet_floor_6m_v1'"
    ).fetchone()
    if row:
        return
    conn.execute(
        """
        UPDATE pilot_stats
        SET credits = MAX(credits, 6000000.0)
        WHERE id = 1;
        """
    )
    conn.execute(
        "INSERT INTO app_meta (key, value) VALUES ('wallet_floor_6m_v1', '1');"
    )


def _ensure_market_listings(conn: sqlite3.Connection) -> None:
    for name, price in MASTER_MARKET:
        conn.execute(
            """
            INSERT OR IGNORE INTO market (model_name, price)
            VALUES (?, ?);
            """,
            (name, price),
        )


def _ensure_column(
    conn: sqlite3.Connection, table: str, col: str, decl_sql: str
) -> None:
    cols = {
        r[1]
        for r in conn.execute(f"PRAGMA table_info({table})").fetchall()
    }
    if col not in cols:
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {col} {decl_sql};")


def _ensure_schema_m11_m12(conn: sqlite3.Connection) -> None:
    _ensure_column(conn, "pilot_stats", "xp", "REAL NOT NULL DEFAULT 0")
    _ensure_column(conn, "pilot_stats", "license_suspended_until", "REAL NOT NULL DEFAULT 0")
    _ensure_column(conn, "pilot_stats", "pilot_rest_until", "REAL NOT NULL DEFAULT 0")
    _ensure_column(conn, "pilot_stats", "lifetime_fuel_cost", "REAL NOT NULL DEFAULT 0")
    _ensure_column(conn, "pilot_stats", "lifetime_revenue", "REAL NOT NULL DEFAULT 0")
    _ensure_column(conn, "pilot_stats", "crew_fatigue_pct", "REAL NOT NULL DEFAULT 0")
    _ensure_column(conn, "owned_aircraft", "insured", "INTEGER NOT NULL DEFAULT 0")
    _ensure_column(
        conn, "owned_aircraft", "insurance_last_charge_ts", "REAL NOT NULL DEFAULT 0"
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS flight_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            flown_at TEXT NOT NULL DEFAULT (datetime('now')),
            aircraft TEXT NOT NULL,
            route_from TEXT NOT NULL DEFAULT '-',
            route_to TEXT NOT NULL DEFAULT '-',
            duration_minutes REAL NOT NULL,
            landing_vs_fpm REAL,
            landing_g REAL,
            credits_earned REAL NOT NULL DEFAULT 0,
            fuel_gallons REAL NOT NULL DEFAULT 0,
            fuel_cost REAL NOT NULL DEFAULT 0,
            hard_landing INTEGER NOT NULL DEFAULT 0,
            sim_crash INTEGER NOT NULL DEFAULT 0
        );
        """
    )


def desktop_dir() -> Path:
    home = Path.home()
    desk = home / "Desktop"
    if desk.is_dir():
        return desk
    if sys.platform == "win32":
        up = os.environ.get("USERPROFILE")
        if up:
            p = Path(up) / "Desktop"
            if p.is_dir():
                return p
    return home


def rank_from_xp(xp: float) -> str:
    if xp < LEVEL2_XP:
        return "Flugschüler"
    if xp < LEVEL3_XP:
        return "Privatpilot"
    return "Airline Transport Pilot"


_LUXURY_PERKS_CACHE: dict[str, Any] = {"ts": 0.0, "data": {}}


def skytycoon_luxury_perks(refresh: bool = False) -> dict[str, Any]:
    """Live-Perks aus PostgreSQL (/api/v1/player/luxury_perks) — VIP, Radar, Casino."""
    now = time.time()
    if not refresh and (now - float(_LUXURY_PERKS_CACHE.get("ts") or 0)) < 90.0:
        cached = _LUXURY_PERKS_CACHE.get("data")
        if isinstance(cached, dict) and cached:
            return cached
    out: dict[str, Any] = {
        "vip_income_mult": 1.0,
        "heavy_cargo_mult": 1.0,
        "weather_shield": False,
        "alliance_slots_bonus": 0,
        "high_roller": False,
        "gold_radar": False,
        "casino_unlocked": False,
    }
    try:
        hid = (app_meta_get(DB_PATH, "hardware_id", "") or "").strip()[:64]
        if not hid:
            return out
        base = ionos_server_url().rstrip("/")
        r = requests.get(
            f"{base}/api/v1/player/luxury_perks",
            params={"hardware_id": hid},
            timeout=8,
        )
        if r.status_code == 200:
            data = r.json()
            if isinstance(data, dict):
                out.update(data)
    except Exception:
        pass
    _LUXURY_PERKS_CACHE["ts"] = now
    _LUXURY_PERKS_CACHE["data"] = out
    return out


def append_flight_log(
    path: Path,
    aircraft: str,
    duration_min: float,
    vs_fpm: float | None,
    landing_g: float | None,
    credits_earned: float,
    fuel_gal: float,
    fuel_cost: float,
    hard: int,
    sim_crash: int,
    route_from: str = "-",
    route_to: str = "-",
    *,
    vip_on_board: int = 0,
    vip_outcome: str = "",
) -> None:
    conn = _conn(path)
    try:
        conn.execute(
            """
            INSERT INTO flight_log (
                aircraft, route_from, route_to, duration_minutes,
                landing_vs_fpm, landing_g, credits_earned,
                fuel_gallons, fuel_cost, hard_landing, sim_crash,
                vip_on_board, vip_outcome
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
            """,
            (
                aircraft,
                route_from,
                route_to,
                duration_min,
                vs_fpm,
                landing_g,
                credits_earned,
                fuel_gal,
                fuel_cost,
                hard,
                sim_crash,
                int(vip_on_board),
                str(vip_outcome or "")[:64],
            ),
        )
        conn.commit()
    finally:
        conn.close()


def flight_log_revenue_fuel_last_days(path: Path, days: int = 7) -> list[tuple[str, float, float]]:
    """Pro Kalendertag: (datum, credits_earned_sum, fuel_cost_sum)."""
    conn = _conn(path)
    out: list[tuple[str, float, float]] = []
    try:
        cur = conn.execute(
            """
            SELECT date(flown_at) AS d,
                   SUM(credits_earned) AS ce,
                   SUM(fuel_cost) AS fc
            FROM flight_log
            WHERE datetime(flown_at) >= datetime('now', ?)
            GROUP BY date(flown_at)
            ORDER BY d ASC;
            """,
            (f"-{int(days)} days",),
        )
        for d, ce, fc in cur.fetchall():
            out.append((str(d), float(ce or 0), float(fc or 0)))
    finally:
        conn.close()
    return out


def flight_log_today_revenue_expense(path: Path) -> tuple[float, float]:
    """Heutige Summe (Kalendertag lokal): (Einnahmen credits_earned, Ausgaben fuel_cost)."""
    conn = _conn(path)
    try:
        d = datetime.now().strftime("%Y-%m-%d")
        row = conn.execute(
            """
            SELECT COALESCE(SUM(credits_earned), 0), COALESCE(SUM(fuel_cost), 0)
            FROM flight_log WHERE date(flown_at) = ?;
            """,
            (d,),
        ).fetchone()
        if not row:
            return 0.0, 0.0
        return float(row[0] or 0), float(row[1] or 0)
    finally:
        conn.close()


def pilot_credit_score(path: Path) -> int:
    """0–1000 Demo-Bonität aus Kontostand, XP und Reputation."""
    cr = load_credits(path)
    xp = float(get_pilot_meta(path).get("xp", 0.0))
    rep = get_company_reputation(path)
    raw = cr / 30_000.0 + xp / 30.0 + rep * 2.5
    if max_airline_branch_office_level(path) >= 5:
        raw += 35.0
    return int(max(0.0, min(1000.0, raw)))


def pilot_rank_down_n_levels(path: Path, n: int) -> None:
    """Senkt den XP-Rang um n Stufen (Airline-Pilot → …)."""
    n = max(1, int(n))
    xp = float(get_pilot_meta(path).get("xp", 0.0))
    lvl = rank_pilot_level(xp)
    tgt = max(1, lvl - n)
    if tgt >= 3:
        new_xp = LEVEL3_XP + 1.0
    elif tgt == 2:
        new_xp = LEVEL2_XP + 1.0
    else:
        new_xp = 0.0
    add_xp(path, new_xp - xp)


def export_flight_log_csv(path: Path, dest: Path) -> int:
    conn = _conn(path)
    try:
        rows = conn.execute(
            """
            SELECT flown_at, aircraft, route_from, route_to, duration_minutes,
                   landing_vs_fpm, landing_g, credits_earned, fuel_gallons,
                   fuel_cost, hard_landing, sim_crash
            FROM flight_log ORDER BY id ASC;
            """
        ).fetchall()
    finally:
        conn.close()
    headers = [
        "Datum",
        "Flugzeug",
        "Von",
        "Nach",
        "Dauer_min",
        "Lande_VS_fpm",
        "Lande_G",
        "Credits",
        "Treibstoff_gal",
        "Spritkosten",
        "Harte_Landung",
        "Sim_Crash",
    ]
    with dest.open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f, delimiter=";")
        w.writerow(headers)
        for r in rows:
            w.writerow(r)
    return len(rows)


def flight_log_stats(path: Path) -> dict[str, object]:
    conn = _conn(path)
    try:
        row = conn.execute(
            """
            SELECT aircraft, COUNT(*) FROM flight_log
            GROUP BY aircraft ORDER BY COUNT(*) DESC LIMIT 1;
            """
        ).fetchone()
        most_plane = str(row[0]) if row else "–"
        hm = conn.execute(
            "SELECT MIN(landing_g), MAX(landing_g) FROM flight_log WHERE landing_g IS NOT NULL;"
        ).fetchone()
        hardest = float(hm[0]) if hm and hm[0] is not None else 0.0
        softest = float(hm[1]) if hm and hm[1] is not None else 0.0
        sums = conn.execute(
            "SELECT COALESCE(SUM(credits_earned),0), COALESCE(SUM(fuel_cost),0) FROM flight_log;"
        ).fetchone()
        rev = float(sums[0]) if sums else 0.0
        fuel = float(sums[1]) if sums else 0.0
        n = conn.execute("SELECT COUNT(*) FROM flight_log;").fetchone()[0]
    finally:
        conn.close()
    return {
        "most_aircraft": most_plane,
        "hardest_g": hardest,
        "softest_g": softest,
        "total_credits": rev,
        "total_fuel_cost": fuel,
        "flights": int(n),
    }


def p2p_broker_path() -> Path:
    return BASE_DIR / P2P_LOCAL_BROKER_FILE


def p2p_migrate_legacy_broker_file(path: Path) -> None:
    """Einmalig: alte ``skytycoon_p2p_broker.json`` → app_meta-Cache."""
    if p2p_listings_cache_load(path):
        return
    legacy = p2p_broker_path()
    if not legacy.is_file():
        return
    try:
        raw = json.loads(legacy.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return
    if not isinstance(raw, dict):
        return
    lst = raw.get("listings")
    if isinstance(lst, list) and lst:
        _p2p_broker_save(
            {"listings": lst, "notes": raw.get("notes") if isinstance(raw.get("notes"), list) else []},
            path,
        )


def _p2p_broker_load(path: Path | None = None) -> dict:
    """P2P-Daten aus app_meta (keine skytycoon_p2p_broker.json mehr)."""
    p = path or DB_PATH
    with _p2p_broker_lock:
        listings = p2p_listings_cache_load(p)
        raw_notes = (app_meta_get(p, P2P_NOTES_CACHE_META, "") or "").strip()
        try:
            notes = json.loads(raw_notes) if raw_notes else []
        except json.JSONDecodeError:
            notes = []
        if not isinstance(notes, list):
            notes = []
        return {"listings": listings, "notes": notes}


def _p2p_broker_save(data: dict, path: Path | None = None) -> None:
    p = path or DB_PATH
    with _p2p_broker_lock:
        p2p_listings_cache_save(p, [x for x in (data.get("listings") or []) if isinstance(x, dict)])
        try:
            app_meta_set(
                p,
                P2P_NOTES_CACHE_META,
                json.dumps(data.get("notes") or [], ensure_ascii=False)[:120_000],
            )
        except (TypeError, OSError):
            pass


def ionos_auth_headers(path: Path) -> dict[str, str]:
    """JWT + User-Agent für alle IONOS Desktop-API-Aufrufe."""
    headers = {"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"}
    tok = (app_meta_get(path, "ionos_jwt", "") or "").strip()
    if tok:
        headers["Authorization"] = f"Bearer {tok}"
    return headers


def pilot_handle(path: Path) -> str:
    return (
        app_meta_get(path, "pilot_display_name", "").strip()
        or app_meta_get(path, "pilot_name", "").strip()
        or "Pilot"
    ) or "Pilot"


def flight_log_aircraft_stats(path: Path, aircraft_model: str) -> tuple[int, int, float]:
    """Anzahl Landungen, harte Landungen (Zähler), Flugstunden (Log-Summe)."""
    conn = _conn(path)
    try:
        row = conn.execute(
            """
            SELECT COUNT(*), COALESCE(SUM(hard_landing), 0), COALESCE(SUM(duration_minutes), 0)
            FROM flight_log WHERE aircraft = ?;
            """,
            (aircraft_model,),
        ).fetchone()
        if not row:
            return 0, 0, 0.0
        return int(row[0] or 0), int(row[1] or 0), float(row[2] or 0.0) / 60.0
    finally:
        conn.close()


def tail_number_for_model(path: Path, model: str) -> str:
    k = f"cpo_tail_{model}"
    v = (app_meta_get(path, k, "") or "").strip().upper()
    if 4 <= len(v) <= 12:
        return v
    h = abs(hash(model)) % 90000 + 10000
    tail = f"D-ST{h}"
    app_meta_set(path, k, tail)
    return tail


def read_ccheck_hobbs_ref(path: Path, model: str) -> float | None:
    raw = (app_meta_get(path, f"ccheck_hobbs_hours_{model}", "") or "").strip()
    if not raw:
        return None
    try:
        return float(raw)
    except ValueError:
        return None


def record_ccheck_hobbs(path: Path, model: str) -> None:
    """Speichert Log-Stunden-Stand nach C-Check (z. B. volle Zellen-Wartung)."""
    _, _, hrs = flight_log_aircraft_stats(path, model)
    app_meta_set(path, f"ccheck_hobbs_hours_{model}", f"{hrs:.6f}")


def hours_since_last_ccheck(
    flight_hours: float, ccheck_hobbs_ref: float | None
) -> float | None:
    if ccheck_hobbs_ref is None:
        return None
    return max(0.0, float(flight_hours) - float(ccheck_hobbs_ref))


def delete_owned_aircraft(path: Path, model_name: str) -> None:
    m = (model_name or "").strip()
    if not m:
        return
    conn = _conn(path)
    try:
        sync_aircraft_parts_rows(conn)
        conn.execute("DELETE FROM aircraft_health WHERE model_name = ?;", (m,))
        conn.execute("DELETE FROM aircraft_parts WHERE model_name = ?;", (m,))
        conn.execute("DELETE FROM owned_aircraft WHERE model_name = ?;", (m,))
        conn.commit()
    finally:
        conn.close()


def insert_owned_aircraft_with_parts(
    path: Path,
    model_name: str,
    purchase_price: float,
    airframe_condition: float,
    parts: dict[str, float] | None,
) -> tuple[bool, str]:
    m = (model_name or "").strip()
    if not m:
        return False, "hangar.err.empty_model"
    conn = _conn(path)
    try:
        if conn.execute(
            "SELECT 1 FROM owned_aircraft WHERE model_name = ? LIMIT 1;", (m,)
        ).fetchone():
            return False, "hangar.err.duplicate_model"
        ac = max(0.0, min(100.0, float(airframe_condition)))
        conn.execute(
            "INSERT INTO owned_aircraft (model_name, condition, purchase_price) VALUES (?, ?, ?);",
            (m, ac, float(purchase_price)),
        )
        conn.commit()
    finally:
        conn.close()
    for code in PART_CODES:
        pv = 100.0
        if parts and code in parts:
            try:
                pv = float(parts[code])
            except (TypeError, ValueError):
                pv = 100.0
        set_part_condition(path, m, code, max(0.0, min(100.0, pv)))
    return True, ""


SPARE_PARTS_CATALOG: tuple[tuple[str, str, float], ...] = (
    ("CFM56-5B Fan Disk", "engine", 42_000.0),
    ("LEAP-1A HPT Blade Set", "engine", 58_000.0),
    ("PW1100G Combustor Liner", "engine", 51_000.0),
    ("IAE V2500 LPT Vane Pack", "engine", 36_000.0),
    ("Garmin G3000 MFD Unit", "avionics", 12_500.0),
    ("Honeywell EGPWS Module", "avionics", 8_900.0),
    ("Collins Pro Line FMS CPU", "avionics", 15_200.0),
    ("Thales Weather Radar Antenna", "avionics", 6_400.0),
    ("B737 Main Gear Actuator", "landing", 22_000.0),
    ("A320 NLG Steering Unit", "landing", 18_500.0),
    ("Carbon Brake Stack (4)", "landing", 14_800.0),
    ("Hydraulic Brake Valve Manifold", "landing", 9_200.0),
)


def fetch_ionos_spare_parts_market(path: Path) -> list[dict[str, object]] | None:
    base = ionos_api_base_url()
    if not base:
        return None
    try:
        r = requests.get(
            f"{base}/api/v1/market/spare-parts",
            timeout=25,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200:
            return None
        data = r.json()
        offers = data.get("offers") if isinstance(data, dict) else None
        if isinstance(offers, list):
            return [o for o in offers if isinstance(o, dict)]
    except Exception:
        return None
    return None


def spare_parts_market_rotation(path: Path) -> list[dict[str, object]]:
    """Täglich rotierende Ersatzteil-Liste (Verschleiß 0–100 %, Preis aus Basis + Zustand)."""
    if ionos_market_enabled(path) or ionos_api_base_url().strip():
        remote = fetch_ionos_spare_parts_market(path)
        if remote:
            return remote
    day = int(time.time() // 86_400)
    seed = day ^ (abs(hash(str(path.resolve()))) % 1_000_003)
    rng = random.Random(seed)
    picks = list(SPARE_PARTS_CATALOG)
    rng.shuffle(picks)
    picks = picks[: min(10, len(picks))]
    out: list[dict[str, object]] = []
    for idx, (name, category, base) in enumerate(picks):
        wear = round(rng.uniform(5.0, 95.0), 1)
        price = round(float(base) * (0.32 + (100.0 - wear) / 220.0), 0)
        out.append(
            {
                "id": f"SP-{day}-{idx}",
                "name": name,
                "category": category,
                "wear_pct": wear,
                "price": max(250.0, price),
            }
        )
    return out


def ionos_cloud_credentials(path: Path) -> tuple[str, str]:
    base = ionos_api_base_url().strip().rstrip("/")
    pw = cloud_password_get(path)
    return base, pw


def ionos_market_enabled(path: Path) -> bool:
    base, pw = ionos_cloud_credentials(path)
    return bool(base and pw)


def fetch_ionos_market_listings(path: Path) -> list[dict]:
    base, _pw = ionos_cloud_credentials(path)
    if not base:
        return []
    try:
        r = requests.get(
            f"{base}/api/v1/market/listings",
            timeout=28,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200 or not r.text.strip():
            return []
        data = r.json()
        lst = data.get("listings") if isinstance(data, dict) else data
        if not isinstance(lst, list):
            return []
        out: list[dict] = []
        for row in lst:
            if not isinstance(row, dict):
                continue
            norm = _normalize_cloud_row_to_local_p2p_listing(row)
            if norm:
                out.append(norm)
        return out
    except Exception:
        return []


def p2p_listings_cache_save(path: Path, listings: list[dict]) -> None:
    try:
        app_meta_set(
            path,
            P2P_LISTINGS_CACHE_META,
            json.dumps(listings, ensure_ascii=False)[:500_000],
        )
    except (TypeError, OSError):
        pass


def p2p_listings_cache_load(path: Path) -> list[dict]:
    raw = (app_meta_get(path, P2P_LISTINGS_CACHE_META, "") or "").strip()
    if not raw:
        return []
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return []
    if not isinstance(data, list):
        return []
    return [x for x in data if isinstance(x, dict)]


def sync_ionos_market_listings_into_local_broker(path: Path) -> tuple[bool, str]:
    """IONOS-Gebrauchtmarkt → app_meta-Cache (keine Broker-JSON bei aktivem Cloud-Markt)."""
    if not ionos_market_enabled(path):
        return False, "no_ionos"
    lst = fetch_ionos_market_listings(path)
    p2p_listings_cache_save(path, lst)
    if not lst:
        return True, "0"
    cloud_record_successful_server_contact(path)
    return True, f"{len(lst)}"


def p2p_reserve_listing_ionos(
    path: Path, listing_id: str, buyer_id: str
) -> tuple[bool, str]:
    base, pw = ionos_cloud_credentials(path)
    if not base or not pw:
        return False, "p2p.err.ionos_credentials"
    hid = p2p_hardware_id(path)
    body = {
        "hardware_id": hid,
        "password": pw,
        "buyer_id": (buyer_id or "").strip()[:120],
    }
    try:
        r = requests.post(
            f"{base}/api/v1/market/reserve/{quote(str(listing_id))}",
            json=body,
            timeout=25,
            headers=ionos_auth_headers(path),
        )
        j = r.json() if r.content else {}
    except Exception:
        return False, "p2p.err.ionos_unreachable"
    if r.status_code == 200 and isinstance(j, dict) and j.get("ok"):
        return True, ""
    err = str((j or {}).get("error", "reserve_failed"))
    if err == "reserved_other":
        return False, "p2p.err.reserved_other"
    return False, "p2p.err.listing_not_found" if err == "not_found" else err


def p2p_reserve_listing(path: Path, listing_id: str, buyer_id: str) -> tuple[bool, str]:
    if ionos_market_enabled(path):
        return p2p_reserve_listing_ionos(path, listing_id, buyer_id)
    return p2p_reserve_listing_local(path, listing_id, buyer_id)


def p2p_complete_purchase_ionos(
    path: Path, listing_id: str, buyer_id: str
) -> tuple[bool, str]:
    base, pw = ionos_cloud_credentials(path)
    if not base or not pw:
        return False, "p2p.err.ionos_credentials"
    hid = p2p_hardware_id(path)
    body = {
        "hardware_id": hid,
        "password": pw,
        "buyer_id": (buyer_id or "").strip()[:120],
    }
    try:
        r = requests.post(
            f"{base}/api/v1/market/buy/{quote(str(listing_id))}",
            json=body,
            timeout=45,
            headers=ionos_auth_headers(path),
        )
    except Exception:
        return False, "p2p.err.ionos_unreachable"
    try:
        j = r.json()
    except Exception:
        return False, "p2p.err.ionos_bad_response"
    if not isinstance(j, dict) or not j.get("ok"):
        err = str((j or {}).get("error", "purchase_failed"))
        if err == "insufficient_credits":
            return False, "p2p.err.buyer_credits"
        return False, "p2p.err.listing_not_found" if err == "not_found" else err
    raw = j.get("payload_json") or "{}"
    try:
        payload = json.loads(raw) if isinstance(raw, str) else raw
    except json.JSONDecodeError:
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    model = str(payload.get("model") or "")
    if not model:
        return False, "p2p.err.bad_model"
    parts = payload.get("parts") if isinstance(payload.get("parts"), dict) else {}
    af = float(payload.get("airframe_condition") or 90.0)
    price = float(payload.get("price") or 0)
    try:
        srv_cr = j.get("credits")
        if srv_cr is not None:
            conn = _conn(path)
            try:
                conn.execute(
                    "UPDATE pilot_stats SET credits = ? WHERE id = 1;",
                    (float(srv_cr),),
                )
                conn.commit()
            finally:
                conn.close()
            try:
                economy_sync_shadow(path)
            except Exception:
                pass
    except (TypeError, ValueError, sqlite3.Error):
        pass
    ok, err = insert_owned_aircraft_with_parts(path, model, price, af, parts)
    if not ok:
        return False, err
    fee = float(j.get("fee_credits") or 0)
    if fee > 0:
        add_total_market_fees(path, fee)
    cref = payload.get("ccheck_hobbs_ref")
    if cref is not None:
        try:
            app_meta_set(path, f"ccheck_hobbs_hours_{model}", str(float(cref)))
        except (TypeError, ValueError):
            pass
    return True, "p2p.ok.purchased"


def p2p_complete_purchase(path: Path, listing_id: str, buyer_id: str) -> tuple[bool, str]:
    if ionos_market_enabled(path):
        return p2p_complete_purchase_ionos(path, listing_id, buyer_id)
    return p2p_complete_purchase_local(path, listing_id, buyer_id)


def p2p_listings_read(path: Path) -> list[dict]:
    if ionos_market_enabled(path):
        ionos_lst = fetch_ionos_market_listings(path)
        if ionos_lst:
            p2p_listings_cache_save(path, ionos_lst)
            return ionos_lst
        cached = p2p_listings_cache_load(path)
        if cached:
            return cached
    if P2P_HTTP_BASE:
        try:
            r = requests.get(
                f"{P2P_HTTP_BASE}/listings",
                timeout=18,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            )
            r.raise_for_status()
            data = r.json()
            if isinstance(data, list):
                return data
            if isinstance(data, dict) and isinstance(data.get("listings"), list):
                return list(data["listings"])
        except Exception:
            return []
    d = _p2p_broker_load(path)
    return [x for x in (d.get("listings") or []) if isinstance(x, dict)]


def p2p_publish_listing_local(
    path: Path, model: str, price: float, seller_id: str
) -> tuple[bool, str]:
    """Nimmt Flugzeug aus dem Hangar und legt ein lokales Inserat (app_meta-Cache)."""
    if ionos_market_enabled(path):
        return p2p_publish_listing_ionos(path, model, price, seller_id)
    if P2P_HTTP_BASE:
        return False, "p2p.err.http_publish_unavailable"
    built, lid_or_err = _p2p_build_listing_payload(path, model, price, seller_id)
    if built is None:
        return False, lid_or_err
    listing = built
    lid = lid_or_err
    delete_owned_aircraft(path, model)
    d = _p2p_broker_load(path)
    d.setdefault("listings", []).append(listing)
    _p2p_broker_save(d, path)
    return True, lid


def _p2p_build_listing_payload(path: Path, model: str, price: float, seller_id: str) -> tuple[dict | None, str]:
    """Hängt Flugzeugdaten für Inserat zusammen (ohne Hangar-Löschung)."""
    seller_id = (seller_id or "").strip() or pilot_handle(path)
    info = get_aircraft_parts(path, model)
    parts_d = {k: float(v) for k, v in (info.get("parts") or {}).items()}
    conn = _conn(path)
    try:
        oc = conn.execute(
            "SELECT condition FROM owned_aircraft WHERE model_name = ?;", (model,)
        ).fetchone()
    finally:
        conn.close()
    if not oc:
        return None, "hangar.err.not_in_hangar"
    airframe = float(oc[0])
    n, hard, hrs = flight_log_aircraft_stats(path, model)
    tail = tail_number_for_model(path, model)
    cref = read_ccheck_hobbs_ref(path, model)
    lid = f"L-{uuid.uuid4().hex[:12].upper()}"
    listing = {
        "id": lid,
        "seller_id": seller_id,
        "model": model,
        "price": float(price),
        "parts": parts_d,
        "airframe_condition": airframe,
        "tail": tail,
        "ccheck_hobbs_ref": cref,
        "stats": {"landings": n, "hard_landings": hard, "flight_hours": round(hrs, 2)},
        "reserved_until": 0.0,
        "reserved_by": "",
    }
    return listing, lid


def p2p_publish_listing_ionos(
    path: Path, model: str, price: float, seller_id: str
) -> tuple[bool, str]:
    """Meilenstein 174: Inserat direkt auf IONOS (``POST /api/v1/market/list``)."""
    if not ionos_market_enabled(path):
        return False, "p2p.err.ionos_credentials"
    built, lid_or_err = _p2p_build_listing_payload(path, model, price, seller_id)
    if built is None:
        return False, lid_or_err
    listing = built
    lid = lid_or_err
    base, pw = ionos_cloud_credentials(path)
    hid = p2p_hardware_id(path)
    body = {
        "hardware_id": hid,
        "password": pw,
        "listing_id": lid,
        "seller_id": listing["seller_id"],
        "price_credits": float(price),
        "payload": {
            "model": listing["model"],
            "parts": listing["parts"],
            "airframe_condition": listing["airframe_condition"],
            "tail": listing["tail"],
            "ccheck_hobbs_ref": listing["ccheck_hobbs_ref"],
            "stats": listing["stats"],
        },
    }
    try:
        r = requests.post(
            f"{base}/api/v1/market/list",
            json=body,
            timeout=45,
            headers=ionos_auth_headers(path),
        )
        j = r.json() if r.content else {}
    except Exception:
        return False, "p2p.err.ionos_unreachable"
    if r.status_code != 200 or not isinstance(j, dict) or not j.get("ok"):
        err = str((j or {}).get("error", "publish_failed"))
        return False, err
    delete_owned_aircraft(path, model)
    sync_ionos_market_listings_into_local_broker(path)
    return True, str(j.get("listing_id", lid))


def p2p_withdraw_listing_local(
    path: Path, listing_id: str, seller_id: str
) -> tuple[bool, str]:
    """Eigenes Inserat zurückziehen: Eintrag aus Broker entfernen, Flugzeug wieder in den Hangar."""
    if P2P_HTTP_BASE:
        return False, "p2p.err.http_withdraw_unavailable"
    sid = (seller_id or "").strip()
    if not sid:
        return False, "p2p.err.bad_seller"
    lid = str(listing_id or "").strip()
    if not lid:
        return False, "p2p.err.listing_not_found"
    d = _p2p_broker_load(path)
    listings = [x for x in (d.get("listings") or []) if isinstance(x, dict)]
    chosen: dict | None = None
    rest: list[dict] = []
    for L in listings:
        if str(L.get("id")) == lid:
            chosen = L
        else:
            rest.append(L)
    if chosen is None:
        return False, "p2p.err.listing_not_found"
    if str(chosen.get("seller_id") or "") != sid:
        return False, "p2p.err.not_seller"
    now = time.time()
    ru = float(chosen.get("reserved_until") or 0)
    rb = str(chosen.get("reserved_by") or "")
    if ru > now and rb and rb != sid:
        return False, "p2p.err.cannot_withdraw_reserved"
    model = str(chosen.get("model") or "").strip()
    if not model:
        return False, "p2p.err.bad_model"
    rawp = chosen.get("parts")
    parts: dict[str, float] = {}
    if isinstance(rawp, dict):
        for k, v in rawp.items():
            try:
                parts[str(k)] = float(v)
            except (TypeError, ValueError):
                parts[str(k)] = 100.0
    af = float(chosen.get("airframe_condition") or 90.0)
    ok, err = insert_owned_aircraft_with_parts(path, model, 0.0, af, parts)
    if not ok:
        return False, err
    cref = chosen.get("ccheck_hobbs_ref")
    if cref is not None:
        try:
            app_meta_set(path, f"ccheck_hobbs_hours_{model}", str(float(cref)))
        except (TypeError, ValueError):
            pass
    try:
        economy_sync_shadow(path)
    except Exception:
        pass
    d["listings"] = rest
    _p2p_broker_save(d, path)
    return True, "p2p.ok.withdrawn"


def p2p_reserve_listing_local(path: Path, listing_id: str, buyer_id: str) -> tuple[bool, str]:
    d = _p2p_broker_load(path)
    now = time.time()
    for L in d.get("listings") or []:
        if str(L.get("id")) != str(listing_id):
            continue
        ru = float(L.get("reserved_until") or 0)
        rb = str(L.get("reserved_by") or "")
        if ru > now and rb and rb != buyer_id:
            return False, "p2p.err.reserved_other"
        L["reserved_until"] = now + float(P2P_RESERVE_SECONDS)
        L["reserved_by"] = buyer_id
        _p2p_broker_save(d, path)
        return True, ""
    return False, "p2p.err.listing_not_found"


def p2p_complete_purchase_local(path: Path, listing_id: str, buyer_id: str) -> tuple[bool, str]:
    d = _p2p_broker_load(path)
    now = time.time()
    listings = [x for x in (d.get("listings") or []) if isinstance(x, dict)]
    chosen: dict | None = None
    rest: list[dict] = []
    for L in listings:
        if str(L.get("id")) == str(listing_id):
            chosen = L
        else:
            rest.append(L)
    if chosen is None:
        return False, "p2p.err.listing_not_found"
    if str(chosen.get("reserved_by") or "") != str(buyer_id):
        return False, "p2p.err.no_active_reservation"
    if float(chosen.get("reserved_until") or 0) < now:
        return False, "p2p.err.reservation_expired"
    price = float(chosen.get("price") or 0)
    model = str(chosen.get("model") or "")
    seller = str(chosen.get("seller_id") or "")
    if seller == buyer_id:
        return False, "p2p.err.self_listing"
    cr = load_credits(path)
    if cr < price:
        return False, "p2p.err.buyer_credits"
    parts = chosen.get("parts")
    if not isinstance(parts, dict):
        parts = {}
    af = float(chosen.get("airframe_condition") or 90.0)
    fee = price * P2P_MARKET_FEE_FRACTION
    seller_payout = price * P2P_SELLER_FRACTION
    conn = _conn(path)
    try:
        conn.execute(
            "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;", (price,)
        )
        conn.commit()
    finally:
        conn.close()
    try:
        economy_sync_shadow(path)
    except Exception:
        pass
    ok, err = insert_owned_aircraft_with_parts(path, model, price, af, parts)
    if not ok:
        add_credits(path, price)
        return False, err
    add_total_market_fees(path, fee)
    cref = chosen.get("ccheck_hobbs_ref")
    if cref is not None:
        try:
            app_meta_set(path, f"ccheck_hobbs_hours_{model}", str(float(cref)))
        except (TypeError, ValueError):
            pass
    d["listings"] = rest
    d.setdefault("notes", []).append(
        {
            "to": seller,
            "kind": "sold",
            "model": model,
            "price": seller_payout,
            "buyer": buyer_id,
            "ts": now,
            "fee": fee,
        }
    )
    _p2p_broker_save(d, path)
    return True, "p2p.ok.purchased"


def p2p_credit_seller_and_drain_notes(path: Path, seller_id: str) -> list[str]:
    """Zahlt verkündete Verkäufe an den lokalen Verkäufer gut (Credits) und entfernt Notes."""
    me = (seller_id or "").strip()
    if not me:
        return []
    d = _p2p_broker_load(path)
    notes = d.get("notes") or []
    keep: list[dict] = []
    msgs: list[str] = []
    for n in notes:
        if not isinstance(n, dict):
            continue
        if str(n.get("to")) != me or str(n.get("kind")) != "sold":
            keep.append(n)
            continue
        price = float(n.get("price") or 0)
        if price > 0:
            add_credits(path, price)
        buyer = str(n.get("buyer") or "?")
        model = str(n.get("model") or "?")
        msgs.append(
            i18n_db(
                path,
                "p2p.seller_sold_body",
                "Verkauf: {model} an {buyer} für {price} (Gutschrift erfolgt).",
            ).format(
                model=model,
                price=format_eur_de(price),
                buyer=buyer,
            )
        )
    if len(keep) != len(notes):
        d["notes"] = keep
        _p2p_broker_save(d, path)
    return msgs


def firebase_p2p_base_url() -> str:
    """Legacy Firebase RTDB — deaktiviert wenn IONOS-API konfiguriert ist."""
    if (os.environ.get("SKYTYCOON_IONOS_API_BASE") or os.environ.get("SKYTYCOON_IONOS_SERVER_URL") or "").strip():
        return ""
    if (IONOS_FALLBACK_SERVER_URL or "").strip():
        return ""
    return (os.environ.get("MSFS_SKYTYCOON_FIREBASE_URL", "") or "").strip().rstrip("/")


def firebase_sibling_json_url(base_json_url: str, sibling_name: str) -> str:
    """Leitet z. B. …/listings.json → …/version.json ab."""
    b = (base_json_url or "").strip().rstrip("/")
    if not b:
        return ""
    if not b.lower().endswith(".json"):
        return f"{b}/{sibling_name}"
    pref, _, _ = b.rpartition("/")
    return f"{pref}/{sibling_name}" if pref else sibling_name


def _cloud_listings_json_url() -> str:
    fb = firebase_p2p_base_url()
    if not fb:
        return ""
    return fb if fb.lower().endswith(".json") else f"{fb}/listings.json"


def _cloud_global_config_url() -> str:
    """Gegenstück zu Admin/Firebase: …/global_config.json (update, events, banned_users)."""
    u = (os.environ.get("MSFS_SKYTYCOON_GLOBAL_CONFIG_URL") or "").strip()
    if u:
        return u
    listings = _cloud_listings_json_url()
    if not listings:
        return ""
    return firebase_sibling_json_url(listings, "global_config.json")


def _cloud_banned_users_map_url() -> str:
    """Map hardware_id → true (wie /banned_users/{id}); Datei banned_users.json neben listings."""
    u = (os.environ.get("MSFS_SKYTYCOON_BANNED_USERS_URL") or "").strip()
    if u:
        return u
    listings = _cloud_listings_json_url()
    if not listings:
        return ""
    return firebase_sibling_json_url(listings, "banned_users.json")


def _cloud_bans_json_url() -> str:
    u = (os.environ.get("MSFS_SKYTYCOON_BANS_URL") or "").strip()
    if u:
        return u
    listings = _cloud_listings_json_url()
    if not listings:
        return ""
    return firebase_sibling_json_url(listings, "bans.json")


def cloud_record_successful_server_contact(path: Path) -> None:
    """Erfolgreicher Cloud-Reach (Anti-Cheat: >3 Tage offline bei konfiguriertem Firebase)."""
    try:
        app_meta_set(path, "cloud_last_server_contact_unix", str(time.time()))
        app_meta_set(path, "cloud_ever_synced_ok", "1")
    except OSError:
        pass


def _truthy_server_ban(v: object) -> bool:
    if v is True:
        return True
    if isinstance(v, (int, float)) and v != 0:
        return bool(v)
    s = str(v).strip().lower()
    return s in ("true", "1", "yes", "banned", "gesperrt")


def _hardware_banned_in_users_map(data: object, hw: str) -> bool:
    if not hw or not isinstance(data, dict):
        return False
    v = data.get(hw)
    if v is None and hw in data:
        v = data[hw]
    return _truthy_server_ban(v)


def is_offline_cloud_stale_blocked(path: Path) -> tuple[bool, str]:
    """Nach mindestens einem erfolgreichen Sync: >72h ohne Server → Start sperren (wenn Firebase-URL gesetzt)."""
    if not firebase_p2p_base_url():
        return False, ""
    if app_meta_get(path, "cloud_ever_synced_ok", "0").strip() != "1":
        return False, ""
    try:
        last = float(app_meta_get(path, "cloud_last_server_contact_unix", "0") or 0.0)
    except ValueError:
        last = 0.0
    if last <= 0:
        return False, ""
    if time.time() - last > 3.0 * 86400.0:
        return True, i18n_db(
            path,
            "security.offline_stale_block",
            "SkyTycoon Pro: Mehr als 3 Tage keine Verbindung zum Betreiber-Server. "
            "Start aus Sicherheitsgründen gesperrt – bitte kurz online gehen und neu starten.",
        )
    return False, ""


def is_launch_blocked_by_cloud_or_license(
    path: Path, global_cfg: dict | None = None
) -> tuple[bool, str]:
    ban_msg = i18n_db(
        path,
        "security.license_revoked",
        "Zugriff verweigert. Diese Lizenz wurde vom Administrator gesperrt.",
    )
    if path.is_file():
        lo = (app_meta_get(path, "license_status_override", "") or "").strip().lower()
        if lo in ("gesperrt", "banned", "sperre"):
            return True, ban_msg
    hw = p2p_hardware_id(path)
    if global_cfg and isinstance(global_cfg.get("banned_users"), dict):
        if _hardware_banned_in_users_map(global_cfg["banned_users"], hw):
            return True, ban_msg
    url = _cloud_bans_json_url()
    if url:
        try:
            r = requests.get(
                url,
                timeout=8,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            )
            if r.status_code == 200 and r.text.strip():
                cloud_record_successful_server_contact(path)
                data = r.json()
                if isinstance(data, dict):
                    blocked = data.get("blocked") or data.get("banned_hwids") or []
                    if isinstance(blocked, list) and hw and hw in [str(x) for x in blocked]:
                        return True, ban_msg
        except Exception:
            pass
    bu = _cloud_banned_users_map_url()
    if bu and hw:
        try:
            r2 = requests.get(
                bu,
                timeout=8,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            )
            if r2.status_code == 200 and r2.text.strip():
                cloud_record_successful_server_contact(path)
                m = r2.json()
                if isinstance(m, dict) and _hardware_banned_in_users_map(m, hw):
                    return True, ban_msg
        except Exception:
            pass
    return False, ""


_cloud_glob: dict[str, float] = {"fuel": 1.0, "emerg": 1.0, "ts": 0.0}


def _cloud_global_econ_url() -> str:
    u = (os.environ.get("MSFS_SKYTYCOON_GLOBAL_URL") or "").strip()
    if u:
        return u
    listings = _cloud_listings_json_url()
    if not listings:
        return ""
    return firebase_sibling_json_url(listings, "global_econ.json")


def cloud_global_econ_bundle(*, force_refresh: bool = False) -> tuple[float, float]:
    """(fuel_price_mult, maintenance_fault_mult) aus global_econ.json; Standard-TTL 90 s."""
    global _cloud_glob
    url = _cloud_global_econ_url()
    if not url:
        return (1.0, 1.0)
    now = time.time()
    ts = float(_cloud_glob.get("ts") or 0.0)
    if (
        not force_refresh
        and ts > 0.0
        and (now - ts) < 90.0
    ):
        return (
            max(0.15, min(6.0, float(_cloud_glob.get("fuel") or 1.0))),
            max(0.25, min(5.0, float(_cloud_glob.get("emerg") or 1.0))),
        )
    try:
        r = requests.get(
            url,
            timeout=7,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code == 200 and r.text.strip():
            j = r.json()
            if isinstance(j, dict):
                v = float(j.get("fuel_mult", 1.0) or 1.0)
                v = max(0.15, min(6.0, v))
                ep = float(j.get("emergency_prob", 0) or 0)
                emerg = 1.0 + min(4.0, ep * 80.0)
                emerg = max(0.25, min(5.0, emerg))
                _cloud_glob = {"fuel": v, "emerg": emerg, "ts": now}
                try:
                    cloud_record_successful_server_contact(DB_PATH)
                except Exception:
                    pass
                return (v, emerg)
    except Exception:
        pass
    _cloud_glob["ts"] = now
    return (
        max(0.15, min(6.0, float(_cloud_glob.get("fuel") or 1.0))),
        max(0.25, min(5.0, float(_cloud_glob.get("emerg") or 1.0))),
    )


def cloud_global_fuel_price_mult() -> float:
    """Server-globaler Sprit-Multiplikator (global_econ.json), gecacht."""
    return cloud_global_econ_bundle(force_refresh=False)[0]


def cloud_global_maintenance_fault_mult() -> float:
    """Skaliert SimConnect-Wartungs-Störungen (emergency_prob in global_econ.json)."""
    return cloud_global_econ_bundle(force_refresh=False)[1]


def _normalize_cloud_row_to_local_p2p_listing(row: dict) -> dict | None:
    if not isinstance(row, dict):
        return None
    lid = str(row.get("id") or "").strip()
    model = str(row.get("model") or "").strip()
    if not lid or not model:
        return None
    seller = (
        str(row.get("seller_id") or row.get("seller_name") or "").strip()
        or "unknown"
    )
    try:
        price = float(row.get("price") or 0)
    except (TypeError, ValueError):
        price = 0.0
    cj = row.get("condition_json")
    if isinstance(cj, dict):
        try:
            af = float(cj.get("airframe", row.get("airframe_condition", 100)))
        except (TypeError, ValueError):
            af = 100.0
        parts_raw = cj.get("parts")
    else:
        try:
            af = float(row.get("airframe_condition", 100))
        except (TypeError, ValueError):
            af = 100.0
        parts_raw = row.get("parts")
    parts_d: dict[str, float] = {}
    if isinstance(parts_raw, dict):
        for k, v in parts_raw.items():
            try:
                parts_d[str(k)] = float(v)
            except (TypeError, ValueError):
                pass
    cref_raw = row.get("ccheck_hobbs_ref")
    cref: float | None = None
    if cref_raw is not None and cref_raw != "":
        try:
            cref = float(cref_raw)
        except (TypeError, ValueError):
            cref = None
    stats = row.get("stats")
    if not isinstance(stats, dict):
        stats = {}
    tail = str(row.get("tail") or "").strip()
    if not tail:
        tail = f"CLD-{lid[-8:].upper()}"
    try:
        ru = float(row.get("reserved_until") or 0)
    except (TypeError, ValueError):
        ru = 0.0
    rb = str(row.get("reserved_by") or "")
    return {
        "id": lid,
        "seller_id": seller,
        "model": model,
        "price": price,
        "parts": parts_d,
        "airframe_condition": max(0.0, min(100.0, af)),
        "tail": tail,
        "ccheck_hobbs_ref": cref,
        "stats": stats,
        "reserved_until": ru,
        "reserved_by": rb,
    }


def sync_firebase_listings_into_local_broker(path: Path) -> tuple[bool, str]:
    """Holt listings.json von Firebase und ersetzt lokale Broker-Inserate (Admin-Löschungen sichtbar)."""
    if P2P_HTTP_BASE:
        return False, "http_p2p"
    url = _cloud_listings_json_url()
    if not url:
        return False, "no_firebase"
    try:
        r = requests.get(
            url,
            timeout=12,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200:
            return False, f"http_{r.status_code}"
        data = r.json() if r.text.strip() else {}
        lst = data.get("listings")
        if not isinstance(lst, list):
            lst = data if isinstance(data, list) else []
        norm: list[dict] = []
        for x in lst:
            e = _normalize_cloud_row_to_local_p2p_listing(x) if isinstance(x, dict) else None
            if e:
                norm.append(e)
        d = _p2p_broker_load(path)
        d["listings"] = norm
        _p2p_broker_save(d, path)
        cloud_record_successful_server_contact(path)
        return True, f"{len(norm)}"
    except Exception as ex:
        return False, str(ex)


def fetch_market_listings(path: Path) -> bool:
    """Cloud-Markt: Inserate neu laden (IONOS oder Firebase → lokale Börse)."""
    if ionos_market_enabled(path):
        ok, _ = sync_ionos_market_listings_into_local_broker(path)
        return ok
    ok, _ = sync_firebase_listings_into_local_broker(path)
    return ok


def _http_get_json_dict(url: str, timeout: float = 10.0) -> dict | None:
    try:
        r = requests.get(
            url,
            timeout=timeout,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200 or not r.text.strip():
            return None
        j = r.json()
        return j if isinstance(j, dict) else None
    except Exception:
        return None


def _load_cached_global_config(path: Path) -> dict:
    cached = (app_meta_get(path, "cloud_global_config_json", "") or "").strip()
    if not cached:
        return {}
    try:
        c = json.loads(cached)
        return c if isinstance(c, dict) else {}
    except json.JSONDecodeError:
        return {}


def fetch_global_config_merged(path: Path, *, network: bool = True) -> dict:
    """global_config.json laden; bei Netzfehler letzte Session aus app_meta."""
    cached = _load_cached_global_config(path)
    if cached and network:
        try:
            fetched = float(
                app_meta_get(path, "cloud_global_config_fetched_unix", "0") or 0
            )
        except ValueError:
            fetched = 0.0
        if fetched > 0 and (time.time() - fetched) < GLOBAL_CONFIG_CACHE_TTL_SEC:
            return cached
    if cached and not network:
        return cached
    url = _cloud_global_config_url()
    if url and network:
        raw = _http_get_json_dict(url, timeout=8.0)
        if raw:
            try:
                app_meta_set(
                    path,
                    "cloud_global_config_json",
                    json.dumps(raw, ensure_ascii=False),
                )
            except OSError:
                pass
            cloud_record_successful_server_contact(path)
            try:
                app_meta_set(
                    path, "cloud_global_config_fetched_unix", str(time.time())
                )
            except OSError:
                pass
            return raw
    return cached


def apply_global_config_cloud_to_meta(path: Path, cfg: dict) -> None:
    """active_event + events (Sprit) → app_meta cloud_active_event_fuel_mult."""
    mult = 1.0
    ae = cfg.get("active_event")
    if isinstance(ae, dict):
        t = str(ae.get("type", "")).lower()
        for cand in (
            ae.get("fuel_mult"),
            ae.get("kerosene_mult"),
            ae.get("multiplier"),
        ):
            if cand is None:
                continue
            try:
                fm = float(cand)
            except (TypeError, ValueError):
                continue
            if not t or t in (
                "fuel_crisis",
                "spritkrise",
                "spritmangel",
                "kerosene",
                "fuel",
            ):
                mult *= max(0.05, min(3.5, fm))
            break
    evroot = cfg.get("events")
    if isinstance(evroot, dict):
        for _name, ev in evroot.items():
            if not isinstance(ev, dict):
                continue
            if ev.get("active") is not True:
                continue
            fm = ev.get("fuel_mult") or ev.get("kerosene_mult") or ev.get("multiplier")
            if fm is None:
                continue
            try:
                mult *= max(0.05, min(3.5, float(fm)))
            except (TypeError, ValueError):
                pass
    try:
        app_meta_set(path, "cloud_active_event_fuel_mult", f"{max(0.1, min(4.0, mult)):.6f}")
    except OSError:
        pass
    try:
        ma = cfg.get("maintenance_active")
        if ma is True or str(ma).lower() in ("1", "true", "yes", "on"):
            app_meta_set(path, "cloud_maintenance_active", "1")
        elif ma is False or str(ma).lower() in ("0", "false", "no", "off"):
            app_meta_set(path, "cloud_maintenance_active", "0")
    except OSError:
        pass


def _version_tuple_for_compare(ver: str) -> tuple[int, ...]:
    s = (ver or "").strip().split("-")[0].split("+")[0].strip()
    out: list[int] = []
    for seg in s.split("."):
        digits = "".join(ch for ch in seg if ch.isdigit())
        out.append(int(digits)) if digits else out.append(0)
    return tuple(out) or (0,)


def version_remote_is_newer(remote: str, local: str) -> bool:
    return _version_tuple_for_compare(remote) > _version_tuple_for_compare(local)


def _version_cmp_label(s: str) -> str:
    return (s or "").strip().split("-")[0].split("+")[0].strip().lower()


def version_strings_differ_for_update_prompt(remote: str, local: str) -> bool:
    """MS109: Remote- und Local-Version unterscheiden sich (Basis ohne Suffix wie -GOLD)."""
    r = _version_cmp_label(remote)
    l = _version_cmp_label(local)
    return bool(r) and r != l


def _merge_version_info_for_startup(
    path: Path, global_cfg: dict
) -> tuple[str, str, str, bool, str]:
    upd = global_cfg.get("update")
    upd = upd if isinstance(upd, dict) else {}
    lv = str(upd.get("latest_version") or upd.get("version") or "").strip()
    changelog = str(upd.get("changelog") or "").strip()
    dl = str(upd.get("download_url") or upd.get("url") or "").strip()
    allow = upd.get("allow_skip", True)
    allow_skip = allow is not False and str(allow).lower() not in ("0", "false", "no")
    mandatory = upd.get("mandatory") is True or str(upd.get("mandatory", "")).lower() in (
        "1",
        "true",
        "yes",
    )
    min_v = str(upd.get("min_version") or "").strip()
    if min_v and version_remote_is_newer(min_v, APP_VERSION):
        allow_skip = False
    vu = effective_update_version_url().strip()
    if vu:
        vj = _http_get_json_dict(vu, timeout=9.0)
        if isinstance(vj, dict):
            if not lv:
                lv = str(vj.get("version") or "").strip()
            if not dl:
                dl = str(vj.get("url") or "").strip()
            if not changelog:
                changelog = str(vj.get("changelog") or "").strip()
            if vj.get("mandatory") is True or str(vj.get("mandatory", "")).lower() in (
                "1",
                "true",
                "yes",
            ):
                mandatory = True
            if str(vj.get("release_channel", "") or "").strip().lower() == "beta":
                beta_url = firebase_sibling_json_url(vu, "beta_testers.json")
                bm = _http_get_json_dict(beta_url, timeout=7.0) if beta_url else None
                hid = p2p_hardware_id(path)
                ok = False
                if isinstance(bm, dict):
                    if hid in bm or str(bm.get(hid, "")).lower() in ("1", "true", "yes"):
                        ok = True
                    if not ok:
                        for k in ("ids", "beta_hwids", "hardware_ids", "hwids"):
                            ent = bm.get(k)
                            if isinstance(ent, dict) and hid in ent:
                                ok = True
                                break
                            if isinstance(ent, list) and hid in [str(x) for x in ent]:
                                ok = True
                                break
                if not ok:
                    lv = ""
                    changelog = ""
                    dl = ""
    if mandatory:
        allow_skip = False
    vcmp = str(upd.get("version_compare", "unequal") or "unequal").lower()
    return lv, changelog, dl, allow_skip, vcmp


def run_startup_update_gate(path: Path, parent: QWidget | None, global_cfg: dict) -> bool:
    """True = Hauptfenster laden; False = Abbruch (Update erzwungen / Nutzer beendet)."""
    lv, changelog, dl, allow_skip, vcmp = _merge_version_info_for_startup(path, global_cfg)
    needs_prompt = False
    if lv:
        if vcmp in ("newer", "newer_only"):
            needs_prompt = version_remote_is_newer(lv, APP_VERSION)
        else:
            needs_prompt = version_strings_differ_for_update_prompt(lv, APP_VERSION)
    if not needs_prompt:
        return True
    dlg = QDialog(parent)
    dlg.setWindowTitle(i18n_db(path, "update.available_title", "Update verfügbar"))
    dlg.setWindowModality(Qt.WindowModality.ApplicationModal)
    dlg.setMinimumWidth(520)
    lay = QVBoxLayout(dlg)
    lay.addWidget(
        QLabel(
            i18n_db(
                path,
                "update.body_fmt",
                "Neue Version: {remote}\nInstalliert: {local}",
            ).format(remote=lv, local=APP_VERSION)
        )
    )
    te = QTextEdit()
    te.setReadOnly(True)
    te.setPlainText(
        changelog or i18n_db(path, "update.no_changelog", "(Kein Changelog.)")
    )
    te.setMinimumHeight(200)
    lay.addWidget(te)
    row = QHBoxLayout()
    b_dl = QPushButton(i18n_db(path, "update.btn_download", "Jetzt herunterladen"))
    if dl:
        b_dl.clicked.connect(lambda: QDesktopServices.openUrl(QUrl(dl)))
    else:
        b_dl.setEnabled(False)
    row.addWidget(b_dl)
    b_skip = QPushButton(i18n_db(path, "update.btn_skip", "Später fortfahren"))
    b_skip.clicked.connect(dlg.accept)
    if not allow_skip:
        b_skip.setVisible(False)
    row.addWidget(b_skip)
    b_ex = QPushButton(i18n_db(path, "update.btn_exit", "Beenden"))
    b_ex.clicked.connect(dlg.reject)
    row.addWidget(b_ex)
    lay.addLayout(row)
    return dlg.exec() == QDialog.DialogCode.Accepted


def check_for_updates(
    path: Path, parent: QWidget | None, global_cfg: dict | None = None
) -> bool:
    """
    Meilenstein 109 / Pre-Launch: liest ``global_config`` → ``update`` (und ergänzend
    ``version.json``), zeigt bei abweichender Admin-``latest_version`` ein blockierendes
    Fenster. Standard: Versionen **ungleich** (Basis-Label ohne Suffix); in ``update`` kann
    ``\"version_compare\": \"newer_only\"`` gesetzt werden (nur strikt neuere Remote-Version).
    """
    cfg = global_cfg if global_cfg is not None else fetch_global_config_merged(path)
    return run_startup_update_gate(path, parent, cfg)


def deferred_startup_cloud_refresh(path: Path) -> None:
    """Nach sichtbarem Cockpit: global_config + Wirtschaft im Hintergrund."""

    def _work() -> None:
        try:
            cfg = fetch_global_config_merged(path, network=True)
            apply_global_config_cloud_to_meta(path, cfg)
        except Exception:
            pass

    QThreadPool.globalInstance().start(HeavyTaskWorker(_work))


def run_startup_cloud_security_and_updates(
    path: Path, parent: QWidget | None, *, network: bool = True
) -> tuple[bool, str]:
    """Pre-Launch: global_config, Bann, Offline-Fenster, Update-Dialog."""
    cfg = fetch_global_config_merged(path, network=network)
    apply_global_config_cloud_to_meta(path, cfg)
    blocked, msg = is_launch_blocked_by_cloud_or_license(path, cfg)
    if blocked:
        return False, msg
    stale_b, stale_m = is_offline_cloud_stale_blocked(path)
    if stale_b:
        return False, stale_m
    if not check_for_updates(path, parent, cfg):
        return False, i18n_db(
            path,
            "update.aborted",
            "Start abgebrochen (Update erforderlich oder beendet).",
        )
    return True, ""


def read_windows_machine_uuid() -> str:
    """Windows 10/11: offizielle Hardware-UUID via Get-CimInstance (ersetzt wmic)."""
    if sys.platform != "win32":
        return ""
    try:
        import subprocess

        proc = subprocess.run(
            [
                "powershell",
                "-NoProfile",
                "-Command",
                "(Get-CimInstance Win32_ComputerSystemProduct).UUID",
            ],
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
        if proc.returncode != 0:
            return ""
        raw = (proc.stdout or "").strip()
        if not raw or raw.lower() in ("uuid", "ffffffff-ffff-ffff-ffff-ffffffffffff"):
            return ""
        return raw.upper()[:64]
    except (OSError, subprocess.SubprocessError, ValueError):
        return ""


def ensure_ionos_hardware_id_from_os(path: Path) -> str:
    """Bindet die echte Windows-UUID, falls noch keine IONOS-ID gesetzt ist."""
    bound = (app_meta_get(path, IONOS_HW_ID_KEY, "") or "").strip()
    if bound and bound != "unknown" and not bound.startswith("web-"):
        return bound[:64]
    win_uuid = read_windows_machine_uuid()
    if win_uuid:
        ionos_bind_hardware_id(path, win_uuid)
        return win_uuid[:64]
    return bound[:64] if bound else ""


def p2p_hardware_id(path: Path) -> str:
    ensure_ionos_hardware_id_from_os(path)
    bound = (app_meta_get(path, IONOS_HW_ID_KEY, "") or "").strip()
    if bound and bound != "unknown":
        return bound[:64]
    tag = (app_meta_get(path, "econ_device_tag", "") or "").strip()
    if not tag:
        tag = uuid.uuid4().hex
        app_meta_set(path, "econ_device_tag", tag)
    return tag[:64]


def _p2p_listings_payload_for_cloud(path: Path) -> list[dict]:
    out: list[dict] = []
    for L in p2p_listings_read(path):
        out.append(
            {
                "id": L.get("id"),
                "model": L.get("model"),
                "price": L.get("price"),
                "seller_name": str(L.get("seller_id") or ""),
                "hardware_id": p2p_hardware_id(path),
                "condition_json": {
                    "airframe": L.get("airframe_condition"),
                    "parts": L.get("parts"),
                },
            }
        )
    return out


def _on_p2p_fb_upload_finished(win: object, reply: QNetworkReply) -> None:
    reply.deleteLater()
    err = reply.error()
    try:
        if err != QNetworkReply.NetworkError.NoError:
            QMessageBox.warning(
                win,
                win._tr("bank.firebase_title", "Cloud-P2P"),
                win._tr(
                    "bank.firebase_err",
                    "Upload fehlgeschlagen (Netzwerk).",
                ),
            )
        else:
            QMessageBox.information(
                win,
                win._tr("bank.firebase_title", "Cloud-P2P"),
                win._tr("bank.firebase_ok_upload", "Inserate an Cloud gesendet."),
            )
    except Exception:
        pass


def sync_market_to_firebase_nam(win: object, base: str) -> None:
    nam = getattr(win, "_nam", None)
    if nam is None:
        return
    listings = _p2p_listings_payload_for_cloud(DB_PATH)
    url = base if base.lower().endswith(".json") else f"{base}/listings.json"
    body = json.dumps({"listings": listings}, ensure_ascii=False).encode("utf-8")
    req = QNetworkRequest(QUrl(url))
    req.setHeader(
        QNetworkRequest.KnownHeaders.ContentTypeHeader,
        "application/json; charset=utf-8",
    )
    rep = nam.post(req, QByteArray(body))
    rep.finished.connect(partial(_on_p2p_fb_upload_finished, win, rep))


def _on_p2p_fb_download_finished(
    win: object, reply: QNetworkReply, preview_only: bool
) -> None:
    reply.deleteLater()
    if reply.error() != QNetworkReply.NetworkError.NoError:
        try:
            QMessageBox.warning(
                win,
                win._tr("bank.firebase_title", "Cloud-P2P"),
                win._tr("bank.firebase_err_dl", "Download fehlgeschlagen."),
            )
        except Exception:
            pass
        return
    try:
        raw = bytes(reply.readAll()).decode("utf-8", errors="replace")
        data = json.loads(raw) if raw.strip() else {}
        lst = data.get("listings")
        if not isinstance(lst, list):
            lst = data if isinstance(data, list) else []
        n = len([x for x in lst if isinstance(x, dict)])
        QMessageBox.information(
            win,
            win._tr("bank.firebase_title", "Cloud-P2P"),
            win._tr(
                "bank.firebase_pull_ok",
                "Cloud enthält {n} Inserate (nur Vorschau / kein Merge).",
            ).format(n=n),
        )
        if not preview_only and n > 0:
            pass
    except Exception:
        QMessageBox.warning(
            win,
            win._tr("bank.firebase_title", "Cloud-P2P"),
            win._tr("bank.firebase_parse", "Antwort konnte nicht gelesen werden."),
        )


def purchase_from_firebase_nam(win: object, base: str, *, preview_only: bool) -> None:
    nam = getattr(win, "_nam", None)
    if nam is None:
        return
    url = base if base.lower().endswith(".json") else f"{base}/listings.json"
    req = QNetworkRequest(QUrl(url))
    rep = nam.get(req)
    rep.finished.connect(
        partial(_on_p2p_fb_download_finished, win, rep, preview_only)
    )


def _draw_cpo_certificate_core(
    dr: object,
    font_title: object,
    font_h: object,
    font_b: object,
    *,
    model: str,
    tail: str,
    purchase: float,
    airframe: float,
    parts: dict[str, float],
    n_ldg: int,
    n_hard: int,
    hrs: float,
    ccheck_hobbs_ref: float | None,
    lang_de: bool,
) -> None:
    w, h = 920, 640
    cref = ccheck_hobbs_ref
    h_since = hours_since_last_ccheck(hrs, cref)
    seal_ok = h_since is not None and h_since < 10.0
    seal_txt = "SERVICE OK" if seal_ok else "SERVICE DUE"
    seal_col = (46, 125, 50) if seal_ok else (183, 28, 28)
    seal_expl = (
        f"Letzter C-Check: vor {h_since:.1f} Log-h (Stempel < 10 h = OK)."
        if lang_de and h_since is not None
        else (
            f"Last C-check: {h_since:.1f} log-h ago (green if < 10 h)."
            if not lang_de and h_since is not None
            else (
                "Kein C-Check am Log-Hobbs vermerkt – Stempel rot."
                if lang_de
                else "No C-check logged on hobbs – seal red."
            )
        )
    )

    title = "OFFICIAL CONDITION REPORT"
    sub = f"{SKYTYCOON_APP_NAME} · Certified Pre-Owned (CPO)"
    dr.rectangle((0, 0, w, 86), fill=(33, 37, 41))
    dr.text((28, 18), title, fill=(255, 255, 255), font=font_title)
    dr.text((28, 52), sub, fill=(200, 220, 255), font=font_b)

    y = 110
    dr.text((28, y), ("Stammdaten" if lang_de else "Identity"), fill=(20, 24, 30), font=font_h)
    y += 32
    dr.text(
        (40, y),
        f"Tail / Reg: {tail}     Typ: {model}     Kaufpreis (Hangar): {format_eur_de(purchase)}",
        fill=(40, 44, 55),
        font=font_b,
    )
    y += 52
    dr.text(
        (28, y),
        ("Technischer Check (Live)" if lang_de else "Technical check (live)"),
        fill=(20, 24, 30),
        font=font_h,
    )
    y += 32
    gear_pct = min(parts.get("TIRES", 100.0), parts.get("BRAKES", 100.0))
    rows_tech = [
        ("⚙ Motor / Engines", parts.get("ENGINES", 100.0)),
        ("⛓ Fahrwerk (Reifen+Bremsen)", gear_pct),
        ("▣ Zelle (Airframe %)", airframe),
    ]
    for label, pct in rows_tech:
        dr.text((44, y), f"{label}: {pct:.1f} %", fill=(40, 44, 55), font=font_b)
        y += 28
    y += 18
    dr.text((28, y), ("Historie" if lang_de else "History"), fill=(20, 24, 30), font=font_h)
    y += 32
    dr.text(
        (44, y),
        f"Landungen: {n_ldg}   ·   Hart (>500 fpm sim-flag): {n_hard}   ·   Log-Stunden: {hrs:.1f} h",
        fill=(40, 44, 55),
        font=font_b,
    )
    y += 60
    dr.ellipse((28, y, 28 + 120, y + 120), outline=seal_col, width=4)
    dr.text((42, y + 38), seal_txt, fill=seal_col, font=font_h)
    dr.text((170, y + 28), seal_expl, fill=(80, 84, 96), font=font_b)


def generate_cpo_certificate_png(
    path: Path,
    model: str,
    out_png: Path,
    *,
    lang_de: bool = True,
) -> bool:
    """Erzeugt ein CPO-/Zustands-Zertifikat (PNG) für ein Hangar-Flugzeug."""
    if not _PIL_AVAILABLE or Image is None or ImageDraw is None:
        return False
    conn = _conn(path)
    try:
        oc = conn.execute(
            "SELECT condition, purchase_price FROM owned_aircraft WHERE model_name = ?;",
            (model,),
        ).fetchone()
    finally:
        conn.close()
    if not oc:
        return False
    airframe = float(oc[0])
    purchase = float(oc[1] or 0.0)
    info = get_aircraft_parts(path, model)
    parts = {k: float(v) for k, v in (info.get("parts") or {}).items()}
    n_ldg, n_hard, hrs = flight_log_aircraft_stats(path, model)
    tail = tail_number_for_model(path, model)
    cref = read_ccheck_hobbs_ref(path, model)

    im = Image.new("RGB", (920, 640), (248, 249, 252))
    dr = ImageDraw.Draw(im)
    try:
        font_title = ImageFont.truetype("arial.ttf", 26)
        font_h = ImageFont.truetype("arial.ttf", 18)
        font_b = ImageFont.truetype("arial.ttf", 15)
    except OSError:
        font_title = ImageFont.load_default()
        font_h = ImageFont.load_default()
        font_b = ImageFont.load_default()

    _draw_cpo_certificate_core(
        dr,
        font_title,
        font_h,
        font_b,
        model=model,
        tail=tail,
        purchase=purchase,
        airframe=airframe,
        parts=parts,
        n_ldg=n_ldg,
        n_hard=n_hard,
        hrs=hrs,
        ccheck_hobbs_ref=cref,
        lang_de=lang_de,
    )
    out_png.parent.mkdir(parents=True, exist_ok=True)
    im.save(out_png, format="PNG")
    return True


def generate_cpo_certificate_png_from_listing(
    listing: dict,
    out_png: Path,
    *,
    lang_de: bool = True,
) -> bool:
    """Zertifikat-Vorschau aus einem P2P-Inserat (ohne lokales owned_aircraft)."""
    if not _PIL_AVAILABLE or Image is None or ImageDraw is None:
        return False
    model = str(listing.get("model") or "?")
    tail = str(listing.get("tail") or "?")
    price = float(listing.get("price") or 0.0)
    airframe = float(listing.get("airframe_condition") or 0.0)
    rawp = listing.get("parts") or {}
    parts: dict[str, float] = {}
    if isinstance(rawp, dict):
        for k, v in rawp.items():
            try:
                parts[str(k)] = float(v)
            except (TypeError, ValueError):
                parts[str(k)] = 100.0
    for c in PART_CODES:
        parts.setdefault(c, 100.0)
    st = listing.get("stats") if isinstance(listing.get("stats"), dict) else {}
    n_ldg = int(st.get("landings") or 0)
    n_hard = int(st.get("hard_landings") or 0)
    hrs = float(st.get("flight_hours") or 0.0)
    cref_o = listing.get("ccheck_hobbs_ref")
    cref: float | None
    try:
        cref = float(cref_o) if cref_o is not None and str(cref_o) != "" else None
    except (TypeError, ValueError):
        cref = None

    im = Image.new("RGB", (920, 640), (248, 249, 252))
    dr = ImageDraw.Draw(im)
    try:
        font_title = ImageFont.truetype("arial.ttf", 26)
        font_h = ImageFont.truetype("arial.ttf", 18)
        font_b = ImageFont.truetype("arial.ttf", 15)
    except OSError:
        font_title = ImageFont.load_default()
        font_h = ImageFont.load_default()
        font_b = ImageFont.load_default()

    _draw_cpo_certificate_core(
        dr,
        font_title,
        font_h,
        font_b,
        model=model,
        tail=tail,
        purchase=price,
        airframe=airframe,
        parts=parts,
        n_ldg=n_ldg,
        n_hard=n_hard,
        hrs=hrs,
        ccheck_hobbs_ref=cref,
        lang_de=lang_de,
    )
    out_png.parent.mkdir(parents=True, exist_ok=True)
    im.save(out_png, format="PNG")
    return True


def get_pilot_meta(path: Path) -> dict[str, float]:
    conn = _conn(path)
    try:
        row = conn.execute(
            """
            SELECT xp, license_suspended_until, pilot_rest_until,
                   lifetime_fuel_cost, lifetime_revenue
            FROM pilot_stats WHERE id = 1;
            """
        ).fetchone()
        if not row:
            return {
                "xp": 0.0,
                "license_until": 0.0,
                "rest_until": 0.0,
                "lfuel": 0.0,
                "lrev": 0.0,
            }
        return {
            "xp": float(row[0]),
            "license_until": float(row[1]),
            "rest_until": float(row[2]),
            "lfuel": float(row[3]),
            "lrev": float(row[4]),
        }
    finally:
        conn.close()


