def add_xp(path: Path, delta: float) -> float:
    conn = _conn(path)
    try:
        conn.execute(
            "UPDATE pilot_stats SET xp = MAX(0, xp + ?) WHERE id = 1;", (delta,)
        )
        row = conn.execute("SELECT xp FROM pilot_stats WHERE id = 1;").fetchone()
        conn.commit()
        out = float(row[0]) if row else 0.0
        try:
            economy_sync_shadow(path)
        except Exception:
            pass
        return out
    finally:
        conn.close()


