def process_insurance_premiums(path: Path) -> None:
    """1 % des Kaufpreises pro realer Tag (86400 s) je versichertem Flugzeug."""
    now = time.time()
    conn = _conn(path)
    try:
        rows = conn.execute(
            """
            SELECT model_name, purchase_price, insurance_last_charge_ts
            FROM owned_aircraft WHERE insured = 1;
            """
        ).fetchall()
        for model, price, last_ts in rows:
            last_ts = float(last_ts or 0.0)
            if last_ts <= 0.0:
                last_ts = now
                conn.execute(
                    "UPDATE owned_aircraft SET insurance_last_charge_ts = ? WHERE model_name = ?;",
                    (now, model),
                )
                continue
            due = last_ts + 86400.0
            while due <= now:
                fee = float(price) * INSURANCE_DAILY_FRACTION
                cr = conn.execute(
                    "SELECT credits FROM pilot_stats WHERE id = 1;"
                ).fetchone()
                bal = float(cr[0]) if cr else 0.0
                if bal >= fee:
                    conn.execute(
                        "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
                        (fee,),
                    )
                else:
                    conn.execute(
                        "UPDATE owned_aircraft SET insured = 0 WHERE model_name = ?;",
                        (model,),
                    )
                    break
                conn.execute(
                    "UPDATE owned_aircraft SET insurance_last_charge_ts = ? WHERE model_name = ?;",
                    (due, model),
                )
                due += 86400.0
        conn.commit()
        try:
            economy_sync_shadow(path)
        except Exception:
            pass
    finally:
        conn.close()


def process_kasko_airline_policy_daily(path: Path) -> None:
    """Meilenstein 146: feste Tagesprämie für Kasko-Police (Credits, 24h-Schritte)."""
    pol = (
        app_meta_get(path, "active_insurance_policy", INSURANCE_POLICY_LIABILITY) or ""
    ).strip()
    if pol != INSURANCE_POLICY_KASKO:
        return
    now = time.time()
    try:
        last = float(app_meta_get(path, "insurance_kasko_last_charge_ts", "0") or 0.0)
    except ValueError:
        last = 0.0
    if last <= 0.0:
        app_meta_set(path, "insurance_kasko_last_charge_ts", str(now))
        return
    due = last + 86400.0
    conn = _conn(path)
    try:
        while due <= now:
            row = conn.execute(
                "SELECT credits FROM pilot_stats WHERE id = 1;"
            ).fetchone()
            bal = float(row[0]) if row else 0.0
            fee = float(INSURANCE_KASKO_DAILY_CREDITS)
            if bal >= fee:
                conn.execute(
                    "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
                    (fee,),
                )
            else:
                app_meta_set(path, "active_insurance_policy", INSURANCE_POLICY_LIABILITY)
                conn.commit()
                try:
                    economy_sync_shadow(path)
                except Exception:
                    pass
                return
            app_meta_set(path, "insurance_kasko_last_charge_ts", str(due))
            due += 86400.0
        conn.commit()
        try:
            economy_sync_shadow(path)
        except Exception:
            pass
    finally:
        conn.close()


def apply_condition_hours(path: Path, model_name: str, flight_hours: float) -> None:
    loss = flight_hours * CONDITION_LOSS_PER_FLIGHT_HOUR
    conn = _conn(path)
    try:
        conn.execute(
            """
            UPDATE owned_aircraft SET condition = MAX(0.0, condition - ?)
            WHERE model_name = ?;
            """,
            (loss, model_name),
        )
        conn.execute(
            "UPDATE pilot_stats SET flight_hours = flight_hours + ? WHERE id = 1;",
            (flight_hours,),
        )
        conn.commit()
    finally:
        conn.close()


def hangar_wait_maintenance(path: Path, model_name: str) -> tuple[bool, str]:
    conn = _conn(path)
    try:
        cr = conn.execute("SELECT credits FROM pilot_stats WHERE id = 1;").fetchone()
        row_a = conn.execute(
            "SELECT condition FROM owned_aircraft WHERE model_name = ?;",
            (model_name,),
        ).fetchone()
        if not row_a:
            return False, "Flugzeug nicht gefunden."
        credits = float(cr[0]) if cr else 0.0
        cond = float(row_a[0])
        if credits < HANGAR_WAIT_COST:
            return False, "Zu wenig Credits für Wartungs-Wartezeit."
        if cond >= 100.0:
            return False, "Bereits 100 %."
        conn.execute(
            "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
            (HANGAR_WAIT_COST,),
        )
        conn.execute(
            """
            UPDATE owned_aircraft SET condition = MIN(100.0, condition + ?)
            WHERE model_name = ?;
            """,
            (HANGAR_WAIT_COND_BONUS, model_name),
        )
        conn.commit()
        return True, ""
    finally:
        conn.close()


def get_purchase_price(path: Path, model_name: str) -> float:
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT purchase_price FROM owned_aircraft WHERE model_name = ?;",
            (model_name,),
        ).fetchone()
        return float(row[0]) if row else 0.0
    finally:
        conn.close()


def insurance_base_price(path: Path, model_name: str) -> float:
    """Kaufpreis aus Hangar, sonst Marktpreis (alte DB mit purchase_price 0)."""
    p = get_purchase_price(path, model_name)
    if p > 0:
        return p
    for _mid, name, price in fetch_market(path):
        if name == model_name:
            return float(price)
    return max(p, 1.0)


def apply_bruchlandung(
    path: Path, model_name: str, insured: bool
) -> tuple[float, float]:
    """Reparaturkosten abziehen, XP -500, Lizenzsperre setzen. Rückgabe (Kosten, Sperre_bis)."""
    price = get_purchase_price(path, model_name)
    pct = CRASH_REPAIR_INSURED if insured else CRASH_REPAIR_UNINSURED
    cost = price * pct
    pol = (app_meta_get(path, "active_insurance_policy", INSURANCE_POLICY_LIABILITY) or "").strip()
    if pol == INSURANCE_POLICY_KASKO:
        cost *= 0.3
    add_credits(path, -cost)
    add_xp(path, -500.0)
    until = time.time() + (
        LICENSE_SUSPEND_INSURED_S if insured else LICENSE_SUSPEND_S
    )
    meta = get_pilot_meta(path)
    if float(meta["license_until"]) < until:
        set_license_suspend(path, until)
    return cost, until


def _migrate_owned_aircraft_if_needed(conn: sqlite3.Connection) -> None:
    rows = conn.execute("PRAGMA table_info(owned_aircraft)").fetchall()
    if not rows:
        return
    cols = {r[1] for r in rows}
    if "model_name" in cols and "condition" in cols and "purchase_price" in cols:
        return
    if "aircraft_title" in cols:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS owned_aircraft__new (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                model_name TEXT NOT NULL UNIQUE,
                condition REAL NOT NULL DEFAULT 100.0,
                purchase_price REAL NOT NULL DEFAULT 0.0
            );
            """
        )
        conn.execute(
            """
            INSERT OR IGNORE INTO owned_aircraft__new (model_name, condition, purchase_price)
            SELECT aircraft_title, 100.0, 0.0 FROM owned_aircraft;
            """
        )
        conn.execute("DROP TABLE owned_aircraft")
        conn.execute(
            "ALTER TABLE owned_aircraft__new RENAME TO owned_aircraft;"
        )


def load_credits(path: Path) -> float:
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT credits FROM pilot_stats WHERE id = 1"
        ).fetchone()
        return float(row[0]) if row else STARTING_CREDITS
    finally:
        conn.close()


def add_credits(path: Path, delta: float) -> float:
    conn = _conn(path)
    try:
        conn.execute(
            "UPDATE pilot_stats SET credits = credits + ? WHERE id = 1;", (delta,)
        )
        row = conn.execute(
            "SELECT credits FROM pilot_stats WHERE id = 1"
        ).fetchone()
        conn.commit()
        out = float(row[0]) if row else STARTING_CREDITS
        try:
            economy_sync_shadow(path)
        except Exception:
            pass
        return out
    finally:
        conn.close()


def fetch_market(path: Path) -> list[tuple[int, str, float]]:
    conn = _conn(path)
    try:
        cur = conn.execute(
            "SELECT id, model_name, price FROM market ORDER BY price ASC;"
        )
        return [(int(r[0]), str(r[1]), float(r[2])) for r in cur.fetchall()]
    finally:
        conn.close()


def buy_aircraft(path: Path, model_name: str, price: float) -> tuple[bool, str]:
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT credits FROM pilot_stats WHERE id = 1"
        ).fetchone()
        credits = float(row[0]) if row else 0.0
        if credits < price:
            return False, "Nicht genug Credits."
        exists = conn.execute(
            "SELECT 1 FROM owned_aircraft WHERE model_name = ? LIMIT 1;",
            (model_name,),
        ).fetchone()
        if exists:
            return False, "Bereits im Hangar."
        conn.execute(
            "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
            (price,),
        )
        conn.execute(
            """
            INSERT INTO owned_aircraft (model_name, condition, purchase_price)
            VALUES (?, 100.0, ?);
            """,
            (model_name, price),
        )
        sync_aircraft_parts_rows(conn)
        conn.commit()
        record_ccheck_hobbs(path, model_name)
        try:
            economy_sync_shadow(path)
        except Exception:
            pass
        return True, ""
    finally:
        conn.close()


def match_owned_for_title(path: Path, title: str) -> tuple[bool, str | None, float | None]:
    if not title or title.strip() in ("–", "– (noch keine Daten)"):
        return False, None, None
    t = title.upper()
    conn = _conn(path)
    try:
        rows = conn.execute(
            "SELECT model_name, condition FROM owned_aircraft;"
        ).fetchall()
        candidates: list[tuple[str, float]] = []
        for model_name, cond in rows:
            if _title_matches_hangar_model(t, str(model_name)):
                candidates.append((str(model_name), float(cond)))
        if not candidates:
            return False, None, None
        best = max(candidates, key=lambda x: len(x[0]))
        return True, best[0], best[1]
    finally:
        conn.close()


def apply_wear_after_landing(path: Path, model_name: str) -> None:
    wear = random.uniform(0.1, 0.5)
    conn = _conn(path)
    try:
        conn.execute(
            """
            UPDATE owned_aircraft
            SET condition = MAX(0.0, condition - ?)
            WHERE model_name = ?;
            """,
            (wear, model_name),
        )
        conn.commit()
    finally:
        conn.close()


def repair_aircraft(path: Path, model_name: str) -> tuple[bool, str, float]:
    conn = _conn(path)
    try:
        row = conn.execute(
            "SELECT condition FROM owned_aircraft WHERE model_name = ?;",
            (model_name,),
        ).fetchone()
        if not row:
            return False, "Flugzeug nicht gefunden.", 0.0
        cond = float(row[0])
        if cond >= 100.0:
            return False, "Bereits 100 %.", 0.0
        cost = max(250, int((100.0 - cond) * 25))
        cr = conn.execute(
            "SELECT credits FROM pilot_stats WHERE id = 1;"
        ).fetchone()
        credits = float(cr[0]) if cr else 0.0
        if credits < cost:
            return False, f"Zu wenig Credits (benötigt {format_eur_de(float(cost))}).", float(cost)
        conn.execute(
            "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
            (float(cost),),
        )
        conn.execute(
            "UPDATE owned_aircraft SET condition = 100.0 WHERE model_name = ?;",
            (model_name,),
        )
        conn.commit()
        record_ccheck_hobbs(path, model_name)
        try:
            economy_sync_shadow(path)
        except Exception:
            pass
        return True, "", float(cost)
    finally:
        conn.close()


def _download_first_ok(urls: tuple[str, ...], target: Path) -> Path:
    if target.exists() and target.stat().st_size > 0:
        return target
    last_err: Exception | None = None
    for url in urls:
        try:
            r = requests.get(
                url,
                timeout=60,
                headers={"User-Agent": "MSFS-Career-Tool/0.1"},
            )
            r.raise_for_status()
            data = r.content
            if len(data) < 200:
                continue
            target.write_bytes(data)
            return target
        except Exception as exc:  # noqa: BLE001
            last_err = exc
            continue
    raise RuntimeError("Download fehlgeschlagen.") from last_err


def ensure_cabin_wav(target: Path) -> Path:
    """Kabinen-Loop: gebündelte WAV (PyInstaller) oder User-writable assets/sounds."""
    name = target.name
    bundled = get_resource_path(f"assets/sounds/{name}")
    if bundled.is_file() and bundled.stat().st_size > 50:
        return bundled
    bundled2 = resource_path(name)
    if bundled2.exists() and bundled2.stat().st_size > 50:
        return bundled2
    return _download_first_ok(CABIN_WAV_URLS, target)


def ensure_passenger_wav(target: Path) -> Path:
    bundled = resource_path(target.name)
    if bundled.exists() and bundled.stat().st_size > 50:
        return bundled
    return _download_first_ok(PASSENGER_WAV_URLS, target)


def detect_addon_from_title(title: str) -> str:
    if not title or not str(title).strip():
        return "–"
    t = str(title).upper()
    if "FENIX" in t:
        return "Fenix (TITLE)"
    if "PMDG" in t:
        return "PMDG (TITLE)"
    return "Kein Fenix/PMDG-TITLE-Match"


def _as_bool(v: object) -> bool:
    if v is None:
        return False
    if isinstance(v, (bool, int)):
        return bool(v)
    s = str(v).strip().lower()
    return s in ("true", "1", "yes")


def _as_float(v: object) -> float | None:
    if v is None:
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _sim_on_ground_safe_int(raw: object) -> int:
    """
    SimConnect-robust: 1 = am Boden (Default bei fehlender/ungültiger Telemetrie),
    0 = in der Luft (nur wenn explizit „nicht am Boden“ erkannt).
    """
    if raw is None:
        return 1
    s = str(raw).strip()
    if s == "":
        return 1
    try:
        v = int(float(s))
        return 1 if v != 0 else 0
    except (TypeError, ValueError):
        return 1 if _as_bool(raw) else 0


def _now_hms() -> str:
    return time.strftime("%H:%M:%S")


