def _navigraph_crypto_key(path: Path) -> bytes:
    raw = (
        (app_meta_get(path, "econ_device_tag", "") or "skytycoon")
        + SKYTYCOON_APP_NAME
        + "navigraph-v1"
    ).encode("utf-8", errors="replace")
    return hashlib.sha256(raw).digest()


def navigraph_encrypt_secret(path: Path, plain: str) -> str:
    if not plain:
        return ""
    k = _navigraph_crypto_key(path)
    data = plain.encode("utf-8", errors="replace")
    x = bytes(b ^ k[i % len(k)] for i, b in enumerate(data))
    return base64.urlsafe_b64encode(x).decode("ascii")


def navigraph_decrypt_secret(path: Path, blob: str) -> str:
    if not blob.strip():
        return ""
    try:
        raw = base64.urlsafe_b64decode(blob.encode("ascii"))
    except (ValueError, OSError):
        return ""
    k = _navigraph_crypto_key(path)
    p = bytes(b ^ k[i % len(k)] for i, b in enumerate(raw))
    return p.decode("utf-8", errors="replace")


def navigraph_refresh_access_token(path: Path) -> str | None:
    rt = navigraph_decrypt_secret(
        path, app_meta_get(path, "navigraph_refresh_token_enc", "") or ""
    ).strip()
    if not rt:
        return None
    cid = _navigraph_resolved_client_id()
    if not cid:
        return None
    body: dict[str, str] = {
        "grant_type": "refresh_token",
        "refresh_token": rt,
        "client_id": cid,
    }
    sec = (os.environ.get("NAVIGRAPH_CLIENT_SECRET") or "").strip()
    if sec:
        body["client_secret"] = sec
    try:
        r = requests.post(
            "https://identity.navigraph.com/connect/token",
            data=body,
            timeout=25,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
        )
        if r.status_code != 200:
            return None
        j = r.json()
        if not isinstance(j, dict):
            return None
        at = str(j.get("access_token") or "").strip()
        if not at:
            return None
        app_meta_set(
            path,
            "navigraph_access_token_enc",
            navigraph_encrypt_secret(path, at),
        )
        rt2 = str(j.get("refresh_token") or "").strip()
        if rt2:
            app_meta_set(
                path,
                "navigraph_refresh_token_enc",
                navigraph_encrypt_secret(path, rt2),
            )
        try:
            exp = int(time.time()) + int(float(j.get("expires_in", 3600)))
        except (TypeError, ValueError):
            exp = int(time.time()) + 3600
        app_meta_set(path, "navigraph_token_expires_unix", str(exp))
        return at
    except Exception:
        return None


def navigraph_get_valid_access_token(path: Path) -> str | None:
    """Liefert ein gültiges Bearer-Token oder None (inkl. Refresh-Versuch)."""
    try:
        exp = float(app_meta_get(path, "navigraph_token_expires_unix", "0") or 0)
    except ValueError:
        exp = 0.0
    at = navigraph_decrypt_secret(
        path, app_meta_get(path, "navigraph_access_token_enc", "") or ""
    ).strip()
    if at and (exp <= 0 or time.time() < exp - 90):
        return at
    return navigraph_refresh_access_token(path)


def simbrief_dep_arr_from_meta(path: Path) -> tuple[str, str]:
    raw = (app_meta_get(path, "simbrief_summary_json", "") or "").strip()
    if not raw:
        return "", ""
    try:
        d = json.loads(raw)
        if isinstance(d, dict):
            dep = str(d.get("dep", "") or "").strip().upper()[:4]
            arr = str(d.get("arr", "") or "").strip().upper()[:4]
            return dep, arr
    except (json.JSONDecodeError, TypeError, ValueError):
        pass
    return "", ""


def navigraph_fetch_charts_list(path: Path, icao: str) -> tuple[list[dict], str | None]:
    token = navigraph_get_valid_access_token(path)
    if not token:
        return [], "notoken"
    icao = (icao or "").strip().upper()[:4]
    if len(icao) != 4:
        return [], "badicao"
    try:
        r = requests.get(
            f"https://api.navigraph.com/v2/charts/{icao}",
            params={"version": "STD", "rules": "IFR"},
            headers={
                "Authorization": f"Bearer {token}",
                "User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}",
            },
            timeout=45,
        )
        if r.status_code != 200:
            return [], f"http_{r.status_code}"
        j = r.json()
        if not isinstance(j, dict):
            return [], "json"
        charts = j.get("charts")
        if not isinstance(charts, list):
            return [], "nocharts"
        out: list[dict] = [c for c in charts if isinstance(c, dict)]
        return out, None
    except Exception as exc:
        return [], str(exc)


