def flightlog_upload_to_ionos(path: Path, report: dict) -> None:
    base, pw = ionos_cloud_credentials(path)
    if not base or not pw:
        return
    hid = p2p_hardware_id(path)
    body = {"hardware_id": hid, "password": pw, "report": report}

    def _run() -> None:
        try:
            requests.post(
                f"{base}/api/v1/user/flightlog/upload",
                json=body,
                timeout=45,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            )
        except Exception:
            pass

    QThreadPool.globalInstance().start(HeavyTaskWorker(_run))


def navigraph_download_chart_bytes(path: Path, url: str) -> tuple[bytes | None, str | None]:
    token = navigraph_get_valid_access_token(path)
    if not token:
        return None, "notoken"
    try:
        r = requests.get(
            url,
            headers={
                "Authorization": f"Bearer {token}",
                "User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}",
            },
            timeout=60,
        )
        if r.status_code != 200:
            return None, f"http_{r.status_code}"
        return r.content, None
    except Exception as exc:
        return None, str(exc)


