class _NavigraphOAuthHttpHandler(http.server.BaseHTTPRequestHandler):
    """Lokaler Callback-Listener für Navigraph OAuth (Port 8000)."""

    auth_code: str | None = None

    def log_message(self, format: str, *args: object) -> None:  # noqa: A003
        return

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        qs = parse_qs(parsed.query)
        codes = qs.get("code") or []
        code = codes[0] if codes else ""
        if code:
            _NavigraphOAuthHttpHandler.auth_code = code
        html_ok = (
            "<html><body style='font-family:Segoe UI,sans-serif;background:#0d1117;"
            "color:#e8c547;text-align:center;padding:48px;'>"
            "<h1>Anmeldung erfolgreich!</h1>"
            "<p>Sie können dieses Fenster schließen und zum EFB-Tablet zurückkehren.</p>"
            "</body></html>"
        )
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.end_headers()
        self.wfile.write(html_ok.encode("utf-8"))


class NavigraphOAuthDialog(QDialog):
    """OAuth 2.0 (PKCE): Browser + lokaler Listener auf http://127.0.0.0:8000/."""

    def __init__(self, parent: QWidget | None, path: Path) -> None:
        super().__init__(parent)
        self._path = path
        self._token_done = False
        self.setWindowTitle(i18n_db(path, "navigraph.oauth_title", "Navigraph anmelden"))
        self.resize(520, 220)
        lay = QVBoxLayout(self)
        self._status = QLabel(
            i18n_db(
                path,
                "navigraph.oauth_wait",
                "Browser wird geöffnet … Warten auf Navigraph-Rückruf am lokalen Port.",
            )
        )
        self._status.setWordWrap(True)
        lay.addWidget(self._status)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        bb.rejected.connect(self.reject)
        lay.addWidget(bb)
        self._verifier = secrets.token_urlsafe(48)
        chal = hashlib.sha256(self._verifier.encode("ascii")).digest()
        self._challenge = base64.urlsafe_b64encode(chal).decode("ascii").rstrip("=")
        self._client_id = _navigraph_resolved_client_id()
        self._redirect_uri = _navigraph_resolved_redirect_uri()
        if not self._client_id:
            self._status.setText(
                i18n_db(
                    path,
                    "navigraph.missing_client_id",
                    "NAVIGRAPH_CLIENT_ID fehlt (ENV, Datei oder NAVIGRAPH_CLIENT_ID_EMBEDDED).",
                )
            )
            return
        QTimer.singleShot(200, self._start_oauth_flow)

    def _start_oauth_flow(self) -> None:
        _NavigraphOAuthHttpHandler.auth_code = None
        port = NAVIGRAPH_OAUTH_LOCAL_PORT
        try:
            self._httpd = http.server.HTTPServer(("127.0.0.1", port), _NavigraphOAuthHttpHandler)
        except OSError:
            self._status.setText(
                i18n_db(
                    self._path,
                    "navigraph.port_busy",
                    f"Port {port} ist belegt — schließen Sie andere OAuth-Listener.",
                )
            )
            return
        self._http_thread = threading.Thread(
            target=self._httpd.serve_forever, daemon=True
        )
        self._http_thread.start()
        scopes = quote("openid charts offline_access")
        auth = (
            "https://identity.navigraph.com/connect/authorize"
            f"?client_id={quote(self._client_id)}"
            f"&redirect_uri={quote(self._redirect_uri)}"
            "&response_type=code"
            f"&scope={scopes}"
            f"&code_challenge={quote(self._challenge)}"
            "&code_challenge_method=S256"
            "&state=skytycoon"
        )
        QDesktopServices.openUrl(QUrl(auth))
        self._poll_timer = QTimer(self)
        self._poll_timer.timeout.connect(self._poll_for_code)
        self._poll_timer.start(400)

    def _poll_for_code(self) -> None:
        code = _NavigraphOAuthHttpHandler.auth_code
        if not code:
            return
        self._poll_timer.stop()
        try:
            self._httpd.shutdown()
        except Exception:
            pass
        body: dict[str, str] = {
            "grant_type": "authorization_code",
            "code": code,
            "redirect_uri": self._redirect_uri,
            "client_id": self._client_id,
            "code_verifier": self._verifier,
        }
        sec = (os.environ.get("NAVIGRAPH_CLIENT_SECRET") or "").strip()
        if sec:
            body["client_secret"] = sec
        try:
            r = requests.post(
                "https://identity.navigraph.com/connect/token",
                data=body,
                timeout=25,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            )
            if r.status_code != 200:
                self._status.setText(
                    i18n_db(self._path, "navigraph.token_fail", "Token-Austausch fehlgeschlagen.")
                )
                return
            j = r.json()
            if not isinstance(j, dict):
                return
            at = str(j.get("access_token") or "").strip()
            rt = str(j.get("refresh_token") or "").strip()
            if not at:
                return
            app_meta_set(
                self._path,
                "navigraph_access_token_enc",
                navigraph_encrypt_secret(self._path, at),
            )
            if rt:
                app_meta_set(
                    self._path,
                    "navigraph_refresh_token_enc",
                    navigraph_encrypt_secret(self._path, rt),
                )
            try:
                exp = int(time.time()) + int(float(j.get("expires_in", 3600)))
            except (TypeError, ValueError):
                exp = int(time.time()) + 3600
            app_meta_set(self._path, "navigraph_token_expires_unix", str(exp))
            self._token_done = True
            self._status.setText(
                i18n_db(
                    self._path,
                    "navigraph.oauth_ok",
                    "Navigraph verbunden — Charts im EFB verfügbar.",
                )
            )
            QTimer.singleShot(800, self.accept)
        except Exception:
            self._status.setText(
                i18n_db(self._path, "navigraph.token_fail", "Token-Austausch fehlgeschlagen.")
            )

    def closeEvent(self, event) -> None:  # type: ignore[no-untyped-def]
        try:
            if hasattr(self, "_poll_timer"):
                self._poll_timer.stop()
            if hasattr(self, "_httpd"):
                self._httpd.shutdown()
        except Exception:
            pass
        super().closeEvent(event)


