class CabinGenerator:
    """Kabinen-Grid-Profile je nach Flugzeug-Titel (Heuristik)."""

    @staticmethod
    def profile_for_title(title: str) -> tuple[int, int, str]:
        u = (title or "").upper()
        if any(x in u for x in ("CESSNA", "152", "DA40", "SR22", "CUB", "PA-28")):
            return 2, 2, "GA (2×2)"
        if "747" in u or "777" in u or "787" in u or "A330" in u:
            return 8, 9, "Widebody (3-3-3)"
        if "ATR" in u or "CRJ" in u or "E175" in u or "E190" in u:
            return 6, 4, "Regional (2-2)"
        return 7, 6, "Narrowbody (3-3)"


def _st_auth_tr(path: Path, key: str, default: str) -> str:
    return i18n_db(path, key, default)


def ionos_server_reachable(max_attempts: int = 4, pause_sec: float = 2.0) -> bool:
    """Prüft ob skytycoon.info erreichbar ist (kurze Retries bei Deploy-Neustart)."""
    base = ionos_server_url()
    if not base:
        return False
    url = f"{base.rstrip('/')}/api/v1/health"
    for attempt in range(max(1, int(max_attempts))):
        try:
            r = requests.get(
                url,
                timeout=12,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
                verify=auth_requests_verify_tls(),
            )
            if r.status_code == 200:
                try:
                    j = r.json()
                except json.JSONDecodeError:
                    j = {}
                if str(j.get("status", "")).lower() == "ok":
                    return True
        except Exception:
            pass
        if attempt + 1 < max_attempts:
            time.sleep(max(0.5, float(pause_sec)))
    return False


def ionos_drm_verify_strict_request(path: Path) -> tuple[bool, str]:
    """POST ``/api/v1/auth/verify_strict`` — Cloud-only, kein Offline-Bypass."""
    base = ionos_server_url()
    if not base:
        return False, "no_url"
    try:
        last = float(
            app_meta_get(path, "cloud_last_server_contact_unix", "0") or 0
        )
    except ValueError:
        last = 0.0
    recent = last > 0 and (time.time() - last) < DRM_VERIFY_TRUST_SEC
    if not recent and not ionos_server_reachable(max_attempts=1, pause_sec=0.6):
        return False, "server_offline"
    hid = p2p_hardware_id(path)
    key = (app_meta_get(path, "license_key_installed", "") or "").strip()
    last_exc: Exception | None = None
    for attempt in range(3):
        try:
            r = requests.post(
                f"{base.rstrip('/')}/api/v1/auth/verify_strict",
                json={
                    "hardware_id": hid,
                    "current_key": key,
                    "app_version": APP_VERSION,
                },
                timeout=20,
                headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
                verify=auth_requests_verify_tls(),
            )
            if r.status_code == 403:
                try:
                    j = r.json()
                except json.JSONDecodeError:
                    j = {}
                return False, str(j.get("message", j.get("status", "denied")))
            if r.status_code != 200:
                return False, "http_error"
            j = r.json()
            if str(j.get("status", "")).lower() == "success" or cloud_payload_license_active(j):
                remember_successful_cloud_license(path, j)
                app_meta_set(path, "drm_last_status", "cloud_validated")
                try:
                    app_meta_set(path, "drm_offline_autark", "0")
                except OSError:
                    pass
                return True, "success"
            return False, str(j.get("message", j.get("status", "denied")))
        except Exception as exc:
            last_exc = exc
            if attempt < 2:
                time.sleep(2.0)
    return False, f"net_err:{last_exc}"


def ionos_drm_verify_request(path: Path) -> tuple[str, str]:
    """POST ``/api/v1/auth/verify`` → (status, detail)."""
    base = ionos_server_url()
    if not base:
        return "no_server", ""
    hid = p2p_hardware_id(path)
    key = (app_meta_get(path, "license_key_installed", "") or "").strip()
    try:
        r = requests.post(
            f"{base}/api/v1/auth/verify",
            json={
                "hardware_id": hid,
                "current_key": key,
                "app_version": APP_VERSION,
            },
            timeout=18,
            headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
            verify=auth_requests_verify_tls(),
        )
        if r.status_code != 200:
            return "http_error", str(r.status_code)
        j = r.json()
        return str(j.get("status", "error")), ""
    except Exception as exc:
        return "net_err", str(exc)


def ionos_drm_gate_run(path: Path) -> tuple[bool, str]:
    """Zwingende Cloud-Verifikation bei jedem Start — kein lokaler Offline-Bypass."""
    if app_meta_get(path, "license_activated", "0") == "1":
        try:
            last = float(
                app_meta_get(path, "cloud_last_server_contact_unix", "0") or 0
            )
        except ValueError:
            last = 0.0
        if last > 0 and (time.time() - last) < DRM_VERIFY_TRUST_SEC:
            return True, "recent_cloud_contact"
    base = ionos_server_url()
    if not online_network_enabled(path) and base:
        if app_meta_get(path, "license_activated", "0") == "1":
            app_meta_set(path, "online_network_enabled", "1")
        elif (app_meta_get(path, "ionos_server_url", "") or "").strip():
            app_meta_set(path, "online_network_enabled", "1")
    if not online_network_enabled(path):
        return False, "offline_blocked"
    if not base:
        return False, "no_url"
    ok, detail = ionos_drm_verify_strict_request(path)
    if ok:
        return True, detail
    return False, detail


