    def _paste_key_into(self, target: QLineEdit) -> None:
        app = QApplication.instance()
        if app is None:
            return
        txt = app.clipboard().text().strip()
        if txt:
            target.setText(txt[:384])
            target.setFocus(Qt.FocusReason.OtherFocusReason)

    def _paste_act_key(self) -> None:
        self._paste_key_into(self.ed_act_key)

    def _write_activation_file(self, payload: dict, pilot: str) -> None:
        try:
            activation = {
                "activated": True,
                "pilot_name": pilot,
                "hardware_id": p2p_hardware_id(self._path),
                "license_key": str(payload.get("license_key") or payload.get("key") or app_meta_get(self._path, "license_key_installed", ""))[:256],
                "activated_at": int(time.time()),
                "server": "https://skytycoon.info",
                "app_version": APP_VERSION,
            }
            (BASE_DIR / "activated.json").write_text(json.dumps(activation, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            pass

    def _try_web_profile_license_login(
        self, login_name: str, password: str, license_key: str = ""
    ) -> dict | None:
        base = ionos_server_url().strip().rstrip("/")
        if not base or not password:
            return None
        hid = p2p_hardware_id(self._path)
        body: dict[str, object] = {
            "hardware_id": hid,
            "password": password,
            "pull_only": True,
            "app_version": APP_VERSION,
        }
        name = (login_name or "").strip()
        if "@" in name:
            body["portal_email"] = name.lower()[:200]
            body["email"] = name.lower()[:200]
        elif name:
            body["pilot_name"] = name[:120]
            body["username"] = name[:120]
        if license_key:
            body["license_key"] = license_key[:256]
        try:
            r = requests.post(
                f"{base}/api/v1/user/sync_profile",
                json=body,
                timeout=22,
                headers={
                    "User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}",
                    "Content-Type": "application/json",
                },
                verify=auth_requests_verify_tls(),
            )
            if r.status_code != 200:
                return None
            j = r.json() if r.content else {}
            if isinstance(j, dict) and profile_cloud_payload_ok(j) and cloud_payload_license_active(j):
                remember_successful_cloud_license(
                    self._path, j, password=password, pilot_name=name
                )
                apply_server_profile_authority(self._path, j)
                return j
        except Exception:
            return None
        return None

    def _try_pc_hardware_rebind_login(self, login_name: str, password: str, license_key: str = "") -> dict | None:
        base = ionos_server_url().strip().rstrip("/")
        if not base or not login_name or not password:
            return None
        hid = p2p_hardware_id(self._path)
        name = (login_name or "").strip()
        body: dict[str, object] = {
            "pilot_name": name[:120],
            "username": name[:120],
            "password": password,
            "hardware_id": hid,
            "pc_hardware_id": hid,
            "incoming_pc_hardware_id": hid,
            "app_version": APP_VERSION,
        }
        if "@" in name:
            body["portal_email"] = name.lower()[:200]
            body["email"] = name.lower()[:200]
        if license_key:
            body["license_key"] = license_key[:256]
        try:
            r = requests.post(
                f"{base}/api/v1/auth/update_hardware",
                json=body,
                timeout=22,
                headers={
                    "User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}",
                    "Content-Type": "application/json",
                },
                verify=auth_requests_verify_tls(),
            )
            if r.status_code != 200:
                return None
            j = r.json() if r.content else {}
            if isinstance(j, dict) and (
                str(j.get("status", "")).lower() in ("login_success", "success", "ok")
                or cloud_payload_license_active(j)
            ):
                remember_successful_cloud_license(
                    self._path, j, password=password, pilot_name=name
                )
                return j
        except Exception:
            return None
        return None

    def _accept_license_payload(self, payload: dict, pilot: str, pw: str, fallback_key: str = "") -> None:
        data = dict(payload or {})
        if fallback_key and not str(data.get("license_key") or "").strip():
            data["license_key"] = fallback_key.strip()
        if pilot and not str(data.get("pilot_name") or data.get("username") or "").strip():
            data["pilot_name"] = pilot[:120]
        ionos_bind_hardware_id(
            self._path,
            str(data.get("hardware_id") or p2p_hardware_id(self._path))[:64],
        )
        app_meta_set(self._path, "license_activated", "1")
        remember_successful_cloud_license(self._path, data, password=pw, pilot_name=pilot)
        self._write_activation_file(data, pilot)
        self.accept()

    def _do_login(self) -> None:
        base = ionos_server_url()
        pilot = self.ed_login_name.text().strip()
        pw = self.ed_login_pw.text().strip()
        key = self.ed_login_key.text().strip() if hasattr(self, "ed_login_key") and self.ed_login_key.isVisible() else ""
        hid = p2p_hardware_id(self._path)
        if not pilot or not pw:
            QMessageBox.warning(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(self._path, "startup.auth.fill_all", "Bitte alle Felder ausfüllen."),
            )
            return
        try:
            r = requests.post(
                f"{base}/api/v1/auth/login",
                json={
                    "pilot_name": pilot[:120],
                    "password": pw,
                    "hardware_id": hid,
                    "pc_hardware_id": hid,
                    "incoming_pc_hardware_id": hid,
                    "license_key": key[:256],
                },
                timeout=20,
                headers={
                    "User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}",
                    "Content-Type": "application/json",
                },
                verify=auth_requests_verify_tls(),
            )
            j = r.json() if r.content else {}
        except Exception as exc:
            QMessageBox.warning(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(self._path, "startup.auth.net_err", "Server nicht erreichbar: {e}").format(
                    e=str(exc)
                ),
            )
            return
        st = str(j.get("status", ""))
        if st == "login_success" or cloud_payload_license_active(j):
            app_meta_set(self._path, "pilot_display_name", pilot[:120])
            app_meta_set(self._path, "license_activated", "1")
            ionos_bind_hardware_id(
                self._path, str(j.get("hardware_id") or hid)[:64]
            )
            if pw:
                cloud_password_set(self._path, pw)
            lk = str(j.get("license_key", "") or "").strip()
            if lk:
                app_meta_set(self._path, "license_key_installed", lk[:256])
            elif key:
                app_meta_set(self._path, "license_key_installed", key[:256])
            try:
                credits_v = float(j.get("credits", 0))
                xp_v = float(j.get("xp", 0))
                rep_v = float(j.get("reputation", 0))
            except (TypeError, ValueError):
                credits_v = xp_v = rep_v = None
            if credits_v is not None and xp_v is not None:
                try:
                    cdb = _conn(self._path)
                    try:
                        cdb.execute(
                            "UPDATE pilot_stats SET credits = ?, xp = ? WHERE id = 1;",
                            (credits_v, xp_v),
                        )
                        cdb.commit()
                    finally:
                        cdb.close()
                except sqlite3.Error:
                    pass
            if rep_v is not None:
                rep_clamped = max(0.0, min(100.0, rep_v))
                app_meta_set(self._path, "company_reputation", f"{rep_clamped:.2f}")
            app_meta_set(self._path, "drm_last_ok_ts", str(int(time.time())))
            app_meta_set(self._path, "drm_last_status", "activated")
            cloud_record_successful_server_contact(self._path)
            self._write_activation_file(j, pilot)
            self.accept()
        elif st == "banned":
            QMessageBox.critical(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(self._path, "startup.auth.banned", "Account gesperrt."),
            )
        else:
            rebind_payload = self._try_pc_hardware_rebind_login(pilot, pw, key)
            if rebind_payload:
                self._accept_license_payload(rebind_payload, pilot, pw, key)
                return
            web_payload = self._try_web_profile_license_login(pilot, pw, key)
            if web_payload:
                self._accept_license_payload(web_payload, pilot, pw, key)
                return
            QMessageBox.warning(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(
                    self._path,
                    "startup.auth.login_failed",
                    "Anmeldung fehlgeschlagen (Name/Passwort/Hardware).",
                ),
            )

    def _do_activate(self) -> None:
        base = ionos_server_url()
        pilot = self.ed_act_name.text().strip()
        pw = self.ed_act_pw.text().strip()
        key = self.ed_act_key.text().strip()
        hid = p2p_hardware_id(self._path)
        if not pilot or not pw or not key:
            QMessageBox.warning(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(self._path, "startup.auth.fill_all", "Bitte alle Felder ausfüllen."),
            )
            return
        try:
            r = requests.post(
                f"{base}/api/v1/auth/register_license",
                json={
                    "pilot_name": pilot[:120],
                    "password": pw,
                    "license_key": key,
                    "hardware_id": hid,
                    "app_version": APP_VERSION,
                },
                timeout=22,
                headers={
                    "User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}",
                    "Content-Type": "application/json",
                },
                verify=auth_requests_verify_tls(),
            )
            j = r.json() if r.content else {}
        except Exception as exc:
            QMessageBox.warning(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(self._path, "startup.auth.net_err", "Server nicht erreichbar: {e}").format(
                    e=str(exc)
                ),
            )
            return
        if r.status_code == 200:
            st = str(j.get("status", ""))
            if st == "activated" or cloud_payload_license_active(j):
                app_meta_set(self._path, "license_key_installed", key.strip()[:256])
                app_meta_set(self._path, "license_activated", "1")
                app_meta_set(self._path, "pilot_display_name", pilot[:120])
                ionos_bind_hardware_id(
                    self._path, str(j.get("hardware_id") or hid)[:64]
                )
                if pw:
                    cloud_password_set(self._path, pw)
                app_meta_set(self._path, "drm_last_ok_ts", str(int(time.time())))
                app_meta_set(self._path, "drm_last_status", "activated")
                app_meta_set(self._path, "setup_wizard_required", "1")
                self.accept()
            elif st == "hardware_mismatch":
                rebind_payload = self._try_pc_hardware_rebind_login(pilot, pw, key)
                if rebind_payload:
                    self._accept_license_payload(rebind_payload, pilot, pw, key)
                    return
                web_payload = self._try_web_profile_license_login(pilot, pw, key)
                if web_payload:
                    self._accept_license_payload(web_payload, pilot, pw, key)
                    return
                QMessageBox.critical(
                    self,
                    SKYTYCOON_APP_NAME,
                    _st_auth_tr(
                        self._path,
                        "drm.activate_hardware_mismatch",
                        "Dieser Lizenzschlüssel ist bereits mit einer anderen Hardware-ID verknüpft.",
                    ),
                )
            elif st in ("key_invalid", "bad_request"):
                web_payload = self._try_web_profile_license_login(pilot, pw, key)
                if web_payload:
                    self._accept_license_payload(web_payload, pilot, pw, key)
                    return
                QMessageBox.warning(
                    self,
                    SKYTYCOON_APP_NAME,
                    _st_auth_tr(
                        self._path,
                        "drm.activate_key_invalid",
                        "Ungültiger oder bereits verwendeter Lizenzschlüssel.",
                    ),
                )
            else:
                web_payload = self._try_web_profile_license_login(pilot, pw, key)
                if web_payload:
                    self._accept_license_payload(web_payload, pilot, pw, key)
                    return
                QMessageBox.warning(
                    self,
                    SKYTYCOON_APP_NAME,
                    _st_auth_tr(
                        self._path,
                        "startup.auth.activate_failed",
                        "Aktivierung fehlgeschlagen (Server-Antwort).",
                    ),
                )
        else:
            web_payload = self._try_web_profile_license_login(pilot, pw, key)
            if web_payload:
                self._accept_license_payload(web_payload, pilot, pw, key)
                return
            QMessageBox.warning(
                self,
                SKYTYCOON_APP_NAME,
                _st_auth_tr(
                    self._path,
                    "startup.auth.activate_failed",
                    "Aktivierung fehlgeschlagen (ungültiger oder bereits genutzter Schlüssel).",
                ),
            )


