    def resizeEvent(self, event) -> None:  # type: ignore[override]
        super().resizeEvent(event)
        self._persist_efb_geometry()

    def _persist_efb_geometry(self) -> None:
        try:
            app_meta_set(
                DB_PATH,
                "ui_efb_geometry",
                bytes(self.saveGeometry().toHex()).decode("ascii"),
            )
        except Exception:
            pass

    def _reload_simbrief_pdf_tab(self) -> None:
        m = self._main
        url = (app_meta_get(DB_PATH, "simbrief_ofp_pdf_url", "") or "").strip()
        self._efb_ofp_hint.setText(
            m._tr("efb.simbrief_pdf_hint", "Offizielles SimBrief-OFP (PDF). SimBrief-Import ausführen, falls leer.")
        )
        if self._efb_web_ofp is not None:
            if url.startswith("http"):
                self._efb_web_ofp.load(QUrl(url))
            else:
                self._efb_web_ofp.setHtml(
                    "<body style='background:#121214;color:#b0bec5;font-family:Segoe UI;padding:16px'>"
                    + m._tr("efb.simbrief_pdf_empty", "Keine PDF-URL – bitte SimBrief OFP importieren.")
                    + "</body>"
                )
        elif self._efb_ofp_placeholder is not None:
            self._efb_ofp_placeholder.setText(
                m._tr("efb.simbrief_pdf_noweb", "PDF-Anzeige benötigt Qt WebEngine.")
                if url.startswith("http")
                else m._tr("efb.simbrief_pdf_empty", "Keine PDF-URL – bitte SimBrief OFP importieren.")
            )

    def _blink_cabin_intercom_tab(self) -> None:
        tb = self._efb_tabs.tabBar()
        if not getattr(self._main, "_cabin_rage_pending", None):
            self._blink_timer.stop()
            try:
                tb.setTabTextColor(self._cabin_tab_idx, QColor("#eceff1"))
            except Exception:
                pass
            return
        self._blink_on = not self._blink_on
        try:
            tb.setTabTextColor(
                self._cabin_tab_idx,
                QColor("#ff5252") if self._blink_on else QColor("#ffab91"),
            )
        except Exception:
            pass

