MSFS_INGAME_WS_PORT = 8383


class _MsfsIngameWsBridge(QObject):
    """Lokaler WebSocket (Port 8383) für MSFS In-Game-Panel ↔ Desktop-App."""

    command_received = Signal(str)

    def __init__(self, parent: QObject | None = None) -> None:
        super().__init__(parent)
        self._clients: list[object] = []
        self._server: object | None = None
        if not _QT_WEBSOCKETS_OK or QWebSocketServer is None:
            print("[MSFS PANEL] QtWebSockets nicht verfügbar – In-Game-Bridge deaktiviert.")
            return
        self._server = QWebSocketServer(
            "SkyTycoonMsfs",
            QWebSocketServer.SslMode.NonSecureMode,
            self,
        )
        if self._server.listen(QHostAddress.SpecialAddress.LocalHost, MSFS_INGAME_WS_PORT):
            self._server.newConnection.connect(self._on_new_connection)
            print(f"[MSFS PANEL] WebSocket lauscht auf ws://127.0.0.1:{MSFS_INGAME_WS_PORT}/msfs_data")
        else:
            print(f"[MSFS PANEL] WebSocket-Port {MSFS_INGAME_WS_PORT} nicht bindbar.")

    def _on_new_connection(self) -> None:
        if self._server is None:
            return
        sock = self._server.nextPendingConnection()
        if sock is None:
            return
        sock.textMessageReceived.connect(
            lambda msg, s=sock: self.command_received.emit(str(msg))
        )

        def _drop() -> None:
            try:
                self._clients.remove(sock)
            except ValueError:
                pass

        sock.disconnected.connect(_drop)
        self._clients.append(sock)

    def broadcast_json(self, data: dict) -> None:
        if not self._clients:
            return
        try:
            payload = json.dumps(data, ensure_ascii=False)
        except (TypeError, ValueError):
            return
        dead: list[object] = []
        for client in self._clients:
            try:
                client.sendTextMessage(payload)
            except Exception:
                dead.append(client)
        for client in dead:
            try:
                self._clients.remove(client)
            except ValueError:
                pass


