class _SimConnectPollThread(QThread):
    """Dedizierter SimConnect-Poll-Thread (MSFS-Telemetrie, Zero-Freeze GUI)."""

    snapshot_ready = Signal(dict)
    poll_error = Signal(object)

    def __init__(self, aq: object) -> None:
        super().__init__()
        self._aq = aq
        self._running = True

    def stop(self) -> None:
        self._running = False

    def run(self) -> None:
        while self._running:
            if self._aq is None:
                break
            snap: dict[str, object] = {}
            try:
                for name in SIM_POLL_VAR_NAMES:
                    snap[name] = self._aq.get(name)
                self.snapshot_ready.emit(snap)
            except Exception as exc:
                self.poll_error.emit(exc)
            self.msleep(SIMCONNECT_POLL_INTERVAL_MS)


