class ExternalAcarsHudNotification(QWidget):
    """M195+: Rahmenloses TopMost-Overlay über MSFS für eingehende ACARS-Meldungen."""

    def __init__(self, main_window: "MainWindow") -> None:
        super().__init__()
        self.mw = main_window
        self.setWindowFlags(
            Qt.WindowType.FramelessWindowHint
            | Qt.WindowType.WindowStaysOnTopHint
            | Qt.WindowType.SubWindow
        )
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setFixedSize(800, 50)
        outer = QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        self._frame = QFrame(self)
        self._frame.setStyleSheet(
            "QFrame {"
            "background-color: rgba(0, 34, 68, 210);"
            "color: #00ff66;"
            "font-family: Consolas, monospace;"
            "font-size: 13px;"
            "font-weight: bold;"
            "border: 2px solid #d4af37;"
            "border-radius: 6px;"
            "padding: 6px 12px;"
            "}"
        )
        fl = QHBoxLayout(self._frame)
        fl.setContentsMargins(8, 4, 8, 4)
        self.lbl_hud = QLabel("")
        self.lbl_hud.setWordWrap(False)
        self.lbl_hud.setAlignment(
            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft
        )
        fl.addWidget(self.lbl_hud, 1)
        outer.addWidget(self._frame)
        self._hide_timer = QTimer(self)
        self._hide_timer.setSingleShot(True)
        self._hide_timer.timeout.connect(self.hide)
        self._place_top_center()
        self.hide()

    def _place_top_center(self) -> None:
        app = QApplication.instance()
        if app is None:
            return
        screen = app.primaryScreen()
        if screen is None:
            return
        geo = screen.availableGeometry()
        self.move(max(0, (geo.width() - self.width()) // 2), max(0, geo.top() + 8))

    def show_dispatch(self, banner_text: str) -> None:
        self.lbl_hud.setText((banner_text or "")[:500])
        self._place_top_center()
        self.show()
        self.raise_()
        self.activateWindow()
        self.repaint()
        self.update()
        self._hide_timer.start(10_000)


class AcarsInCockpitRadioWidget(QWidget):
    """M185/M195: Live-ACARS — nur 4 standardisierte Systemmeldungen (WebSocket)."""

    def __init__(self, main_window: QMainWindow) -> None:
        super().__init__()
        self.mw = main_window
        self.ws_client = QWebSocket() if _QT_WEBSOCKETS_OK and QWebSocket else None
        self._reconnect_timer = QTimer(self)
        self._reconnect_timer.setInterval(10_000)
        self._reconnect_timer.timeout.connect(self._maybe_reconnect)
        self._init_ui()
        if self.ws_client is not None:
            self.ws_client.textMessageReceived.connect(self._on_message_received)
            self.ws_client.connected.connect(self._on_connected)
            self.ws_client.disconnected.connect(self._on_disconnected)
            if hasattr(self.ws_client, "errorOccurred"):
                self.ws_client.errorOccurred.connect(self._on_acars_ws_error)

    def _tr(self, key: str, default: str) -> str:
        return self.mw._tr(key, default)

    def _init_ui(self) -> None:
        layout = QVBoxLayout(self)
        self.lbl_status = QLabel(
            self._tr("acars.status_offline", "ACARS-Funkstatus: 🔴 OFFLINE")
        )
        self.lbl_status.setStyleSheet("font-weight: bold; color: #ff3333;")
        layout.addWidget(self.lbl_status)
        self.txt_history = QTextEdit()
        self.txt_history.setReadOnly(True)
        self.txt_history.setStyleSheet(
            "background-color: #080a0f; color: #33ccff; "
            "font-family: Consolas, monospace; font-size: 12px;"
        )
        layout.addWidget(self.txt_history, 1)
        h_box = QHBoxLayout()
        self.combo_acars_templates = QComboBox()
        self.combo_acars_templates.setMinimumWidth(320)
        self._populate_acars_template_combo()
        self.btn_send = QPushButton(self._tr("acars.send", "⚡ Senden"))
        self.btn_send.clicked.connect(self.transmit_acars_message)
        h_box.addWidget(self.combo_acars_templates, 1)
        h_box.addWidget(self.btn_send)
        layout.addLayout(h_box)

    def _populate_acars_template_combo(self) -> None:
        defaults = {
            "acars.tpl.metar": (
                "[⚠️ METAR_ALERT] Schwerer Sturm/Gewitter am Zielflughafen detektiert. "
                "Vorsicht im Endanflug!"
            ),
            "acars.tpl.engine": (
                "[⚙️ ENGINE_WARN] Kritischer Triebwerksverschleiß gemeldet. "
                "Inspektion im Hangar erforderlich."
            ),
            "acars.tpl.emergency": (
                "[🚨 EMERGENCY] Mayday! Luftnotfall im Simulator deklariert. "
                "Priorität für Landung angefordert."
            ),
            "acars.tpl.alliance": (
                "[🤝 ALLIANCE_TAX] Allianz-Kriegskasse aktualisiert. "
                "Steuern an Cloud-Tresor übertragen."
            ),
            "acars.tpl.flightplan": (
                "[✈️ FLIGHT_PLAN] Neuer IFR-Flugplan via SimBrief ins EFB-Tablet geladen. "
                "Bereite Triebwerksstart vor."
            ),
            "acars.tpl.fuel": (
                "[⛽ FUEL_ALERT] Kraftstoff-Minimum erreicht. "
                "Ändere Route zum Ausweichflughafen!"
            ),
            "acars.tpl.passenger": (
                "[👥 PASSENGER_SYNC] Boarding abgeschlossen. "
                "Passagier-Manifest erfolgreich an IONOS-Server übermittelt."
            ),
            "acars.tpl.weather_clear": (
                "[🌤️ WEATHER_CLEAR] Wetterbesserung am Zielflughafen. "
                "Sichtanflug (VFR) freigegeben."
            ),
        }
        self.combo_acars_templates.clear()
        for key in ACARS_TEMPLATE_I18N_KEYS:
            self.combo_acars_templates.addItem(
                self._tr(key, defaults[key]), key
            )

    def showEvent(self, event) -> None:  # noqa: ANN001
        super().showEvent(event)
        self.connect_to_ionos_acars_server()
        self._reconnect_timer.start()

    def hideEvent(self, event) -> None:  # noqa: ANN001
        self._reconnect_timer.stop()
        super().hideEvent(event)

    def connect_to_ionos_acars_server(self) -> None:
        if self.ws_client is None:
            self.lbl_status.setText(
                self._tr(
                    "acars.status_no_ws",
                    "ACARS: QtWebSockets fehlt (PySide6-Addons installieren).",
                )
            )
            self.lbl_status.setStyleSheet("font-weight: bold; color: #ffaa00;")
            return
        if not online_network_enabled(DB_PATH):
            self.lbl_status.setText(
                self._tr(
                    "acars.status_need_online",
                    "ACARS: Online-Netzwerk in den Einstellungen aktivieren.",
                )
            )
            self.lbl_status.setStyleSheet("font-weight: bold; color: #ffaa00;")
            return
        root = (ionos_server_url() or "").strip().rstrip("/")
        if not root:
            self.lbl_status.setText(
                self._tr(
                    "acars.status_no_server",
                    "ACARS: Kein IONOS-Server (SKYTYCOON_IONOS_SERVER_URL).",
                )
            )
            self.lbl_status.setStyleSheet("font-weight: bold; color: #ffaa00;")
            return
        if QAbstractSocket is not None:
            st = self.ws_client.state()
            if st in (
                QAbstractSocket.SocketState.ConnectedState,
                QAbstractSocket.SocketState.ConnectingState,
            ):
                return
        ws_root = root.replace("https://", "wss://").replace("http://", "ws://")
        ws_url = f"{ws_root}/api/v1/ws/acars"
        if QSslConfiguration is not None and QSslSocket is not None:
            config = QSslConfiguration.defaultConfiguration()
            config.setPeerVerifyMode(QSslSocket.PeerVerifyMode.VerifyNone)
            self.ws_client.setSslConfiguration(config)
        self.lbl_status.setText(
            self._tr("acars.status_connecting", "ACARS-Funkstatus: Verbinde…")
        )
        self.lbl_status.setStyleSheet("font-weight: bold; color: #ffcc00;")
        self.ws_client.open(QUrl(ws_url))

    def _maybe_reconnect(self) -> None:
        if self.ws_client is None:
            return
        if QAbstractSocket is not None:
            if self.ws_client.state() == QAbstractSocket.SocketState.ConnectedState:
                return
        self.connect_to_ionos_acars_server()

    def _on_acars_ws_error(self, err: object) -> None:
        if self.ws_client is None:
            return
        self.lbl_status.setText(
            self._tr(
                "acars.status_ws_error",
                "ACARS-Funkstatus: ⚠ Verbindungsfehler (Reconnect…) — {err}",
            ).format(err=str(err))
        )
        self.lbl_status.setStyleSheet("font-weight: bold; color: #ffaa00;")

    def _on_connected(self) -> None:
        self.lbl_status.setText(
            self._tr(
                "acars.status_live",
                "ACARS-Funkstatus: 🟢 LIVE (Zentral-Dispatcher)",
            )
        )
        self.lbl_status.setStyleSheet("font-weight: bold; color: #00ff66;")

    def _on_disconnected(self) -> None:
        self.lbl_status.setText(
            self._tr(
                "acars.status_reconnect",
                "ACARS-Funkstatus: 🔴 DISCONNECTED (Reconnect…)",
            )
        )
        self.lbl_status.setStyleSheet("font-weight: bold; color: #ff3333;")

    def transmit_acars_message(self) -> None:
        if self.ws_client is None:
            return
        text = self.combo_acars_templates.currentText().strip()
        if not text:
            return
        pilot = (
            app_meta_get(DB_PATH, "pilot_display_name", "").strip()
            or pilot_handle(DB_PATH)
        )
        airline = (
            app_meta_get(DB_PATH, "selected_airline_name", "").strip() or "Freelancer"
        )
        payload = {
            "pilot_name": pilot[:80],
            "airline_name": airline[:80],
            "text": text[:500],
        }
        self.ws_client.sendTextMessage(json.dumps(payload, ensure_ascii=False))

    def _push_acars_ticker_banner(
        self, timestamp: str, sender: str, airline: str, msg_text: str
    ) -> None:
        mw = self.mw
        if not hasattr(mw, "label_global_acars_ticker"):
            return
        banner = self._tr(
            "acars.banner_dispatch_fmt",
            "📡 ACARS DISPATCH [{ts}] {sender} ({airline}): {msg}",
        ).format(
            ts=timestamp,
            sender=sender,
            airline=airline,
            msg=msg_text,
        )
        mw.label_global_acars_ticker.setText(banner)
        mw.label_global_acars_ticker.show()
        mw.label_global_acars_ticker.repaint()
        mw.label_global_acars_ticker.update()
        hud = getattr(mw, "_external_acars_hud", None)
        if hud is not None:
            hud.show_dispatch(banner)

    @Slot(str)
    def _on_message_received(self, raw_message: str) -> None:
        try:
            data = json.loads(raw_message)
        except json.JSONDecodeError:
            return
        if not isinstance(data, dict):
            return
        timestamp = str(data.get("timestamp", "00:00"))
        sender = str(data.get("sender", "?"))
        airline = str(data.get("airline", ""))
        msg_text = str(data.get("message", ""))
        line = f"[{timestamp}] {sender} ({airline}): {msg_text}\n"
        self.txt_history.append(line)
        self._push_acars_ticker_banner(timestamp, sender, airline, msg_text)


class MainWindow(QMainWindow):
    language_changed = Signal(str)

    def _i18n_register(self, w: QWidget | QAction, key: str, default: str) -> None:
        self._i18n_widgets.append((w, key, default))

    def _emit_language_changed(self) -> None:
        lang = getattr(self, "_ui_lang", "de") or "de"
        self.language_changed.emit(lang)
        for child in self.findChildren(QWidget):
            handler = getattr(child, "_on_language_changed", None)
            if callable(handler):
                try:
                    handler(lang)
                except Exception:
                    pass

    def pull_fids_board_data(self) -> None:
        """Cloud-Bridge: Live-Flugtafel nach Radar-Ping sofort aktualisieren."""
        self.fetch_global_online_pilots_fids()

    def _retranslate_i18n_widgets(self) -> None:
        for w, key, default in getattr(self, "_i18n_widgets", []):
            t = self._tr(key, default)
            if isinstance(w, QAction):
                w.setText(t)
            elif isinstance(w, QGroupBox):
                w.setTitle(t)
            elif isinstance(w, (QLabel, QPushButton, QCheckBox, QRadioButton)):
                w.setText(t)
        self._refresh_ionos_hint_label()
        try:
            self._retranslate_fids_table_headers()
        except Exception:
            pass
        try:
            self._retranslate_acars_ui()
        except Exception:
            pass
        try:
            self.fetch_global_online_pilots_fids()
        except Exception:
            pass

    def _retranslate_acars_ui(self) -> None:
        if hasattr(self, "label_global_acars_ticker"):
            idle = self._tr(
                "acars.banner_idle",
                "📡 ACARS-System: Warte auf offizielle Flugfunk-Meldungen…",
            )
            cur = self.label_global_acars_ticker.text()
            if not cur or "ACARS DISPATCH" not in cur and "DISPATCH" not in cur:
                self.label_global_acars_ticker.setText(idle)
        aw = getattr(self, "acars_widget", None)
        if aw is not None and hasattr(aw, "_populate_acars_template_combo"):
            aw._populate_acars_template_combo()

    def _refresh_ionos_hint_label(self) -> None:
        if not hasattr(self, "label_ionos_server_hint"):
            return
