    def _hub_inner_current_is(self, hub_ix: int, leaf: QWidget) -> bool:
        if self.tab_widget.currentIndex() != hub_ix:
            return False
        inner = self._hub_tabwidgets.get(hub_ix)
        return inner is not None and inner.currentWidget() is leaf

    def _on_hub_inner_tab_changed(self, hub_ix: int) -> None:
        if hub_ix == getattr(self, "_hub_ix_bank", -999):
            inner = self._hub_tabwidgets.get(hub_ix)
            if inner is not None:
                self._on_bank_inner_subtab_changed(inner.currentIndex())
        elif hub_ix == getattr(self, "_hub_ix_career", -999):
            if hasattr(self, "_refresh_profile_tab"):
                self._refresh_profile_tab()

    def _inject_hangar_scrapyard_once(self) -> None:
        if getattr(self, "_hangar_scrapyard_injected", False):
            return
        self._inject_hangar_scrapyard_subtab()
        self._hangar_scrapyard_injected = True

    def _inject_hangar_scrapyard_subtab(self) -> None:
        """Gebraucht-/Neuteile-Märkte in Hangar-Unter-Reiter (idempotent)."""
        if not hasattr(self, "tab_used_scrapyard") or self.tab_used_scrapyard is None:
            self.tab_used_scrapyard = HighEndScrapyardAndNewPartsWidget(
                self, market_type="USED_SCRAPYARD"
            )
            self.cloud_scrapyard_widget = self.tab_used_scrapyard
        if not hasattr(self, "tab_new_parts_market") or self.tab_new_parts_market is None:
            self.tab_new_parts_market = HighEndScrapyardAndNewPartsWidget(
                self, market_type="NEW_PART"
            )
        inner = getattr(self, "hangar_inner_tabs", None)
        if not isinstance(inner, QTabWidget):
            return
        for widget, sk, default in (
            (
                self.tab_used_scrapyard,
                "hangar.tab.scrapyard_used",
                "⚙️ Cloud-Schrottplatz (Gebraucht)",
            ),
            (
                self.tab_new_parts_market,
                "hangar.tab.parts_new",
                "💎 Hangar-Neuteile (100 %)",
            ),
        ):
            if inner.indexOf(widget) < 0:
                inner.addTab(widget, self._tr(sk, default))

    def _inject_force_main_tabs(self) -> None:
        """Unter-Reiter nachziehen (Scrapyard, Allianz-Forschung)."""
        self._inject_hangar_scrapyard_subtab()
        dash = getattr(self, "advanced_alliance_dashboard", None)
        if dash is not None and hasattr(dash, "sub_tabs"):
            research_title = self._tr("alliance.sub.research", "🔬 Allianz-Forschung")
            rw = getattr(dash, "research_widget", None)
            if rw is not None:
                found = False
                for i in range(dash.sub_tabs.count()):
                    if dash.sub_tabs.widget(i) is rw:
                        dash.sub_tabs.setTabText(i, research_title)
                        found = True
                        break
                if not found:
                    dash.sub_tabs.insertTab(3, rw, research_title)

