    def _startup_sound_assets_if_needed(self) -> None:
        try:
            ensure_builtin_sound_wavs()
        except OSError:
            pass
        if SOUND_ASSET_MANIFEST:
            root = assets_sounds_dir()
            missing = any(
                not (root / fn).is_file() or (root / fn).stat().st_size < 64
                for fn, _ in SOUND_ASSET_MANIFEST
            )
            if missing:
                self._set_status_safe("Zusätzliche Sound-URLs werden geladen …", 12_000)
                errs = self._run_sound_download(force=False, show_errors=False)
                if errs:
                    self._set_status_safe(
                        f"Sound-Download: {len(errs)} Fehler (Netz / URLs).",
                        12_000,
                    )

    def _run_sound_download(self, *, force: bool, show_errors: bool) -> list[str]:
        ensure_builtin_sound_wavs()
        self.progress_sound_dl.setVisible(True)
        self.progress_sound_dl.setMaximum(
            max(1, len(SOUND_ASSET_MANIFEST) + 1)
        )
        self.progress_sound_dl.setValue(0)

        def prog(i: int, total: int, name: str) -> None:
            self.progress_sound_dl.setMaximum(total)
            self.progress_sound_dl.setValue(i)
            self.progress_sound_dl.setFormat(f"Lade Sound-Assets … {name}")
            QApplication.processEvents()

        errs = download_sound_assets(force, prog)
        self.progress_sound_dl.setVisible(False)
        self.progress_sound_dl.setFormat("%p%")
        if errs and show_errors:
            QMessageBox.warning(self, self._tr("ui.auto.sound_download_6efbfdbb", "Sound-Download"), "Einige Dateien fehlen oder konnten nicht geladen werden:\n"
                + "\n".join(errs[:12]),
            )
        elif not errs and show_errors:
            QMessageBox.information(self, self._tr("ui.msg.sound_download", "Sound-Download"), self._tr("ui.msg.sound_complete", "Sound-Paket ist vollständig."))
        return errs

    def _on_sound_download_clicked(self) -> None:
        self._run_sound_download(force=False, show_errors=True)

    def _on_sound_repair_clicked(self) -> None:
        ret = QMessageBox.question(self, self._tr("ui.auto.sound_paket_08f4cd15", "Sound-Paket"), self._tr("ui.auto.alle_sound_dateien_l_schen_und_neu_herunterladen_acf523ec", "Alle Sound-Dateien löschen und neu herunterladen?"),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if ret != QMessageBox.StandardButton.Yes:
            return
        root = assets_sounds_dir()
        for fname in SOUND_PACK_FILENAMES:
            p = root / fname
            if p.is_file():
                try:
                    p.unlink()
                except OSError:
                    pass
        for fname, _u in SOUND_ASSET_MANIFEST:
            p = root / fname
            if p.is_file():
                try:
                    p.unlink()
                except OSError:
                    pass
        self._run_sound_download(force=True, show_errors=True)

