    def _sound_path(self, fname: str) -> Path:
        bundled = get_resource_path(f"assets/sounds/{fname}")
        if bundled.is_file():
            return bundled
        return assets_sounds_dir() / fname

    def _test_audio_master(self) -> None:
        p = self._sound_path("dingdong.wav")
        if p.is_file():
            self._audio.play_effect_file(p)

    def _test_audio_cabin(self) -> None:
        for fname in ("cabin_chime.wav", "boarding_chime.wav"):
            p = self._sound_path(fname)
            if p.is_file():
                self._audio.play_effect_file(p)
                return
        self._set_status_safe(
            "cabin_chime.wav / boarding_chime.wav fehlt – bitte Sound-Paket laden.",
            6000,
        )

    def _test_audio_copilot(self) -> None:
        p = assets_sounds_dir() / "_tts_test_copilot.wav"
        if tts_export_wav(
            "Copilot-Test. Eins zwei drei.", p, rate=178
        ):
            try:
                self._audio.play_tts_wav(p)
            except Exception:
                tts_speak_async("Copilot test.")
        else:
            tts_speak_async("Copilot test.")

    def _test_audio_effects(self) -> None:
        p = self._sound_path("dingdong.wav")
        if p.is_file():
            self._audio.play_effect_file(p)

