    def _persist_airline_selection_from_brand_combo(self) -> None:
        code_raw = self.combo_brand_airline.currentData()
        code = str(code_raw).strip().upper() if code_raw is not None else ""
        if len(code) != 3:
            txt = self.combo_brand_airline.currentText().strip()
            if "(" in txt and txt.rstrip().endswith(")"):
                inner = txt[txt.rfind("(") + 1 :].rstrip(")")
                code = inner.strip().upper()[:3]
            else:
                code = (app_meta_get(DB_PATH, "selected_airline_icao", "DLH") or "DLH")[
                    :3
                ]
        name_txt = self.combo_brand_airline.currentText().strip()
        if "(" in name_txt:
            name_txt = name_txt[: name_txt.rfind("(")].strip()
        if not name_txt:
            name_txt = app_meta_get(DB_PATH, "selected_airline_name", "Airline")
        app_meta_set(DB_PATH, "selected_airline_icao", code[:3])
        app_meta_set(DB_PATH, "selected_airline_name", name_txt[:80])
        if len(code) == 3:
            try:
                try_download_airline_logo(code[:3])
            except Exception:
                pass
        self.update_airline_branding()

    def _on_online_network_toggled(self, checked: bool) -> None:
        app_meta_set(DB_PATH, "online_network_enabled", "1" if checked else "0")
        if hasattr(self, "mp_share_timer"):
            self.mp_share_timer.setInterval(
                5000 if checked and ionos_server_url().strip() else 30_000
            )
        if hasattr(self, "ionos_status_timer"):
            if checked and ionos_server_url().strip():
                self.ionos_status_timer.start()
            else:
                self.ionos_status_timer.stop()
                app_meta_set(DB_PATH, "cloud_maintenance_active", "0")
                app_meta_set(DB_PATH, "ionos_maintenance_message", "")
                self._sync_maintenance_overlay()
        aw = getattr(self, "acars_widget", None)
        if aw is not None:
            if checked and ionos_server_url().strip():
                aw._reconnect_timer.start()
                aw.connect_to_ionos_acars_server()
            else:
                aw._reconnect_timer.stop()
                if aw.ws_client is not None:
                    aw.ws_client.close()
                aw.lbl_status.setText(
                    self._tr(
                        "acars.status_need_online",
                        "ACARS: Online-Netzwerk in den Einstellungen aktivieren.",
                    )
                )
                aw.lbl_status.setStyleSheet("font-weight: bold; color: #ffaa00;")

    def _ionos_status_poll_nam(self) -> None:
        if not online_network_enabled(DB_PATH) or not ionos_server_url().strip():
            return
        req = QNetworkRequest(QUrl(f"{ionos_server_url()}/api/v1/status"))
        rep = self._nam.get(req)
        rep.setProperty("kind", "ionos_status")

    def _on_save_sound_tab_clicked(self) -> None:
        app_meta_set(DB_PATH, "ui_lang", self._ui_lang)
        app_meta_set(
            DB_PATH,
            "pilot_display_name",
            self.edit_brand_pilot.text().strip() or "Pilot",
        )
        app_meta_set(
            DB_PATH,
            "pilot_name",
            self.edit_brand_pilot.text().strip() or "Pilot",
        )
        self._persist_airline_selection_from_brand_combo()
        app_meta_set(DB_PATH, "tts_lang", self.combo_tts_lang_sound.currentText()[:2])
        app_meta_set(DB_PATH, "tts_voice", self.combo_tts_voice_sound.currentText())
        app_meta_set(DB_PATH, "copilot_v1_kts", str(int(self.spin_v1.value())))
        app_meta_set(DB_PATH, "copilot_vr_kts", str(int(self.spin_vr.value())))
        self._audio.set_master_linear(self.slider_master.value() / 100.0)
        self._audio.set_bus_cabin(self.slider_cabin.value() / 100.0)
        self._audio.set_bus_copilot(self.slider_copilot.value() / 100.0)
        self._audio.set_bus_effects(self.slider_effects.value() / 100.0)
        self._audio.save_mixer_to_meta(DB_PATH)
        if hasattr(self, "combo_tts_lang"):
            self.combo_tts_lang.blockSignals(True)
            lang_code = self.combo_tts_lang_sound.currentText().strip()[:2]
            lix = self.combo_tts_lang.findText(lang_code)
            if lix >= 0:
                self.combo_tts_lang.setCurrentIndex(lix)
            self.combo_tts_lang.blockSignals(False)
        if hasattr(self, "combo_tts_voice"):
            self.combo_tts_voice.blockSignals(True)
            self.combo_tts_voice.setCurrentText(self.combo_tts_voice_sound.currentText())
            self.combo_tts_voice.blockSignals(False)
        self.update_airline_branding()
        if hasattr(self, "edit_mp_pilot"):
            self.edit_mp_pilot.setText(app_meta_get(DB_PATH, "pilot_display_name", "Pilot"))
        QMessageBox.information(
            self,
            self._tr("sound.save_ok_title", "Sound & Sprache"),
            self._tr("sound.save_ok_body", "Einstellungen gespeichert."),
        )

    def _captain_announce(self, kind: str) -> None:
        en = self._ui_lang == "en"
        if kind == "welcome":
            delta = 4.0
            msg = (
                "Ladies and gentlemen, welcome on board. We hope you enjoy the flight."
                if en
                else "Sehr geehrte Gäste, herzlich willkommen an Bord. "
                "Wir wünschen Ihnen einen angenehmen Flug."
            )
        elif kind == "turb":
            delta = -3.0
            msg = (
                "We are expecting some turbulence. Please remain seated with seatbelts fastened."
                if en
                else "Wir rechnen mit Turbulenzen. Bitte bleiben Sie sitzen und anschnallen."
            )
        elif kind == "delay":
            delta = -6.0
            msg = (
                "We apologize for the delay. We are doing our best to make up time."
                if en
                else "Wir bitten um Entschuldigung für die Verspätung. "
                "Wir bemühen uns, den Rückstand aufzuholen."
            )
        else:
            return
        self._passenger_satisfaction = max(0.0, min(100.0, self._passenger_satisfaction + delta))
        self._refresh_passenger_label()
        self._tts_speak_line(msg, cabin_style=True, force=True)

    def _auto_announce_enabled(self) -> bool:
        return app_meta_get(DB_PATH, "auto_announcements", "1") == "1"

    def _copilot_speak(self, text: str, *, prefer_mixer: bool = True) -> None:
        if not self._auto_announce_enabled():
            return
        if prefer_mixer and _PYTTSX3_AVAILABLE:
            cache = assets_sounds_dir() / "_tts_copilot_last.wav"
            try:
                if cache.is_file():
                    cache.unlink()
            except OSError:
                pass

            def work() -> None:
                ok = tts_export_wav(text, cache)
                if ok:
                    with self._tts_q_lock:
                        self._pending_tts_wav = cache

            threading.Thread(target=work, daemon=True).start()
        else:
            tts_speak_async(text)

    def _flush_pending_tts_wav(self) -> None:
        with self._tts_q_lock:
            p = self._pending_tts_wav
            self._pending_tts_wav = None
        if p is not None and p.is_file():
            try:
                self._audio.play_tts_wav(p)
            except Exception:
                tts_speak_async("")

    def _read_landing_lights_on(self) -> bool:
        if self._aq is None:
            return True
        keys = (
            "L:S_OH_EXT_LT_LANDING_L",
            "L:S_OH_EXT_LT_LANDING_R",
            "L:FENIX_LIGHTING_LANDING_LTS",
            "L:XMLVAR_LandingLights",
            "L:XMLVAR_LandingMaster",
            "L:PMDG_LIGHT_LANDING",
            "L:PMDG_LIGHT_LANDING_2",
            "LIGHT LANDING ON",
            "LIGHT LANDING",
            "LIGHT LANDING:1",
            "LANDING LIGHTS ON",
            "LIGHT_ON:3",
            "LANDING_LIGHTS_ON",
        )

        def _pos(raw: object) -> bool | None:
            if raw is None:
                return None
            if isinstance(raw, (bool, int)):
                return bool(raw)
            s = str(raw).strip().lower()
            if s in ("true", "1", "on", "yes"):
                return True
            if s in ("false", "0", "off", "no", ""):
                return False
            fv = _as_float(raw)
            if fv is not None:
                return fv > 0.5
            return None

        on_any = False
        saw = False
        for key in keys:
            raw = self._aq.get(key)
            if raw is None:
                continue
            saw = True
            st = _pos(raw)
            if st is True:
                on_any = True
            elif st is False:
                pass
        if saw:
            return on_any
        return True

    def _copilot_audio_tick(
        self,
        on_ground: bool,
        airborne: bool,
        eng1_on: bool,
        ias: float | None,
        vs_fpm: float | None,
        alt_ft: float | None,
        gear_pct: float | None,
        flaps_pct: float | None,
        g_force: float | None,
    ) -> None:
        if on_ground and ias is not None and ias < 22.0:
            self._co_v1_done = False
            self._co_rotate_done = False
            self._co_gear_up_done = False
            self._co_flaps_up_done = False
            self._co_ll_warn_done = False

        if g_force is not None:
            self._g_hist.append(float(g_force))
            self._g_hist[:] = self._g_hist[-22:]

        if airborne and len(self._g_hist) >= 10:
            m = sum(self._g_hist) / len(self._g_hist)
            var = sum((x - m) ** 2 for x in self._g_hist) / len(self._g_hist)
            sd = math.sqrt(var)
            now = time.monotonic()
            if sd > 0.28 and now - self._last_turb_fx_ts > 11.0:
                self._last_turb_fx_ts = now
                p = self._sound_path("turbulence_rattle.wav")
                if p.is_file():
                    try:
                        self._audio.play_effect_file(p)
                    except Exception:
                        pass

        v1 = int(app_meta_get(DB_PATH, "copilot_v1_kts", "125") or "125")
        vr = int(app_meta_get(DB_PATH, "copilot_vr_kts", "135") or "135")
        if on_ground and eng1_on and ias is not None:
            if not self._co_v1_done and ias >= float(v1):
                self._co_v1_done = True
                self._copilot_speak("V1.")
            if not self._co_rotate_done and ias >= float(vr):
                self._co_rotate_done = True
                self._copilot_speak(
                    "Rotate." if self._ui_lang == "en" else "Rotate. Hochziehen."
                )

        pg = self._prev_gear_pct
        if (
            airborne
            and vs_fpm is not None
            and vs_fpm > 200.0
            and gear_pct is not None
            and pg is not None
            and not self._co_gear_up_done
            and pg > 30.0
            and gear_pct < 12.0
        ):
            self._co_gear_up_done = True
            self._copilot_speak(
                "Positive rate. Gear up."
                if self._ui_lang == "en"
                else "Positiver Steigflug. Fahrwerk einfahren."
            )

        pf = self._prev_flaps
        if (
            airborne
            and flaps_pct is not None
            and pf is not None
            and not self._co_flaps_up_done
            and pf > 22.0
            and flaps_pct < 5.0
        ):
            self._co_flaps_up_done = True
            self._copilot_speak(
                "Flaps up." if self._ui_lang == "en" else "Klappen einfahren."
            )

        if alt_ft is not None:
            if alt_ft > 10_800.0 or on_ground:
                self._co_ll_warn_done = False
            elif (
                2500.0 < alt_ft < 10_000.0
                and not self._co_ll_warn_done
                and not self._read_landing_lights_on()
            ):
                self._co_ll_warn_done = True
                if self._ui_lang == "en":
                    self._copilot_speak(
                        "Reminder: landing lights below ten thousand feet.",
                        prefer_mixer=True,
                    )
                else:
                    self._copilot_speak(
                        "Hinweis: unter zehntausend Fuss Landescheinwerfer einschalten.",
                        prefer_mixer=True,
                    )

        if flaps_pct is not None:
            self._prev_flaps = flaps_pct

    def _realism_sound_tick(
        self,
        *,
        thrust_raw: object,
        belt_on: bool,
        airborne: bool,
        alt_ft: float | None,
        vs_fpm: float | None,
    ) -> None:
        thrust = _as_float(thrust_raw) or 0.0
        if thrust > 0.1 and not self._cabin_ambient_for_thrust:
            p = self._sound_path("ambient_boarding.wav")
            if p.is_file():
                try:
                    self._audio.start_cabin_loop(p)
                    self._audio.set_cabin_volume(0.22)
                    self._cabin_ambient_for_thrust = True
                except Exception:
                    pass
        if self._last_seatbelt_audio_state is None:
            self._last_seatbelt_audio_state = bool(belt_on)
        elif bool(belt_on) != bool(self._last_seatbelt_audio_state):
            self._last_seatbelt_audio_state = bool(belt_on)
            p = self._sound_path("dingdong.wav")
            if p.is_file():
                try:
                    self._audio.play_effect_file(p)
                except Exception:
                    pass
            if self._ui_lang == "en":
                self._copilot_speak(
                    "Ladies and gentlemen, welcome aboard SkyTycoon. Please fasten your seat belts and enjoy the flight.",
                    prefer_mixer=True,
                )
            else:
                self._copilot_speak(
                    "Meine Damen und Herren, willkommen an Bord von SkyTycoon. Bitte legen Sie den Sicherheitsgurt an und genießen Sie den Flug.",
                    prefer_mixer=True,
                )
        if (
            airborne
            and not self._cruise_altitude_announced
            and alt_ft is not None
            and alt_ft >= 28000.0
            and vs_fpm is not None
            and abs(vs_fpm) < 250.0
        ):
            self._cruise_altitude_announced = True
            self._copilot_speak(
                "Cruising altitude reached, Captain. Autopilot is managing the flight deck.",
                prefer_mixer=True,
            )
        if not airborne and alt_ft is not None and alt_ft < 3000.0:
            self._cruise_altitude_announced = False

    def _sync_dispatch_realism_from_cloud(self) -> None:
        base = ionos_api_base_url().strip().rstrip("/")
        if not base or not online_network_enabled(DB_PATH):
            return
        body = build_ionos_cloud_sync_body(DB_PATH, pull_only=True)
        if not body.get("password"):
            return
        try:
            r = requests.post(
                f"{base}/api/v1/dispatch/pc_sync",
                json=body,
                timeout=8,
                headers=ionos_auth_headers(DB_PATH),
            )
            data = r.json()
        except (requests.RequestException, json.JSONDecodeError, ValueError):
            return
        if not isinstance(data, dict) or not data.get("ok"):
            return
        ground = data.get("ground") if isinstance(data.get("ground"), dict) else {}
        sheet = data.get("loadsheet") if isinstance(data.get("loadsheet"), dict) else {}
        status = str((ground or {}).get("status") or "BLOCKED")
        self._departure_ready = status == "DEPARTURE_READY"
        app_meta_set(DB_PATH, "ground_service_status", status)
        if sheet:
            app_meta_set(DB_PATH, "captain_loadsheet_json", json.dumps(sheet, ensure_ascii=False)[:20000])
            self._append_log(
                "Loadsheet Sync: "
                f"{sheet.get('origin', '----')}→{sheet.get('destination', '----')} "
                f"ZFW {sheet.get('zfw_lbs', 0)} lb / CG {sheet.get('cg_percent', 0)}%."
            )

    def _enforce_ground_handshake_lock(self, on_ground: bool, eng1_on: bool) -> None:
        if not self._active_job or self._departure_ready or not on_ground:
            return
        if eng1_on and time.monotonic() - getattr(self, "_last_ground_lock_warn", 0.0) > 12.0:
            self._last_ground_lock_warn = time.monotonic()
            self._append_log(
                self._tr(
                    "ground.lock_warn",
                    "Ground Handshake: Cockpit noch gesperrt. Bitte Web-Dispatcher starten und Boarding auf 100 % bringen.",
                )
            )
            try:
                if self._aq is not None:
                    self._aq.set("PARKING BRAKE", 1.0)
            except Exception:
                pass

    def _maybe_play_applause_pax(self, vs_fpm: float | None) -> None:
        if vs_fpm is None:
            return
        if self._active_job and str(self._active_job.get("typ")) != "PAX":
            return
        if vs_fpm <= -150.0:
            return
        p = self._sound_path("applause.wav")
        if p.is_file():
            try:
                self._audio.play_effect_file(p)
            except Exception:
                pass

    def _schedule_update_check(self, force: bool = False) -> None:
        if not force and (self._update_checked_this_session or self._update_check_inflight):
            return
        url = effective_update_version_url().strip()
        if not url:
            if force:
                QMessageBox.information(
                    self,
                    self._tr("help.update_title", "Update-Check"),
                    self._tr(
                        "help.update_no_url",
                        "Keine Update-URL konfiguriert (version.json). Installierte Version: {v}.",
                    ).format(v=APP_VERSION),
                )
            self._update_checked_this_session = True
            return
        if not force:
            self._update_checked_this_session = True
        self._update_check_inflight = True
        req = QNetworkRequest(QUrl(url))
        rep = self._nam.get(req)
        rep.setProperty("kind", "update_check")
        rep.setProperty("manual", bool(force))

    def _show_update_available_dialog(
        self,
        remote: str,
        dl: str,
        extra_ln: str,
        mandatory: bool,
        changelog: str,
    ) -> None:
        dlg = QDialog(self)
        dlg.setWindowTitle(self._tr("help.update_title", "Update-Check"))
        dlg.setMinimumWidth(540)
        lay = QVBoxLayout(dlg)
        lay.addWidget(
            QLabel(
                self._tr(
                    "help.update_newer_fmt",
                    "Server-Version: {remote}\nInstalliert: {local}{extra}",
                ).format(remote=remote, local=APP_VERSION, extra=extra_ln or "")
            )
        )
        te = QTextEdit()
        te.setReadOnly(True)
        te.setMinimumHeight(180)
        te.setPlainText(
            (changelog or "").strip()
            or self._tr("help.update_no_changelog_body", "(Kein Changelog.)")
        )
        lay.addWidget(te)
        row = QHBoxLayout()
        b_dl = QPushButton(self._tr("help.update_btn_download", "Jetzt herunterladen"))
        if dl.strip():
            b_dl.clicked.connect(lambda u=QUrl(dl): QDesktopServices.openUrl(u))
        else:
            b_dl.setEnabled(False)
        row.addWidget(b_dl)
        b_later = QPushButton(self._tr("help.update_btn_later", "Später fortfahren"))
        b_later.clicked.connect(dlg.accept)
        if mandatory:
            b_later.setVisible(False)
        row.addWidget(b_later)
        lay.addLayout(row)
        dlg.exec()

    def _on_cloud_sync_timer_tick(self) -> None:
        """Gestaffelt: weniger parallele Server-Calls, UI entlastet."""
        self._cloud_sync_round = int(getattr(self, "_cloud_sync_round", 0)) + 1
        rnd = self._cloud_sync_round
        try:
            if self._ionos_cloud_ready():
                if self._is_main_hub_active("_hub_ix_alliance"):
                    self._request_alliance_check()
                elif rnd % 4 == 0:
                    self._request_alliance_check_direct()
                if rnd % 2 == 0:
                    self._sync_dispatch_realism_from_cloud()
        except Exception:
            pass
        if getattr(self, "_cloud_poll_inflight", False):
            return
        u = _cloud_global_config_url()
        if u:
            self._cloud_poll_inflight = True
            req = QNetworkRequest(QUrl(u))
            rep = self._nam.get(req)
            rep.setProperty("kind", "cloud_global_config_poll")
            return
        u2 = _cloud_banned_users_map_url()
        if u2:
            self._cloud_poll_inflight = True
            req2 = QNetworkRequest(QUrl(u2))
            rep2 = self._nam.get(req2)
            rep2.setProperty("kind", "cloud_banned_users_poll")
            return
        try:
            force_econ = rnd % 4 == 0 or self._is_main_hub_active(
                "_hub_ix_career"
            ) or self._is_main_hub_active("_hub_ix_bank")
            cloud_global_econ_bundle(force_refresh=force_econ)
            if getattr(self, "_active_job", None) or self._is_main_hub_active(
                "_hub_ix_dispatch"
            ):
                self._refresh_leg_fuel_status()
            self._refresh_credits_label()
        except Exception:
            pass

    def _trigger_cloud_ban_exit_dialog(self, message: str | None = None) -> None:
        if getattr(self, "_mid_session_ban_quit_scheduled", False):
            return
        self._mid_session_ban_quit_scheduled = True
        body = message or self._tr(
            "security.banned_exit",
            "Zugriff verweigert. Die Sitzung wird beendet.",
        )
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Critical)
        box.setWindowModality(Qt.WindowModality.ApplicationModal)
        box.setWindowTitle(self._tr("security.banned_title", "SkyTycoon Pro"))
        box.setText(body)
        box.setStandardButtons(QMessageBox.StandardButton.Ok)
        box.exec()
        QTimer.singleShot(0, self.close)

    def _cloud_post_poll_refresh(self) -> None:
        self._cloud_poll_inflight = False
        try:
            blocked, ban_msg = is_launch_blocked_by_cloud_or_license(DB_PATH, None)
            if blocked:
                self._trigger_cloud_ban_exit_dialog(ban_msg)
        except Exception:
            pass
        try:
            if self._hangar_market_fetch_wanted():
                if firebase_p2p_base_url():
                    fetch_market_listings(DB_PATH)
                self._refresh_p2p_table()
            elif self._is_main_hub_active("_hub_ix_hangar"):
                self._refresh_p2p_table()
        except Exception:
            pass
        try:
            rnd_e = int(getattr(self, "_cloud_sync_round", 0))
            force_econ = rnd_e % 4 == 0 or self._is_main_hub_active(
                "_hub_ix_career"
            ) or self._is_main_hub_active("_hub_ix_bank")
            cloud_global_econ_bundle(force_refresh=force_econ)
            if getattr(self, "_active_job", None) or self._is_main_hub_active(
                "_hub_ix_dispatch"
            ):
                self._refresh_leg_fuel_status()
            self._refresh_credits_label()
        except Exception:
            pass
        try:
            raw = (app_meta_get(DB_PATH, "cloud_global_config_json", "") or "").strip()
            if raw:
                cfg = json.loads(raw)
                if isinstance(cfg, dict):
                    apply_global_config_cloud_to_meta(DB_PATH, cfg)
        except Exception:
            pass
        try:
            self._sync_maintenance_overlay()
        except Exception:
            pass
        try:
            if int(getattr(self, "_cloud_sync_round", 0)) % 3 == 0:
                self._poll_support_ticket_head_firebase()
        except Exception:
            pass
        try:
            rnd = int(getattr(self, "_cloud_sync_round", 0))
            need_snap = (
                self._is_main_hub_active("_hub_ix_career")
                or self._is_main_hub_active("_hub_ix_bank")
                or rnd % 3 == 0
            )
            if need_snap:
                self._request_cloud_profile_snapshot_poll()
        except Exception:
            pass

    def _request_cloud_profile_snapshot_poll(self, *, force: bool = False) -> None:
        """Meilenstein 170: Server-Profil (Credits/XP/…) für Live-Abgleich mit Admin-Cloud."""
        now = time.monotonic()
        if not force and (
            now - float(getattr(self, "_profile_snapshot_last_mono", 0.0) or 0.0)
        ) < 50.0:
            return
        self._profile_snapshot_last_mono = now
        if getattr(self, "_cloud_profile_snapshot_inflight", False):
            return
        base = (ionos_api_base_url() or "").strip().rstrip("/")
        pw = self._cloud_password_stored()
        if not base or not pw:
            return
        self._cloud_profile_snapshot_inflight = True
        hid = p2p_hardware_id(DB_PATH)
        q = urlencode({"hardware_id": hid, "password": pw})
        req = QNetworkRequest(QUrl(f"{base}/api/v1/user/profile_snapshot?{q}"))
        rep = self._nam.get(req)
        rep.setProperty("kind", "cloud_profile_snapshot_poll")

    @Slot(dict)
    def _force_thread_safe_dashboard_refresh(self, data: dict) -> None:
        """Wendet Server-Snapshot an und aktualisiert alle Finanz-/Profil-Widgets im GUI-Thread."""
        if not isinstance(data, dict):
            return
        sig = (
            float(data.get("credits", 0) or 0),
            float(data.get("xp", 0) or 0),
            float(data.get("reputation", 0) or 0),
            str(data.get("active_global_news", "") or "")[:200],
        )
        now = time.monotonic()
        if (
            sig == getattr(self, "_last_dashboard_sync_sig", None)
            and (now - float(getattr(self, "_last_dashboard_sync_mono", 0.0) or 0.0))
            < 25.0
        ):
            return
        self._last_dashboard_sync_sig = sig
        self._last_dashboard_sync_mono = now
        self._apply_global_news_banner(
            str(data.get("active_global_news", "") or "").strip()
        )
        try:
            if not apply_cloud_profile_snapshot_to_career_db(DB_PATH, data):
                return
        except Exception as exc:
            print(f"[ERROR SYNC] apply_cloud_profile_snapshot: {exc}")
            return
        try:
            self._refresh_alliance_panel()
        except Exception:
            pass
        try:
            self._refresh_career_hub_header()
        except Exception:
            pass
        try:
            n_fired = hr_auto_fire_low_satisfaction(DB_PATH)
            if n_fired:
                print(f"[HR] {n_fired} Crew entlassen (niedrige Zufriedenheit).")
        except Exception:
            pass
        try:
            credits_val = float(data.get("credits", 0) or 0)
            xp_val = float(data.get("xp", 0) or 0)
            rep_val = float(data.get("reputation", 0) or 0)
            self._refresh_finances_after_cloud_snapshot()
            print_sig = (credits_val, int(xp_val), round(rep_val, 1))
            if print_sig != getattr(self, "_last_success_sync_print_sig", None):
                self._last_success_sync_print_sig = print_sig
                print(
                    f"[SUCCESS SYNC] Dashboard OK: Credits {format_eur_de(credits_val)} | "
                    f"XP {int(xp_val)} | Rep {rep_val:.1f}",
                    flush=True,
                )
        except Exception as e:
            print(f"[ERROR SYNC RENDERING] Fehler im GUI-Thread: {e!s}")

    def _apply_global_news_banner(self, message: str) -> None:
        msg = (message or "").strip()
        if not msg:
            msg = (app_meta_get(DB_PATH, "active_global_news_cached", "") or "").strip()
        if hasattr(self, "label_news_ticker"):
            if not msg:
                self.label_news_ticker.setText(
                    self._tr("career.news_idle", "News: Markt normal")
                )
            else:
                self.label_news_ticker.setText(msg)
            self.label_news_ticker.show()
        if hasattr(self, "label_global_news_banner"):
            self.label_global_news_banner.hide()
        if not msg:
            if hasattr(self, "_global_news_blink_timer"):
                self._global_news_blink_timer.stop()
            return
        if hasattr(self, "_global_news_blink_timer"):
            if not self._global_news_blink_timer.isActive():
                self._global_news_blink_timer.start()

    def _on_global_news_blink_tick(self) -> None:
        if not hasattr(self, "label_global_news_banner"):
            return
        banner = self.label_global_news_banner
        if not banner.isVisible():
            self._global_news_blink_timer.stop()
            return
        self._global_news_blink_on = not self._global_news_blink_on
        if self._global_news_blink_on:
            self.label_global_news_banner.setStyleSheet(
                "background-color:#5d4a1a;color:#ffe082;font-weight:800;font-size:14px;"
                "padding:10px 14px;border:2px solid #ffca28;border-radius:8px;"
            )
        else:
            self.label_global_news_banner.setStyleSheet(
                "background-color:#3d3520;color:#ffd54f;font-weight:800;font-size:14px;"
                "padding:10px 14px;border:2px solid #d4af37;border-radius:8px;"
            )

    def _refresh_finances_after_cloud_snapshot(self) -> None:
        """Harter UI-Refresh nach Cloud-Snapshot (Labels + Qt-Repaint)."""
        self._credits = load_credits(DB_PATH)
        self._refresh_credits_label()
        self._refresh_bank_tab()
        if hasattr(self, "_refresh_profile_tab"):
            self._refresh_profile_tab()
        if hasattr(self, "_refresh_ceo_report_panel"):
            self._refresh_ceo_report_panel()
        for name in (
            "label_bank_credits",
            "label_prof_rank",
            "prog_xp",
            "prog_credit_score",
            "label_brand_pilot",
        ):
            w = getattr(self, name, None)
            if w is not None:
                try:
                    w.update()
                    w.repaint()
                except Exception:
                    pass
        try:
            self.update()
        except Exception:
            pass

    def _refresh_alliance_panel(self) -> None:
        """Zeigt Allianz-Name, Rolle und geleaste Hub-ICAOs aus Cloud-Snapshot."""
        if not hasattr(self, "label_alliance_summary"):
            return
        raw = (app_meta_get(DB_PATH, "alliance_snapshot_json", "") or "").strip()
        if not raw:
            self.label_alliance_summary.setText(
                self._tr(
                    "alliance.none",
                    "Keine Allianz-Daten. Cloud-Sync mit Passwort aktivieren.",
                )
            )
            return
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            self.label_alliance_summary.setText("—")
            return
        if not isinstance(data, dict):
            self.label_alliance_summary.setText("—")
            return
        name = str(
            data.get("alliance_name", data.get("name", "")) or ""
        ).strip() or "—"
        role = str(data.get("role", "") or "").strip()
        leased = sorted(active_alliance_leased_icaos(DB_PATH))
        lines = [
            f"{self._tr('alliance.name', 'Allianz')}: {name}",
        ]
        if role:
            lines.append(f"{self._tr('alliance.role', 'Rolle')}: {role}")
        if leased:
            hubs_txt = ", ".join(leased)
            lines.append(
                f"{self._tr('alliance.leased_hubs', 'Geleaste Hubs')}: {hubs_txt}"
            )
        self.label_alliance_summary.setText("\n".join(lines))

    def _cloud_password_stored(self) -> str:
        return cloud_password_get(DB_PATH)

    def _save_cloud_password(self, password: str) -> None:
        cloud_password_set(DB_PATH, password)

    def _ionos_cloud_body(self, *, pull_only: bool = False) -> dict[str, object]:
        body = build_ionos_cloud_sync_body(DB_PATH, pull_only=pull_only)
        if pull_only:
            la = self._last_plane_lat
            lo = self._last_plane_lon
            if (la is None or lo is None) and self._aq is not None:
                la = _as_float(self._aq.get("PLANE LATITUDE"))
                lo = _as_float(self._aq.get("PLANE LONGITUDE"))
            if la is not None and lo is not None:
                body["lat"] = float(la)
                body["lon"] = float(lo)
        return body

    def _ionos_cloud_ready(self) -> bool:
        base = (ionos_api_base_url() or "").strip()
        body = self._ionos_cloud_body()
        return bool(base and body.get("password"))

    def _apply_pilot_name_from_cloud_sync(self, data: dict) -> None:
        """M188: Pilotenname aus Cloud-Sync sofort ins UI übernehmen."""
        if not isinstance(data, dict):
            return
        pn = str(
            data.get("pilot_name")
            or data.get("username")
            or data.get("pilot_display_name")
            or ""
        ).strip()
        if not pn:
            return
        self.pilot_display_name = pn[:120]
        try:
            app_meta_set(DB_PATH, "pilot_display_name", pn[:120])
            app_meta_set(DB_PATH, "pilot_name", pn[:120])
        except OSError:
            pass
        if hasattr(self, "edit_brand_pilot"):
            self.edit_brand_pilot.blockSignals(True)
            self.edit_brand_pilot.setText(pn[:120])
            self.edit_brand_pilot.blockSignals(False)
        if hasattr(self, "edit_mp_pilot"):
            self.edit_mp_pilot.setText(pn[:120])
        self._refresh_branding_ui()

    def _request_alliance_check(self) -> None:
        """Vollständiger Profil-/Allianz-Vollstrom via ``/api/v1/user/sync_profile``."""
        if not self._ionos_cloud_ready():
            if hasattr(self, "label_alliance_status"):
                self.label_alliance_status.setText(
                    self._tr(
                        "alliance.cloud_required",
                        "Cloud-Passwort unter Datei → Cloud-Passwort hinterlegen.",
                    )
                )
            return
        if getattr(self, "_alliance_check_inflight", False):
            return
        self._alliance_check_inflight = True
        self._request_alliance_check_direct()
        body = self._ionos_cloud_body(pull_only=True)
        base = ionos_api_base_url().strip().rstrip("/")
        req = QNetworkRequest(QUrl(f"{base}/api/v1/user/sync_profile"))
        req.setHeader(
            QNetworkRequest.KnownHeaders.ContentTypeHeader, "application/json"
        )
        rep = self._nam.post(req, QByteArray(json.dumps(body).encode("utf-8")))
        rep.setProperty("kind", "sync_profile_pull")

    def _request_alliance_check_direct(self) -> None:
        """Dedizierter Allianz-Check (E-Mail/Lizenz-Auflösung für Web-Allianzen)."""
        if not self._ionos_cloud_ready():
            return
        if getattr(self, "_alliance_direct_inflight", False):
            return
        self._alliance_direct_inflight = True
        body = self._ionos_cloud_body()
        base = ionos_api_base_url().strip().rstrip("/")
        req = QNetworkRequest(QUrl(f"{base}/api/v1/user/alliance/check"))
        req.setHeader(
            QNetworkRequest.KnownHeaders.ContentTypeHeader, "application/json"
        )
        rep = self._nam.post(req, QByteArray(json.dumps(body).encode("utf-8")))
        rep.setProperty("kind", "alliance_check_direct")

    def _on_alliance_sync_reply_received(self, server_json: dict) -> None:
        if not isinstance(server_json, dict):
            return
        if not profile_cloud_payload_ok(server_json):
            if getattr(self, "_profile_dialog_pending_open", False):
                self._finish_customer_profile_dialog(None)
            if not getattr(self, "_alliance_cloud_ok", False):
                self._request_alliance_check_direct()
            return
        self._cached_server_profile_data = dict(server_json)
        try:
            apply_server_profile_authority(DB_PATH, server_json)
        except Exception:
            pass
        em = str(server_json.get("email", "") or "").strip()
        if em:
            try:
                app_meta_set(DB_PATH, "portal_email", em[:200])
            except OSError:
                pass
        self._apply_pilot_name_from_cloud_sync(server_json)
        alliance_box = server_json.get("alliance")
        if not isinstance(alliance_box, dict):
            alliance_box = {}
        canonical = str(server_json.get("hardware_id", "") or "").strip()
        if canonical:
            ionos_bind_hardware_id(DB_PATH, canonical)
        check_payload: dict[str, object] = {"ok": True}
        hub_list = alliance_box.get("hub_icaos") or alliance_box.get("alliance_hubs")
        if isinstance(hub_list, list):
            self.active_alliance_hubs_list = [
                str(x).upper()[:4] for x in hub_list if str(x).strip()
            ]
        if alliance_box.get("in_alliance"):
            self._alliance_my_alliance_id = str(alliance_box.get("alliance_id", "") or "")
            pool = float(
                alliance_box.get("alliance_credits", alliance_box.get("credits", 0))
                or 0
            )
            tax_pct = int(
                float(alliance_box.get("tax_pct", alliance_box.get("tax_rate", 0)) or 0)
            )
            check_payload.update(
                {
                    "in_alliance": True,
                    "alliance_id": alliance_box.get("alliance_id"),
                    "alliance_name": alliance_box.get("alliance_name"),
                    "role": alliance_box.get("role"),
                    "alliance_credits": pool,
                    "tax_pct": tax_pct,
                    "ceo_name": alliance_box.get("ceo_name"),
                    "members": alliance_box.get("members") or [],
                    "route_leases": alliance_box.get("route_leases") or [],
                    "public_alliances": alliance_box.get("public_alliances") or [],
                    "alliance_hubs": hub_list if isinstance(hub_list, list) else [],
                }
            )
        else:
            check_payload["in_alliance"] = False
            check_payload["public_alliances"] = (
                alliance_box.get("public_alliances") or []
            )
        self._apply_alliance_check_response(check_payload)
        if not check_payload.get("in_alliance"):
            self._request_alliance_check_direct()
        elif hasattr(self, "advanced_alliance_dashboard"):
            self._request_alliance_mega_state()
        snap_emit = {
            k: server_json[k]
            for k in (
                "credits",
                "xp",
                "reputation",
                "bank_loans",
                "anti_cheat_strikes",
                "credit_score",
                "active_global_news",
            )
            if k in server_json
        }
        if snap_emit:
            self._profile_cloud_bridge.profile_updated.emit(snap_emit)
        if server_json.get("logo_url"):
            self._fetch_custom_airline_logo_from_server()
        if int(server_json.get("has_license", 0) or 0) == 1:
            self._activate_msfs_pro_license_features(server_json)

    def _activate_msfs_pro_license_features(self, server_json: dict | None = None) -> None:
        """DRM-freier Multiplayer-Gottmodus: 3D-Traffic + Treibstoff-Persistenz."""
        if getattr(self, "_msfs_pro_features_active", False):
            return
        self._msfs_pro_features_active = True
        try:
            app_meta_set(DB_PATH, "license_activated", "1")
            if not (app_meta_get(DB_PATH, "license_key_installed", "") or "").strip():
                lk = str((server_json or {}).get("license_key", "") or "").strip()
                if lk:
                    app_meta_set(DB_PATH, "license_key_installed", lk[:256])
        except OSError:
            pass
        self._start_msfs_3d_traffic_injector()
        QTimer.singleShot(400, self.load_aircraft_persistence_state_from_cloud)
        self._append_log(
            self._tr(
                "msfs.pro_unlock_log",
                "SkyTycoon Pro: 3D-Traffic-Engine und Cloud-Persistenz aktiv.",
            )
        )

    def _start_msfs_3d_traffic_injector(self) -> None:
        """Pollt globalen Radar-Feed und spawnt nahe Piloten als MSFS-AI."""
        if getattr(self, "_msfs_3d_traffic_timer", None) is not None:
            return
        self._msfs_3d_traffic_spawned = {}
        t = QTimer(self)
        t.setInterval(MSFS_3D_TRAFFIC_POLL_MS)
        t.timeout.connect(self._tick_msfs_3d_traffic_radar_fetch)
        t.start()
        self._msfs_3d_traffic_timer = t
        QTimer.singleShot(800, self._tick_msfs_3d_traffic_radar_fetch)

    def _tick_msfs_3d_traffic_radar_fetch(self) -> None:
        if self._sm is None and self._aq is None:
            return
        base = ionos_api_base_url().strip() or ionos_server_url().strip()
        if not base:
            return
        req = QNetworkRequest(
            QUrl(f"{base.rstrip('/')}/api/v1/web/radar/positions")
        )
        rep = self._nam.get(req)
        rep.setProperty("kind", "radar_positions_3d")

    def _apply_msfs_3d_traffic_positions(self, positions: list) -> None:
        la = self._last_plane_lat
        lo = self._last_plane_lon
        if (la is None or lo is None) and self._aq is not None:
            la = _as_float(self._aq.get("PLANE LATITUDE"))
            lo = _as_float(self._aq.get("PLANE LONGITUDE"))
        if la is None or lo is None:
            return
        my_hw = p2p_hardware_id(DB_PATH)
        seen: set[str] = set()
        for p in positions:
            if not isinstance(p, dict):
                continue
            pid = str(p.get("id", p.get("hardware_id", "")) or "").strip()
            if not pid or pid == my_hw or pid == self._mp_client_id:
                continue
            try:
                plat = float(p["lat"])
                plon = float(p["lon"])
                palt = float(p.get("alt", 25000) or 25000)
                phdg = float(p.get("hdg", 0) or 0)
            except (KeyError, TypeError, ValueError):
                continue
            dnm = haversine_nm(float(la), float(lo), plat, plon)
            if dnm > MSFS_3D_TRAFFIC_RADIUS_NM:
                continue
            seen.add(pid)
            pilot = str(p.get("pilot", "?"))[:24]
            ac_title = str(p.get("aircraft", "") or "").strip()
            if not ac_title or ac_title.upper() in ("?", "UNKNOWN"):
                ac_title = "Airbus A320 Neo Asobo"
            tail = ("ST-" + pilot.replace(" ", "")[:6].upper())[:8] or "STPILOT"
            rec = self._msfs_3d_traffic_spawned.get(pid)
            if rec is None:
                spawned = self._try_spawn_msfs_ai_aircraft(
                    plat, plon, int(palt), ac_title, tail
                )
                self._msfs_3d_traffic_spawned[pid] = {
                    "lat": plat,
                    "lon": plon,
                    "alt_ft": int(palt),
                    "hdg": phdg,
                    "call": tail,
                    "pilot": pilot,
                    "spawned_msfs": spawned,
                }
            else:
                rec["lat"] = plat
                rec["lon"] = plon
                rec["alt_ft"] = int(palt)
                rec["hdg"] = phdg
        stale = [k for k in self._msfs_3d_traffic_spawned if k not in seen]
        for k in stale:
            del self._msfs_3d_traffic_spawned[k]

    def load_aircraft_persistence_state_from_cloud(self) -> None:
        """Überschreibt MSFS-Tankstand + Parkstand aus Cloud vor Triebwerksstart."""
        if self._aq is None:
            return
        title = self._last_title or ""
        owned, matched_model, _c = match_owned_for_title(DB_PATH, title)
        if not owned or not matched_model:
            return
        if matched_model in self._aircraft_persist_applied_models:
            return
        st = ionos_fetch_aircraft_persist_state(DB_PATH, matched_model)
        if not st:
            return
        fuel_gal = float(st.get("fuel_gallons", 0) or 0)
        gate_icao = str(st.get("gate_icao", "") or "").strip().upper()[:4]
        gate_label = str(st.get("gate_label", "") or "").strip()
        try:
            lat = float(st["lat"]) if st.get("lat") is not None else None
            lon = float(st["lon"]) if st.get("lon") is not None else None
        except (TypeError, ValueError):
            lat, lon = None, None
        if fuel_gal > 0.5:
            for var in ("FUEL TOTAL QUANTITY", "FUEL_TOTAL_QUANTITY"):
                try:
                    self._aq.set(var, fuel_gal)
                except Exception:
                    pass
        if gate_icao and len(gate_icao) == 4:
            if lat is not None and lon is not None:
                write_persisted_aircraft_stand(DB_PATH, gate_icao, lat, lon)
            else:
                app_meta_set(DB_PATH, META_STAND_ICAO, gate_icao)
            if gate_label:
                app_meta_set(DB_PATH, "stand_gate_label", gate_label[:64])
        self._aircraft_persist_applied_models.add(matched_model)
        self._append_log(
            self._tr(
                "msfs.persist_loaded_log",
                "Cloud-Persistenz: {gal:.0f} US gal, Gate {gate} injiziert.",
            ).format(gal=fuel_gal, gate=gate_label or gate_icao or "—")
        )

    def _save_aircraft_persistence_after_landing(
        self, title: str, matched_model: str | None
    ) -> None:
        if not matched_model or self._aq is None:
            return
        fuel_gal = _as_float(self._aq.get("FUEL_TOTAL_QUANTITY"))
        if fuel_gal is None:
            fuel_gal = _as_float(self._aq.get("FUEL TOTAL QUANTITY"))
        if fuel_gal is None:
            fuel_gal = 0.0
        gate_icao, gla, glo, _ts, _olv = read_persisted_aircraft_stand(DB_PATH)
        gate_label = (app_meta_get(DB_PATH, "stand_gate_label", "") or "").strip()
        if not gate_icao and self._last_plane_lat is not None and self._last_plane_lon is not None:
            gate_icao, _ = nearest_airport_nm(
                float(self._last_plane_lat), float(self._last_plane_lon)
            )
            gla = self._last_plane_lat
            glo = self._last_plane_lon
        ok = ionos_post_aircraft_save_state(
            DB_PATH,
            aircraft_model=matched_model,
            fuel_gallons=float(fuel_gal),
            gate_icao=gate_icao or "",
            gate_label=gate_label,
            lat=gla,
            lon=glo,
        )
        if ok:
            self._append_log(
                self._tr(
                    "msfs.persist_saved_log",
                    "Treibstoff ({gal:.0f} gal) und Gate an Cloud übertragen.",
                ).format(gal=float(fuel_gal))
            )

    def _broadcast_msfs_flight_planner_sync(self, job: dict) -> None:
        dep = str(job.get("dep", "") or "").upper()[:4]
        arr = str(job.get("arr", "") or "").upper()[:4]
        if not dep or not arr:
            return
        payload = {
            "action": "SYNC_FLIGHT_PLANNER",
            "dep": dep,
            "arr": arr,
            "weight_lbs": round(_job_payload_weight_lbs(job), 1),
        }
        if hasattr(self, "_msfs_ingame_ws"):
            self._msfs_ingame_ws.broadcast_json(payload)

    def _custom_airline_logo_local_path(self) -> Path:
        ASSETS_LOGOS_DIR.mkdir(parents=True, exist_ok=True)
        return ASSETS_LOGOS_DIR / CUSTOM_AIRLINE_LOGO_FILE

    def _fetch_custom_airline_logo_from_server(self) -> None:
        hw = p2p_hardware_id(DB_PATH)
        if not hw:
            return
        base = ionos_api_base_url().strip().rstrip("/")
        if not base:
            return
        url = f"{base}/api/v1/user/profile/download_logo/{quote(hw)}"
        req = QNetworkRequest(QUrl(url))
        rep = self._nam.get(req)
        rep.setProperty("kind", "custom_logo_download")

    def _apply_custom_airline_logo_pixmap(self, logo_path: Path) -> None:
        if not logo_path.is_file():
            return
        pixmap = QPixmap(str(logo_path.resolve()))
        if pixmap.isNull():
            return
        scaled = pixmap.scaled(
            120,
            120,
            Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
        if hasattr(self, "label_airline_logo_dash"):
            self.label_airline_logo_dash.setMinimumSize(120, 120)
            self.label_airline_logo_dash.setMaximumSize(120, 120)
            self.label_airline_logo_dash.setPixmap(scaled)
            self.label_airline_logo_dash.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self.label_airline_logo_dash.repaint()
        if self._tablet_efb is not None and hasattr(self._tablet_efb, "_logo_efb"):
            self._tablet_efb._logo_efb.setPixmap(
                pixmap.scaled(
                    150,
                    80,
                    Qt.AspectRatioMode.KeepAspectRatio,
                    Qt.TransformationMode.SmoothTransformation,
                )
            )

    def process_simconnect_touchdown_telemetry(
        self,
        touchdown_fpm: float | None,
        current_g_force: float,
        matched_model: str | None = None,
    ) -> None:
        """GPWS: harte Aufschläge (≤ −350 fpm) mit Alarm, Blackbox und Insolvenz-Prüfung."""
        if touchdown_fpm is None:
            return
        vs = float(touchdown_fpm)
        g_val = float(current_g_force or 0.0)
        print(
            f"[GPWS TELEMETRIE] Touchdown {vs:.0f} fpm | G-Kraft: {g_val:.2f}G"
        )
        if vs > GPWS_HARD_VS_FPM:
            rating = (
                self._tr("gpws.landing.butter", "Butterweich")
                if vs >= -150.0
                else self._tr("gpws.landing.solid", "Solide")
            )
            self.log_flight_to_blackbox(
                status=rating,
                detail=self._tr(
                    "gpws.landing.safe_detail",
                    "Sichere Landung mit {fpm:.0f} fpm.",
                ).format(fpm=vs),
            )
            return
        if self._gpws_crash_this_leg:
            return
        self._gpws_crash_this_leg = True
        print("[🚨 GPWS ALARM] BRUCHLANDUNG DETEKTIERT! STRUKTUR-SCHADEN IM HANGAR!")
        self._play_gpws_crash_sound()
        self._reduce_engine_health_after_crash(15.0, matched_model)
        self.log_flight_to_blackbox(
            status=self._tr("gpws.landing.crash", "Bruchlandung"),
            detail=self._tr(
                "gpws.landing.crash_detail",
                "Harter Aufschlag mit {fpm:.0f} fpm. Struktur-Inspektion im Hangar zwingend erforderlich!",
            ).format(fpm=vs),
        )
        self.check_airline_solvency_status()

    def _play_gpws_crash_sound(self) -> None:
        for fname in ("structural_crash.wav", "alarm.wav", "dingdong.wav"):
            wav = self._sound_path(fname)
            if wav.is_file():
                try:
                    self._audio.play_effect_file(wav)
                    return
                except Exception:
                    pass
        struct_alt = BASE_DIR / "assets" / "audio" / "structural_crash.wav"
        if struct_alt.is_file():
            try:
                self._audio.play_effect_file(struct_alt)
                return
            except Exception:
                pass
        if sys.platform == "win32":
            try:
                import winsound

                if struct_alt.is_file():
                    winsound.PlaySound(
                        str(struct_alt),
                        winsound.SND_FILENAME | winsound.SND_ASYNC,
                    )
                else:
                    winsound.MessageBeep(winsound.MB_ICONHAND)
            except Exception:
                pass

    def _reduce_engine_health_after_crash(
        self, reduction_percent: float, model: str | None = None
    ) -> None:
        m = (model or getattr(self, "_owned_model", "") or "").strip()
        if not m:
            return
        adjust_aircraft_part(DB_PATH, m, "ENGINES", -abs(float(reduction_percent)))

    def log_flight_to_blackbox(self, status: str, detail: str) -> None:
        note = f"{status}: {detail}"
        self._append_log(f"Blackbox — {note}")
        bbx = getattr(self, "_bbx_session", None)
        if isinstance(bbx, dict):
            bbx["landing_note"] = note

    def check_airline_solvency_status(self) -> None:
        if getattr(self, "_insolvency_mode", False):
            return
        credits = load_credits(DB_PATH)
        try:
            hq_tier = int(float(app_meta_get(DB_PATH, "hq_tier", "0") or "0"))
        except ValueError:
            hq_tier = 0
        loan_maxed = LoanManager.at_max_tier(DB_PATH)
        if credits > 0.0 or (hq_tier < 5 and not loan_maxed):
            return
        self._insolvency_mode = True
        print("[🏛️ INSOLVENZVERWALTER] BANKROTT! EINLEITUNG DES INSOLVENZMODUS!")
        if hasattr(self, "label_global_news_banner"):
            self.label_global_news_banner.setText(
                self._tr(
                    "insolvency.banner",
                    "🚨 INSOLVENZ: Deine Airline ist bankrott! Flugbetrieb gesperrt. "
                    "Bitte Allianz-Nothilfe beantragen.",
                )
            )
            self.label_global_news_banner.setStyleSheet(
                "background-color:#ff3333;color:#ffffff;font-weight:bold;"
                "padding:10px 14px;border-radius:8px;"
            )
            self.label_global_news_banner.show()
        self.trigger_allianz_insurance_asset_seizure()

    def trigger_allianz_insurance_asset_seizure(self) -> None:
        if not getattr(self, "_alliance_my_alliance_id", ""):
            self._append_log(
                self._tr(
                    "insolvency.no_alliance",
                    "Insolvenz: Keine Allianz — Nothilfe-Antrag nicht möglich.",
                )
            )
            return
        self._alliance_post(
            "/api/v1/alliance/insurance/claim",
            {
                "requested_credits": float(INSOLVENCY_RESCUE_CREDITS),
                "reason": self._tr(
                    "insolvency.claim_reason",
                    "Insolvenz-Abwendung nach schwerer Bruchlandung. "
                    "Flugzeug als Pfand hinterlegt.",
                ),
            },
            "alliance_insolvency_claim",
        )

    def lock_aircraft_for_insolvency_pledge(self) -> None:
        conn = _conn(DB_PATH)
        try:
            row = conn.execute(
                "SELECT model_name FROM owned_aircraft "
                "ORDER BY purchase_price ASC, model_name ASC LIMIT 1;"
            ).fetchone()
        finally:
            conn.close()
        if not row:
            return
        model = str(row[0])
        app_meta_set(DB_PATH, "insolvency_pledge_model", model)
        self._append_log(
            self._tr(
                "insolvency.pledge_locked",
                "Pfand: {model} bis zur Freigabe durch den Allianz-CEO gesperrt.",
            ).format(model=model)
        )

    def _request_blackbox_pull(self) -> None:
        if not self._ionos_cloud_ready():
            return
        if getattr(self, "_blackbox_pull_inflight", False):
            return
        self._blackbox_pull_inflight = True
        hid = p2p_hardware_id(DB_PATH)
        pw = (app_meta_get(DB_PATH, "cloud_backup_password", "") or "").strip()
        q = urlencode({"hardware_id": hid, "password": pw, "limit": "80"})
        base = ionos_api_base_url().strip().rstrip("/")
        req = QNetworkRequest(QUrl(f"{base}/api/v1/user/flightlog/pull?{q}"))
        rep = self._nam.get(req)
        rep.setProperty("kind", "blackbox_pull")

    def _request_flight_tracks_list(self) -> None:
        if not self._ionos_cloud_ready():
            return
        if getattr(self, "_flight_tracks_pull_inflight", False):
            return
        self._flight_tracks_pull_inflight = True
        hid = p2p_hardware_id(DB_PATH)
        pw = cloud_password_get(DB_PATH)
        em = (app_meta_get(DB_PATH, "portal_email", "") or "").strip().lower()
        q = urlencode(
            {
                "hardware_id": hid,
                "password": pw,
                "portal_email": em,
                "limit": "50",
            }
        )
        base = ionos_api_base_url().strip().rstrip("/")
        req = QNetworkRequest(QUrl(f"{base}/api/v1/flight/tracks?{q}"))
        rep = self._nam.get(req)
        rep.setProperty("kind", "flight_tracks_list")

    def _fill_flight_tracks_table(self, tracks: list) -> None:
        if not hasattr(self, "table_flight_tracks"):
            return
        self.table_flight_tracks.setRowCount(0)
        for tr in tracks:
            if not isinstance(tr, dict):
                continue
            r = self.table_flight_tracks.rowCount()
            self.table_flight_tracks.insertRow(r)
            dep = str(tr.get("dep", "") or "")
            arr = str(tr.get("arr", "") or "")
            route = f"{dep} → {arr}" if dep or arr else "—"
            done = int(tr.get("completed", 0) or 0)
            status = (
                self._tr("flight.tracker.done", "Abgeschlossen")
                if done
                else self._tr("flight.tracker.active", "Aktiv")
            )
            self.table_flight_tracks.setItem(
                r, 0, QTableWidgetItem(str(tr.get("flight_id", ""))[:20])
            )
            self.table_flight_tracks.setItem(r, 1, QTableWidgetItem(route))
            self.table_flight_tracks.setItem(
                r, 2, QTableWidgetItem(str(tr.get("pilot_name", ""))[:40])
            )
            self.table_flight_tracks.setItem(
                r, 3, QTableWidgetItem(str(tr.get("point_count", 0)))
            )
            self.table_flight_tracks.setItem(r, 4, QTableWidgetItem(status))

    def _start_cloud_flight_track(self) -> None:
        aj = load_active_job(DB_PATH)
        dep = str(aj.get("dep", "") if aj else "")[:4]
        arr = str(aj.get("arr", "") if aj else "")[:4]
        self._flight_track_id = ""
        self._flight_track_points = []
        if not self._ionos_cloud_ready():
            self._flight_track_id = f"LOCAL-{uuid.uuid4().hex[:10].upper()}"
            return
        extra: dict[str, object] = {"dep": dep, "arr": arr}
        if self._last_plane_lat is not None and self._last_plane_lon is not None:
            extra["lat"] = float(self._last_plane_lat)
            extra["lon"] = float(self._last_plane_lon)
        self._alliance_post("/api/v1/flight/track/start", extra, "flight_track_start")

    def _maybe_upload_flight_track_point(self) -> None:
        fid = getattr(self, "_flight_track_id", "") or ""
        if not fid or fid.startswith("LOCAL-"):
            return
        if not self._ionos_cloud_ready():
            return
        now = time.time()
        if now - float(getattr(self, "_last_flight_track_upload_ts", 0) or 0) < 45.0:
            return
        la = self._last_plane_lat
        lo = self._last_plane_lon
        if la is None or lo is None:
            return
        self._last_flight_track_upload_ts = now
        alt_ft = 0.0
        if self._aq is not None:
            alt_ft = float(_as_float(self._aq.get("INDICATED ALTITUDE")) or 0.0)
        self._alliance_post(
            "/api/v1/flight/track/append",
            {
                "flight_id": fid,
                "lat": float(la),
                "lon": float(lo),
                "alt_ft": alt_ft,
            },
            "flight_track_append",
        )

    def _set_alliance_actions_busy(self, busy: bool) -> None:
        dash = getattr(self, "advanced_alliance_dashboard", None)
        if dash is not None and hasattr(dash, "set_actions_busy"):
            dash.set_actions_busy(busy)

    def _alliance_post(self, endpoint: str, extra: dict | None, kind: str) -> None:
        if not self._ionos_cloud_ready():
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr(
                    "alliance.cloud_required",
                    "Cloud-Passwort in den Einstellungen hinterlegen.",
                ),
            )
            return
        body = dict(self._ionos_cloud_body())
        aid = (
            str(getattr(self, "_alliance_my_alliance_id", "") or "").strip()
            or str(
                getattr(
                    getattr(self, "advanced_alliance_dashboard", None),
                    "alliance_id",
                    "",
                )
                or ""
            ).strip()
        )
        if aid:
            body["alliance_id"] = aid
        if extra:
            body.update(extra)
        base = ionos_api_base_url().strip().rstrip("/")
        if not base:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr("alliance.net_err", "Server nicht erreichbar."),
            )
            return
        path = endpoint if endpoint.startswith("/") else f"/{endpoint}"
        req = QNetworkRequest(QUrl(f"{base}{path}"))
        req.setHeader(
            QNetworkRequest.KnownHeaders.ContentTypeHeader, "application/json"
        )
        lang = getattr(self, "_ui_lang", "de") or "de"
        req.setRawHeader(b"Accept-Language", lang.encode("utf-8"))
        pw = str(body.get("password", "") or "").strip()
        if pw:
            req.setRawHeader(b"X-Cloud-Password", pw.encode("utf-8"))
        for hk, hv in ionos_auth_headers(DB_PATH).items():
            req.setRawHeader(hk.encode("utf-8"), str(hv).encode("utf-8"))
        self._set_alliance_actions_busy(True)
        rep = self._nam.post(req, QByteArray(json.dumps(body).encode("utf-8")))
        rep.setProperty("kind", kind)

    def _request_alliance_mega_state(self) -> None:
        if not self._ionos_cloud_ready():
            return
        if not getattr(self, "_alliance_my_alliance_id", ""):
            return
        if getattr(self, "_alliance_mega_inflight", False):
            return
        self._alliance_mega_inflight = True
        self._alliance_post(
            "/api/v1/alliance/mega/state",
            None,
            "alliance_mega_state",
        )

    def _is_alliance_hub_icao(self, icao: str) -> bool:
        code = (icao or "").strip().upper()[:4]
        if len(code) != 4:
            return False
        hubs = getattr(self, "active_alliance_hubs_list", None) or []
        return code in {str(h).upper()[:4] for h in hubs}

    def _request_alliance_applications_list(self) -> None:
        if not self._ionos_cloud_ready():
            return
        role = getattr(self, "_alliance_my_role", "")
        if role not in ("ceo", "co_leader"):
            return
        if getattr(self, "_alliance_apps_list_inflight", False):
            return
        self._alliance_apps_list_inflight = True
        self._alliance_post(
            "/api/v1/alliance/applications/list",
            None,
            "alliance_apps_list",
        )

