    def _alliance_role_label(self, role: str) -> str:
        key = f"alliance.role.{(role or 'member').lower()}"
        defaults = {
            "ceo": "CEO",
            "co_leader": "Co-Leader",
            "captain": "Kapitän",
            "trainee": "Trainee",
            "member": "Mitglied",
            "pending": "Anfrage",
        }
        return self._tr(key, defaults.get((role or "member").lower(), role))

    def _blackbox_landing_rating(self, vs_fpm: float | None, g_val: float | None) -> str:
        if vs_fpm is None:
            return self._tr("blackbox.rate.unknown", "—")
        vs = float(vs_fpm)
        if vs > -80:
            return self._tr("blackbox.rate.catastrophic", "Bruchlandung!")
        if vs > -200:
            return self._tr("blackbox.rate.hard", "Harte Landung")
        if vs > -350:
            return self._tr("blackbox.rate.ok", "Solide Landung")
        return self._tr("blackbox.rate.butter", "Butterweich!")

    def _apply_alliance_check_response(self, data: dict) -> None:
        if not isinstance(data, dict):
            return
        in_al = bool(data.get("in_alliance"))
        if in_al:
            try:
                app_meta_set(
                    DB_PATH,
                    "alliance_snapshot_json",
                    json.dumps(
                        {
                            "in_alliance": True,
                            "alliance_id": data.get("alliance_id"),
                            "alliance_name": data.get("alliance_name"),
                            "role": data.get("role"),
                            "alliance_credits": data.get("alliance_credits"),
                            "tax_pct": data.get("tax_pct"),
                            "route_leases": data.get("route_leases", []),
                            "alliance_hubs": data.get("alliance_hubs")
                            or data.get("hub_icaos")
                            or [],
                        },
                        ensure_ascii=False,
                    )[:8000],
                )
            except OSError:
                pass
        self._refresh_alliance_panel()
        self.alliance_stack.setCurrentIndex(1 if in_al else 0)
        if not in_al:
            self._alliance_my_alliance_id = ""
            self._alliance_my_role = ""
            try:
                app_meta_set(DB_PATH, "career_active_alliance_id", "")
                app_meta_set(DB_PATH, "career_active_alliance_name", "")
            except OSError:
                pass
            self._alliance_public_rows = list(data.get("public_alliances") or [])
            self._fill_alliance_join_table(self._alliance_public_rows)
            self._alliance_cloud_ok = True
            self.label_alliance_status.setText(
                self._tr(
                    "alliance.status_none",
                    "Keine Allianz — gründen oder beitreten.",
                )
            )
            self._refresh_career_hub_header()
            return
        name = str(data.get("alliance_name", "") or "")
        pool = float(data.get("alliance_credits", 0) or 0)
        role = str(data.get("role", "") or "")
        self._alliance_my_role = role
        self._alliance_my_alliance_id = str(data.get("alliance_id", "") or "")
        try:
            app_meta_set(
                DB_PATH,
                "career_active_alliance_id",
                self._alliance_my_alliance_id[:128],
            )
            if name:
                app_meta_set(DB_PATH, "career_active_alliance_name", name[:80])
        except OSError:
            pass
        self.active_alliance_hubs_list = list(
            data.get("alliance_hubs") or data.get("hub_icaos") or []
        )
        self._refresh_career_hub_header()
        if hasattr(self, "advanced_alliance_dashboard"):
            self.advanced_alliance_dashboard.set_alliance_context(
                self._alliance_my_alliance_id, role
            )
        ceo = str(data.get("ceo_name", "") or "—")
        tax_pct = int(float(data.get("tax_pct", 0) or 0))
        self.label_alliance_title.setText(
            self._tr("alliance.title_fmt", "Allianz: {name}").format(name=name)
        )
        bank_txt = self._tr("alliance.bank_fmt", "Kasse: {cr} Credits").format(
            cr=format_eur_de(pool)
        )
        self.label_alliance_bank.setText(bank_txt)
        if hasattr(self, "label_alliance_treasury_kasse"):
            self.label_alliance_treasury_kasse.setText(bank_txt)
        self.label_alliance_ceo.setText(
            self._tr("alliance.ceo_fmt", "CEO: {ceo} · Ihre Rolle: {role}").format(
                ceo=ceo, role=self._alliance_role_label(role)
            )
        )
        self.spin_alliance_tax.blockSignals(True)
        self.spin_alliance_tax.setValue(tax_pct)
        self.spin_alliance_tax.blockSignals(False)
        can_hr = role in ("ceo", "co_leader")
        self.btn_alliance_promote.setEnabled(can_hr)
        self.btn_alliance_demote.setEnabled(can_hr)
        self.btn_alliance_kick.setEnabled(can_hr)
        self.btn_alliance_set_tax.setEnabled(role in ("ceo", "co_leader"))
        if hasattr(self, "btn_alliance_app_accept"):
            self.btn_alliance_app_accept.setEnabled(can_hr)
            self.btn_alliance_app_reject.setEnabled(can_hr)
        if can_hr and hasattr(self, "alliance_inner_tabs"):
            if self.alliance_inner_tabs.currentIndex() == getattr(
                self, "_alliance_ix_hr", 1
            ):
                self._request_alliance_applications_list()
        members = data.get("members") or []
        self.table_alliance_members.setRowCount(0)
        for m in members:
            if not isinstance(m, dict):
                continue
            r = self.table_alliance_members.rowCount()
            self.table_alliance_members.insertRow(r)
            mrole = str(m.get("role", ""))
            self.table_alliance_members.setItem(
                r, 0, QTableWidgetItem(self._alliance_role_label(mrole))
            )
            self.table_alliance_members.setItem(
                r,
                1,
                QTableWidgetItem(str(m.get("pilot_name", m.get("hardware_id", "")))),
            )
            self.table_alliance_members.setItem(
                r, 2, QTableWidgetItem(str(m.get("airline", "—")))
            )
            self.table_alliance_members.setItem(
                r,
                3,
                QTableWidgetItem(format_eur_de(float(m.get("contributed_credits", 0)))),
            )
            online = self._tr("alliance.online.yes", "Online") if m.get("online") else self._tr(
                "alliance.online.no", "Offline"
            )
            self.table_alliance_members.setItem(r, 4, QTableWidgetItem(online))
            self.table_alliance_members.item(r, 1).setData(
                Qt.ItemDataRole.UserRole, str(m.get("hardware_id", ""))
            )
        leases = data.get("route_leases") or []
        self.table_alliance_leases.setRowCount(0)
        for le in leases:
            if not isinstance(le, dict):
                continue
            r = self.table_alliance_leases.rowCount()
            self.table_alliance_leases.insertRow(r)
            self.table_alliance_leases.setItem(
                r, 0, QTableWidgetItem(str(le.get("icao", "")))
            )
            self.table_alliance_leases.setItem(
                r, 1, QTableWidgetItem(str(le.get("lessee_hardware_id", ""))[:14])
            )
            self.table_alliance_leases.setItem(
                r,
                2,
                QTableWidgetItem(format_eur_de(float(le.get("credits", 0)))),
            )
        self._alliance_cloud_ok = True
        self.label_alliance_status.setText(
            self._tr("alliance.status_ok", "Cloud-Allianz synchronisiert.")
        )
        self._request_alliance_mega_state()

    def _fill_alliance_join_table(self, rows: list[dict]) -> None:
        self.table_alliances_join.setRowCount(0)
        for a in rows:
            if not isinstance(a, dict):
                continue
            r = self.table_alliances_join.rowCount()
            self.table_alliances_join.insertRow(r)
            self.table_alliances_join.setItem(
                r, 0, QTableWidgetItem(str(a.get("name", "")))
            )
            self.table_alliances_join.setItem(
                r, 1, QTableWidgetItem(str(int(a.get("members", 0))))
            )
            self.table_alliances_join.setItem(
                r,
                2,
                QTableWidgetItem(format_eur_de(float(a.get("credits", 0)))),
            )
            self.table_alliances_join.item(r, 0).setData(
                Qt.ItemDataRole.UserRole, str(a.get("alliance_id", ""))
            )

    def _filter_alliance_join_table(self, text: str) -> None:
        q = (text or "").strip().lower()
        if not q:
            self._fill_alliance_join_table(self._alliance_public_rows)
            return
        filt = [
            a
            for a in self._alliance_public_rows
            if q in str(a.get("name", "")).lower()
        ]
        self._fill_alliance_join_table(filt)

    def _selected_alliance_join_id(self) -> str:
        row = self.table_alliances_join.currentRow()
        if row < 0:
            return ""
        it = self.table_alliances_join.item(row, 0)
        if it is None:
            return ""
        return str(it.data(Qt.ItemDataRole.UserRole) or "")

    def _selected_alliance_member_hid(self) -> str:
        row = self.table_alliance_members.currentRow()
        if row < 0:
            return ""
        it = self.table_alliance_members.item(row, 1)
        if it is None:
            return ""
        return str(it.data(Qt.ItemDataRole.UserRole) or "")

    def _on_alliance_create_clicked(self) -> None:
        name = self.input_create_alliance_name.text().strip()
        if len(name) < 3:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr("alliance.err_bad_name", "Name zu kurz (min. 3 Zeichen)."),
            )
            return
        self._alliance_post(
            "/api/v1/user/alliance/create",
            {"name": name},
            "alliance_create",
        )

    def _on_alliance_join_clicked(self) -> None:
        aid = self._selected_alliance_join_id()
        if not aid:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr("alliance.err_pick_row", "Bitte eine Allianz auswählen."),
            )
            return
        self._alliance_post(
            "/api/v1/user/alliance/join",
            {"alliance_id": aid},
            "alliance_join",
        )

    def _on_alliance_donate_clicked(self) -> None:
        try:
            amount = float(self.input_alliance_donate.text().replace(",", "."))
        except ValueError:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr("alliance.err_bad_amount", "Ungültiger Betrag."),
            )
            return
        if amount < 1.0:
            return
        self._alliance_post(
            "/api/v1/user/alliance/donate",
            {"amount": amount},
            "alliance_donate",
        )

    def _on_alliance_set_tax_clicked(self) -> None:
        self._alliance_post(
            "/api/v1/user/alliance/set_tax",
            {"tax_pct": int(self.spin_alliance_tax.value())},
            "alliance_set_tax",
        )

    def _on_alliance_member_action(self, action: str) -> None:
        target = self._selected_alliance_member_hid()
        if not target:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr("alliance.err_pick_member", "Bitte ein Mitglied auswählen."),
            )
            return
        self._alliance_post(
            "/api/v1/user/alliance/member_action",
            {"action": action, "hardware_id": target},
            "alliance_member_action",
        )

    def _alliance_go_mega_sub(self, sub_ix: int) -> None:
        mega_ix = int(getattr(self, "_alliance_ix_mega", -1))
        if mega_ix < 0 or not hasattr(self, "alliance_inner_tabs"):
            return
        self.alliance_inner_tabs.setCurrentIndex(mega_ix)
        dash = getattr(self, "advanced_alliance_dashboard", None)
        if dash is not None and hasattr(dash, "sub_tabs"):
            sub_ix = max(0, min(sub_ix, dash.sub_tabs.count() - 1))
            dash.sub_tabs.setCurrentIndex(sub_ix)
        self._request_alliance_mega_state()

    def _on_alliance_inner_tab_changed(self, index: int) -> None:
        if index == getattr(self, "_alliance_ix_hr", 1):
            self._request_alliance_applications_list()
        if index == getattr(self, "_alliance_ix_mega", -1):
            self._request_alliance_mega_state()

    def _fill_alliance_applications_table(self, apps: list) -> None:
        if not hasattr(self, "table_alliance_applications"):
            return
        self.table_alliance_applications.setRowCount(0)
        pending_lbl = self._tr("alliance.role.pending", "Anfrage")
        for a in apps:
            if not isinstance(a, dict):
                continue
            r = self.table_alliance_applications.rowCount()
            self.table_alliance_applications.insertRow(r)
            pname = str(a.get("pilot_name", a.get("hardware_id", "")))
            hid = str(a.get("hardware_id", ""))
            app_id = int(a.get("id", 0) or 0)
            self.table_alliance_applications.setItem(r, 0, QTableWidgetItem(pname))
            self.table_alliance_applications.setItem(r, 1, QTableWidgetItem(hid[:20]))
            self.table_alliance_applications.setItem(
                r, 2, QTableWidgetItem(pending_lbl)
            )
            meta = {"id": app_id, "hardware_id": hid}
            self.table_alliance_applications.item(r, 0).setData(
                Qt.ItemDataRole.UserRole, meta
            )

    def _selected_alliance_application(self) -> dict | None:
        row = self.table_alliance_applications.currentRow()
        if row < 0:
            return None
        it = self.table_alliance_applications.item(row, 0)
        if it is None:
            return None
        meta = it.data(Qt.ItemDataRole.UserRole)
        return meta if isinstance(meta, dict) else None

    def _on_alliance_application_accept(self) -> None:
        sel = self._selected_alliance_application()
        if not sel:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr(
                    "alliance.err_pick_application",
                    "Bitte eine Web-Bewerbung auswählen.",
                ),
            )
            return
        extra: dict[str, object] = {}
        if sel.get("id"):
            extra["application_id"] = int(sel["id"])
        if sel.get("hardware_id"):
            extra["hardware_id"] = str(sel["hardware_id"])
        self._alliance_post(
            "/api/v1/alliance/applications/accept",
            extra,
            "alliance_app_accept",
        )

    def _on_alliance_application_reject(self) -> None:
        sel = self._selected_alliance_application()
        if not sel:
            QMessageBox.warning(
                self,
                self._tr("alliance.msg_title", "Airline-Allianzen"),
                self._tr(
                    "alliance.err_pick_application",
                    "Bitte eine Web-Bewerbung auswählen.",
                ),
            )
            return
        extra: dict[str, object] = {}
        if sel.get("id"):
            extra["application_id"] = int(sel["id"])
        if sel.get("hardware_id"):
            extra["hardware_id"] = str(sel["hardware_id"])
        self._alliance_post(
            "/api/v1/alliance/applications/reject",
            extra,
            "alliance_app_reject",
        )

