        if self.radio_ins_kasko.isChecked():
            app_meta_set(DB_PATH, "active_insurance_policy", INSURANCE_POLICY_KASKO)
            app_meta_set(DB_PATH, "insurance_kasko_last_charge_ts", str(time.time()))
        elif self.radio_ins_liability.isChecked():
            app_meta_set(DB_PATH, "active_insurance_policy", INSURANCE_POLICY_LIABILITY)
