    def _on_bank_sonder_clicked(self) -> None:
        ok, key = LoanManager.try_sonder_tilgung(DB_PATH)
        title = self._tr("bank.msg_title", "Bank & Finanzen")
        if ok:
            QMessageBox.information(self, title, self._tr(key, key))
