    def _maybe_security_tick(self) -> None:
        if not validate_economy_integrity(DB_PATH):
            self._acs_report_integrity_failure()

    def trigger_security_flash(self) -> None:
        self._acs_flash_backup = self.styleSheet()
        self.setStyleSheet("QMainWindow { background-color: #440000; }")
        QTimer.singleShot(1100, self._acs_restore_main_stylesheet)

    def _acs_restore_main_stylesheet(self) -> None:
        self.setStyleSheet(getattr(self, "_acs_flash_backup", ""))

    def _acs_report_integrity_failure(self) -> None:
        raw = app_meta_get(DB_PATH, "acs_strike_count", "0")
        try:
            strikes = int(float(raw))
        except ValueError:
            strikes = 0
        strikes += 1
        app_meta_set(DB_PATH, "acs_strike_count", str(strikes))
        if strikes >= 2:
            self._acs_apply_strike_two()
            return
        self.trigger_security_flash()
        QMessageBox.critical(
            self,
            self._tr("security.title", "SkyTycoon Pro · Sicherheit"),
            self._tr(
                "security.warning_1",
                "SYSTEM-INTEGRITÄT VERLETZT: Manipulationsversuch erkannt. "
                "Dies ist Ihre letzte Warnung!",
            ),
        )
        try:
            economy_sync_shadow(DB_PATH)
        except Exception:
            pass

    def _acs_apply_strike_two(self) -> None:
        app_meta_set(DB_PATH, "cheater_detected", "1")
        app_meta_set(DB_PATH, "pilot_profile_banned", "1")
        app_meta_set(DB_PATH, "pilot_ban_reason", "ACS_STRIKE_2")
        app_meta_set(DB_PATH, "pilot_ban_at_unix", str(time.time()))
        ban_name = pilot_handle(DB_PATH)[:200]
        app_meta_set(DB_PATH, "pilot_banned_name_snapshot", ban_name)
        cr = load_credits(DB_PATH)
        add_credits(DB_PATH, -cr * 0.5)
        pilot_rank_down_n_levels(DB_PATH, 2)
        self.trigger_security_flash()
        QMessageBox.critical(
            self,
            self._tr("security.title", "SkyTycoon Pro · Sicherheit"),
            self._tr(
                "security.penalty_msg",
                "Zweiter Verstoß: 50 % Credits abgezogen, Rang um zwei Stufen reduziert. "
                "Profil wurde markiert (lokal; optional Cloud-Hall of Shame).",
            ),
        )
        self._acs_post_cheater_cloud()
        try:
            self._append_log(
                self._tr(
                    "security.ban_log",
                    "Anti-Cheat: Profil dauerhaft als BANNED markiert (Strike 2). "
                    "Cloud-Hall of Shame nur bei gesetzter MSFS_SKYTYCOON_LEADERBOARD_URL.",
                )
            )
        except Exception:
            pass
        try:
            economy_sync_shadow(DB_PATH)
        except Exception:
            pass
        self._refresh_credits_label()
        if hasattr(self, "_refresh_profile_tab"):
            self._refresh_profile_tab()

    def _acs_post_cheater_cloud(self) -> None:
        url = (os.environ.get("MSFS_SKYTYCOON_LEADERBOARD_URL", "") or "").strip()
        nam = getattr(self, "_nam", None)
        if not url or nam is None:
            return
        handle = pilot_handle(DB_PATH)
        js = json.dumps(
            {
                "pilot": handle,
                "status": "BANNED/CHEATER",
                "hardware_id": p2p_hardware_id(DB_PATH),
            },
            ensure_ascii=False,
        ).encode("utf-8")
        req = QNetworkRequest(QUrl(url))
        req.setHeader(
            QNetworkRequest.KnownHeaders.ContentTypeHeader,
            "application/json; charset=utf-8",
        )
        nam.post(req, QByteArray(js))

