    def _on_p2p_buy_clicked(self) -> None:
        L = self._current_p2p_listing()
        if not L:
            QMessageBox.warning(
                self,
                self._tr("market.p2p_title", "Gebrauchtbörse"),
                self._tr("market.p2p_select_row", "Bitte eine Zeile auswählen."),
            )
            return
        buyer = pilot_handle(DB_PATH)
        if str(L.get("seller_id")) == buyer:
            QMessageBox.information(
                self,
                self._tr("market.p2p_title", "Gebrauchtbörse"),
                self._tr("market.p2p_no_self_buy", "Eigenes Inserat kann nicht gekauft werden."),
            )
            return
        lid = str(L.get("id", ""))
        ok, err = p2p_reserve_listing(DB_PATH, lid, buyer)
        if not ok:
            QMessageBox.warning(
                self, self._tr("market.p2p_title", "Gebrauchtbörse"), self._tr(err, err)
            )
            return
        ok2, err2 = p2p_complete_purchase(DB_PATH, lid, buyer)
        if ok2:
            QMessageBox.information(
                self,
                self._tr("market.p2p_title", "Gebrauchtbörse"),
                self._tr(err2, err2),
            )
            self._refresh_credits_label()
            self._refresh_p2p_table()
            self._refresh_p2p_publish_models()
            self._refresh_hangar_parts_ui()
            self._refresh_market_table()
            self._sync_ownership_ui(self._last_title)
        else:
            QMessageBox.warning(
                self,
                self._tr("market.p2p_title", "Gebrauchtbörse"),
                self._tr(err2, err2),
            )

    def _on_p2p_withdraw_clicked(self) -> None:
        title = self._tr("market.p2p_title", "Gebrauchtbörse")
