    def _job_distance_bucket(self) -> str:
        if not hasattr(self, "combo_job_dist_filter"):
            return JOB_DIST_ALL
        ix = min(2, max(0, self.combo_job_dist_filter.currentIndex()))
        return (JOB_DIST_ALL, JOB_DIST_SHORT, JOB_DIST_LONG)[ix]

