    def _evaluate_spawn_vs_persisted_stand(self, lat: float, lon: float) -> None:
        ic_saved, la_s, lo_s, _ts, _olv = read_persisted_aircraft_stand(DB_PATH)
        if not ic_saved:
            self._stand_spawn_warn_active = False
            return
        ic_now, _d0 = nearest_airport_nm(lat, lon)
        if ic_now == ic_saved:
            self._stand_spawn_warn_active = False
            return
        if la_s is not None and lo_s is not None:
            nm = haversine_nm(float(la_s), float(lo_s), lat, lon)
            if nm <= SPAWN_MISMATCH_MAX_NM:
                self._stand_spawn_warn_active = False
                return
        self._stand_spawn_warn_active = True

    def _refresh_career_status_dashboard(self) -> None:
        if not hasattr(self, "label_career_status_title"):
            return
        sim_ok = self._sm is not None and self._aq is not None
        if not sim_ok:
            ic, _la, _lo, _ts, _olv = read_persisted_aircraft_stand(DB_PATH)
            icao_txt = ic or "–"
            loc_lbl = airport_route_label(ic) if ic else "–"
            self.label_career_status_title.setText(
                self._tr("career.dash.msfs_closed", "MSFS GESCHLOSSEN")
            )
            self.label_career_status_detail.setText(
                self._tr(
                    "career.dash.parked_full",
                    "STATUS: Geparkt in {loc}.\n{msg}",
                ).format(
                    loc=loc_lbl,
                    msg=self._tr(
                        "career.dash.parked_safe",
                        "Flugzeug sicher geparkt in {icao}.",
                    ).format(icao=icao_txt),
                )
            )
            return
        og = self._last_poll_on_ground
        eng = self._last_poll_eng1
        if og is None:
            self.label_career_status_title.setText(
                self._tr("career.dash.sim_connected", "SIMULATOR VERBUNDEN")
            )
            self.label_career_status_detail.setText(
                self._tr(
                    "career.dash.wait_telemetry",
                    "Warte auf erste Telemetrie …",
                )
            )
            return
        active = (not og) or eng
        if active:
            self.label_career_status_title.setText(
                self._tr("career.dash.active_flight", "ACTIVE FLIGHT")
            )
            self.label_career_status_detail.setText(
                self._tr(
                    "career.dash.active_detail",
                    "Triebwerk(e) an oder in der Luft – Karriere-Events aktiv.",
                )
            )
        else:
            self.label_career_status_title.setText(
                self._tr("career.dash.parking", "PARKING / STANDBY")
            )
            ic, _la, _lo, _ts, _olv = read_persisted_aircraft_stand(DB_PATH)
            loc = airport_route_label(ic) if ic else "–"
            self.label_career_status_detail.setText(
                self._tr(
                    "career.dash.parking_detail",
                    "Am Boden, Triebwerke AUS · letzter Standort {icao}.",
                ).format(icao=loc)
            )
        if self._stand_spawn_warn_active:
            ic_saved, _, _, _ts2, _olv2 = read_persisted_aircraft_stand(DB_PATH)
            warn = self._tr(
                "career.dash.spawn_warn",
                "Standort-Fehler! Dein Flugzeug steht noch in {icao}. "
                "Bitte positioniere dich dort, um die Karriere fortzusetzen.",
            ).format(icao=airport_route_label(ic_saved) if ic_saved else "?")
            self.label_career_status_detail.setText(
                self.label_career_status_detail.text() + "\n\n" + warn
            )
        if hasattr(self, "update_airline_branding"):
            self.update_airline_branding()

    def _refresh_ceo_report_panel(self) -> None:
        """Status-Bericht (Global infrastructure) unter PARKING/STANDBY."""
        if hasattr(self, "frame_ceo_report"):
            self.frame_ceo_report.show()
            self.frame_ceo_report.setMaximumHeight(16_777_215)
        if hasattr(self, "frame_career_profile_strip"):
            self.frame_career_profile_strip.hide()
            self.frame_career_profile_strip.setMaximumHeight(0)
        if not hasattr(self, "lbl_ceo_greeting"):
            return
        db_path = DB_PATH
        branch_rows = fetch_airline_branches_realty_rows(db_path)
        n_br = len(branch_rows)
        self.lbl_ceo_infra_title.setText(
            self._tr("dash.infra", "Global infrastructure")
        )
        summary_html = self._tr(
            "dash.operate",
            'You currently operate <span style="color:#8ac7ff;font-weight:700">{n}</span> '
            "active branches worldwide.",
        ).format(n=n_br)
        self.lbl_ceo_infra_sum.setText(summary_html)
        tier_keys = {
            1: "morning.office_tier_1",
            2: "morning.office_tier_2",
            3: "morning.office_tier_3",
            4: "morning.office_tier_4",
            5: "morning.office_tier_5",
        }
        top4 = sorted(
            branch_rows,
            key=lambda r: (-int(r.get("level") or 1), -float(r.get("invested") or 0.0)),
        )[:4]
        lines: list[str] = []
        for r in top4:
            icao = str(r.get("icao") or "").strip().upper()[:4]
            lv = max(1, min(5, int(r.get("level") or 1)))
            tkey = tier_keys.get(lv, "morning.office_tier_1")
            tier = self._tr(tkey, "Stufe {lv}").format(lv=lv)
            ap_lab = airport_route_label(icao) if icao else "—"
            lines.append(
                self._tr(
                    "morning.branch_line_fmt",
                    "{ap} — {tier}",
                ).format(ap=ap_lab, tier=tier)
            )
        empty_txt = self._tr("morning.branch_list_empty", "—")
        pilot = (
            app_meta_get(db_path, "pilot_display_name", "").strip()
            or app_meta_get(db_path, "pilot_name", "").strip()
            or "Pilot"
        )
        airline = (app_meta_get(db_path, "selected_airline_name", "").strip() or "Airline")
        ui = (app_meta_get(db_path, "ui_lang", "de") or "de").strip().lower()
        if ui.startswith("en"):
            self.lbl_ceo_greeting.setText(
                f"Good morning, Cpt. {pilot}. Status report for {airline}:"
            )
        else:
            self.lbl_ceo_greeting.setText(
                self._tr(
                    "morning.greeting",
                    "Guten Morgen, Cpt. {pilot}. Status-Bericht für {airline}:",
                ).format(pilot=pilot, airline=airline)
            )
        models = list_owned_models(db_path)
        fly_n = 0
        crit_n = 0
        for m in models:
            info = get_aircraft_parts(db_path, m)
            parts = info.get("parts") or {}
            vals = [float(parts.get(c, 100.0)) for c in PART_CODES]
            if all(v >= 80.0 for v in vals):
                fly_n += 1
            if any(v < 45.0 for v in vals):
                crit_n += 1
        bal = format_eur_de(load_credits(db_path))
        loan_line = self._tr(
            "morning.finance_no_loan", "Kein aktiver Bank-Kredit."
        )
        if LoanManager.has_loan(db_path):
            daily = LoanManager.current_daily_payment(db_path)
            loan_line = self._tr(
                "morning.finance_loan",
                "Fällige Kreditrate (ca. nächste 24 h): {amt}",
            ).format(amt=format_eur_de(max(0.0, daily)))
        fleet_line = self._tr(
            "morning.fleet_fmt",
            "Flotte: {fly} flugfähig · {crit} mit kritischem Hangar-Status.",
        ).format(fly=fly_n, crit=crit_n)
        fin_line = self._tr(
            "dash.finance",
            "Finance balance: {bal}. {loan}",
        ).format(bal=bal, loan=loan_line)
        if lines:
            lines.extend([fleet_line, fin_line])
        else:
            lines = [fleet_line, fin_line]
        self.lbl_ceo_infra_list.setText("\n".join(lines))
        self.lbl_ceo_body.clear()
        self.lbl_ceo_body.hide()

