    def _on_job_auto_refresh_tick(self) -> None:
        if not self._is_main_hub_active("_hub_ix_dispatch"):
            return
        if hasattr(self, "job_board_tabs") and self.job_board_tabs.currentIndex() == 3:
            return
        if self.table_jobs.rowCount() >= 50:
            return
        self._request_cloud_jobs_global_fallback()
