    def _on_spare_part_buy_clicked(
        self, part_id: str, name: str, wear_pct: float, price: float
    ) -> None:
        cr = load_credits(DB_PATH)
        if cr < price:
            QMessageBox.warning(
                self,
                self._tr("hangar.parts_market_title", "Ersatzteil-Markt"),
                self._tr("hangar.low_credits", "Zu wenig Credits."),
            )
            return
        conn = _conn(DB_PATH)
        try:
            conn.execute(
                "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
                (float(price),),
            )
            conn.commit()
        finally:
            conn.close()
        try:
            economy_sync_shadow(DB_PATH)
        except Exception:
            pass
        raw = (app_meta_get(DB_PATH, "spare_parts_inventory_json", "") or "").strip()
        try:
            inv = json.loads(raw) if raw else []
        except json.JSONDecodeError:
            inv = []
        if not isinstance(inv, list):
            inv = []
        inv.append(
            {
                "id": part_id,
                "name": name,
                "wear_pct": round(float(wear_pct), 1),
                "purchased_ts": time.time(),
            }
        )
        app_meta_set(
            DB_PATH,
            "spare_parts_inventory_json",
            json.dumps(inv[-120:], ensure_ascii=False),
        )
        self._refresh_credits_label()
        QMessageBox.information(
            self,
            self._tr("hangar.parts_market_title", "Ersatzteil-Markt"),
            self._tr(
                "hangar.parts_bought",
                "„{name}“ gekauft (Verschleiß {wear:.1f} %) — Lagerbestand aktualisiert.",
            ).format(name=name, wear=wear_pct),
        )
        if QMessageBox.question(
            self,
            self._tr("hangar.install_title", "Montieren"),
            self._tr(
                "hangar.install_question",
                "„{name}“ jetzt im aktiven MSFS-Cockpit montieren und auf 100 % setzen?",
            ).format(name=name),
        ) == QMessageBox.StandardButton.Yes:
            self._install_spare_part_live_to_msfs(name)

    def _install_spare_part_live_to_msfs(self, part_name: str) -> None:
        combo_model = self.combo_aircraft.currentText() if hasattr(self, "combo_aircraft") else ""
        model = str(getattr(self, "_owned_model", "") or getattr(self, "_last_title", "") or combo_model).strip()
        if not model:
            model = self._tr("hangar.current_aircraft", "Aktives Flugzeug")
        name_l = part_name.lower()
        if any(x in name_l for x in ("engine", "trieb", "turbine", "motor")):
            local_part = "engine"
            sim_vars = (
                ("GENERAL ENG DAMAGE PERCENT:1", 0.0),
                ("GENERAL ENG DAMAGE PERCENT:2", 0.0),
                ("ENG ON FIRE:1", 0.0),
                ("ENG ON FIRE:2", 0.0),
            )
        elif any(x in name_l for x in ("avion", "radio", "gps", "display")):
            local_part = "avionics"
            sim_vars = (("AVIONICS MASTER SWITCH", 1.0), ("ELECTRICAL MASTER BATTERY", 1.0))
        elif any(x in name_l for x in ("gear", "fahrwerk", "reifen", "tire", "brake")):
            local_part = "landing"
            sim_vars = (("GEAR HANDLE POSITION", 1.0),)
        else:
            local_part = "airframe"
            sim_vars = (("STRUCTURAL DEICE SWITCH", 0.0),)
        try:
            set_part_condition(DB_PATH, model, local_part, 100.0)
            if local_part == "airframe":
                conn = _conn(DB_PATH)
                try:
                    conn.execute(
                        "UPDATE owned_aircraft SET condition = 100.0 WHERE model_name = ?;",
                        (model,),
                    )
                    conn.commit()
                finally:
                    conn.close()
        except Exception as exc:
            self._append_log(f"Montage lokal fehlgeschlagen: {exc!s}")
        applied = 0
        aq = getattr(self, "_aq", None)
        if aq is not None:
            for var, value in sim_vars:
                try:
                    if aq.set(var, value):
                        applied += 1
                except Exception:
                    pass
        self._refresh_credits_label()
        self._append_log(
            f"Montage: {part_name} auf 100 % gesetzt; SimConnect-Signale: {applied}."
        )
        QMessageBox.information(
            self,
            self._tr("hangar.install_title", "Montieren"),
            self._tr(
                "hangar.install_done",
                "Montage abgeschlossen. Hangar-Status steht auf 100 %. SimConnect-Signale: {n}.",
            ).format(n=applied),
        )

    def append_transaction_to_local_ledger(
        self,
        category: str,
        description: str,
        gross_amount: float,
        tax_deducted: float = 0.0,
    ) -> None:
        """M189: Lokales Finanzbuchhaltungs-Register (Airline-Ledger)."""
        try:
            conn = sqlite3.connect(str(DB_PATH))
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS airline_ledger (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    category TEXT NOT NULL,
                    description TEXT NOT NULL,
                    amount REAL NOT NULL,
                    tax REAL NOT NULL DEFAULT 0
                );
                """
            )
            conn.execute(
                """
                INSERT INTO airline_ledger (timestamp, category, description, amount, tax)
                VALUES (?, ?, ?, ?, ?);
                """,
                (
                    datetime.now(timezone.utc).isoformat(),
                    str(category or "")[:64],
                    str(description or "")[:240],
                    float(gross_amount),
                    float(tax_deducted),
                ),
            )
            conn.commit()
            conn.close()
        except (sqlite3.Error, OSError, TypeError, ValueError):
            pass

    def _load_local_spare_parts_inventory(self) -> list[dict]:
        raw = (app_meta_get(DB_PATH, "spare_parts_inventory_json", "") or "").strip()
        try:
            inv = json.loads(raw) if raw else []
        except json.JSONDecodeError:
            inv = []
        if not isinstance(inv, list):
            return []
        return [x for x in inv if isinstance(x, dict)]

    def _save_local_spare_parts_inventory(self, inv: list[dict]) -> None:
        app_meta_set(
            DB_PATH,
            "spare_parts_inventory_json",
            json.dumps(inv[-120:], ensure_ascii=False),
        )

    def _on_sell_spare_part_world_market_clicked(self) -> None:
        """M188: Lokales Teil auf den globalen Cloud-Schrottplatz listen."""
        base, pw = ionos_cloud_credentials(DB_PATH)
        if not base or not pw:
            QMessageBox.warning(
                self,
                self._tr("hangar.sell_part_world", "Weltmarkt"),
                self._tr(
                    "profile.cloud_credentials_required",
                    "Bitte Cloud-Passwort hinterlegen.",
                ),
            )
            return
        inv = self._load_local_spare_parts_inventory()
        if not inv:
            QMessageBox.information(
                self,
                self._tr("hangar.sell_part_world", "Weltmarkt"),
                self._tr(
                    "hangar.sell_part_empty",
                    "Keine Ersatzteile im Lager — zuerst am Markt kaufen oder gewinnen.",
                ),
            )
            return
        labels: list[str] = []
        for i, row in enumerate(inv):
            nm = str(row.get("name", row.get("part_name", f"Teil {i + 1}")) or "")
            wear = float(row.get("wear_pct", row.get("condition", 70)) or 70)
            labels.append(f"{nm} ({wear:.0f} %)")
        pick, ok_pick = QInputDialog.getItem(
            self,
            self._tr("hangar.sell_part_world", "Weltmarkt"),
            self._tr("hangar.sell_part_pick", "Welches Teil möchten Sie listen?"),
            labels,
            0,
            False,
        )
        if not ok_pick or not pick:
            return
        idx = labels.index(pick)
        part_row = dict(inv[idx])
        price, ok_price = QInputDialog.getDouble(
            self,
            self._tr("hangar.sell_part_world", "Weltmarkt"),
            self._tr("hangar.sell_part_price", "Wunschpreis in Credits:"),
            25_000.0,
            500.0,
            5_000_000.0,
            0,
        )
        if not ok_price or price <= 0:
            return
        part_name = str(
            part_row.get("name", part_row.get("part_name", "Ersatzteil")) or "Ersatzteil"
        )[:160]
        wear = float(part_row.get("wear_pct", part_row.get("condition", 70)) or 70)
        ptype = str(part_row.get("category", part_row.get("part_type", "misc")) or "misc")[
            :48
        ]
        body = build_ionos_cloud_sync_body(DB_PATH)
        body.update(
            {
                "part_name": part_name,
                "part_type": "P2P_USER_PART",
                "condition": wear,
                "price": float(price),
                "price_credits": float(price),
                "seller_hardware_id": body.get("hardware_id", ""),
                "hardware_id": body.get("hardware_id", ""),
            }
        )
        try:
            r = requests.post(
                f"{base.rstrip('/')}/api/v1/scrapyard/list_user_part",
                json=body,
                timeout=18,
                headers=ionos_auth_headers(DB_PATH),
            )
            j = r.json()
        except (requests.RequestException, json.JSONDecodeError):
            QMessageBox.warning(
                self,
                self._tr("hangar.sell_part_world", "Weltmarkt"),
                self._tr("job.cloud_err", "Cloud-Server nicht erreichbar."),
            )
            return
        if isinstance(j, dict) and (j.get("ok") or j.get("status") == "success"):
            inv.pop(idx)
            self._save_local_spare_parts_inventory(inv)
            QMessageBox.information(
                self,
                self._tr("hangar.sell_part_world", "Weltmarkt"),
                str(
                    j.get(
                        "message",
                        self._tr(
                            "hangar.sell_part_ok",
                            "Teil gelistet — Erlös bei Verkauf auf Ihr Cloud-Konto.",
                        ),
                    )
                ),
            )
            if hasattr(self, "cloud_scrapyard_widget"):
                self.cloud_scrapyard_widget.refresh_scrapyard_list()
        else:
            QMessageBox.warning(
                self,
                self._tr("hangar.sell_part_world", "Weltmarkt"),
                str((j or {}).get("message", "Listing fehlgeschlagen.")),
            )

