    def _on_repair_part_clicked(self, model: str, part: str) -> None:
        info = get_aircraft_parts(DB_PATH, model)
        cond = float((info.get("parts") or {}).get(part, 100.0))
        blk = float((info.get("blocks") or {}).get(part, 0.0))
        if blk > time.time():
            QMessageBox.information(
                self,
                self._tr("hangar.msg_title", "Hangar"),
                self._tr(
                    "hangar.part_blocked",
                    "Bauteil ist noch in Wartung / gesperrt.",
                ),
            )
            return
        if cond >= 99.95:
            QMessageBox.information(
                self,
                self._tr("hangar.msg_title", "Hangar"),
                self._tr("hangar.part_already_ok", "Bauteil ist bereits in Top-Zustand."),
            )
            return
        base_cost = max(350.0, (100.0 - cond) * (180.0 if part == "ENGINES" else 95.0))
        used_cost = round(base_cost * 0.30, 0)
        junk_cost = round(base_cost * 0.25, 0) if part == "ENGINES" else 0.0
        rng = random.Random(
            (abs(hash(model)) % 1_000_003)
            ^ (abs(hash(part)) % 100_003)
            ^ (int(time.time()) % 86_400)
        )
        used_target = round(rng.uniform(45.0, 65.0), 1)

        dlg = QDialog(self)
        dlg.setWindowTitle(
            self._tr("hangar.repair_choice_title", "Reparatur: Original oder Gebrauchtteil")
        )
        dlg.resize(520, 320)
        lay = QVBoxLayout(dlg)
        lay.addWidget(
            QLabel(
                self._tr(
                    "hangar.repair_choice_intro",
                    "{model} · {part}\nAktuell: {cond:.1f} %",
                ).format(model=model, part=part, cond=cond)
            )
        )
        pick = {"m": "cancel"}

        def _oem() -> None:
            pick["m"] = "oem"
            dlg.accept()

        def _used() -> None:
            pick["m"] = "used"
            dlg.accept()

        def _junk() -> None:
            pick["m"] = "junk"
            dlg.accept()

        b_oem = QPushButton(
            self._tr(
                "hangar.repair_oem_btn",
                "💎 Original-Ersatzteil ({c}) → 100 %",
            ).format(c=format_eur_de(base_cost))
        )
        b_oem.clicked.connect(_oem)
        lay.addWidget(b_oem)
        b_used = QPushButton(
            self._tr(
                "hangar.repair_used_btn",
                "🔧 Gebrauchtteil ({c}) → ca. {p:.1f} % (doppelter Verschleiß)",
            ).format(c=format_eur_de(used_cost), p=used_target)
        )
        b_used.clicked.connect(_used)
        lay.addWidget(b_used)
        if part == "ENGINES" and cond <= 0.05:
            b_junk = QPushButton(
                self._tr(
                    "hangar.repair_junk_engine_btn",
                    "🔧 Generalüberholtes Schrottplatz-Triebwerk installieren ({c})",
                ).format(c=format_eur_de(junk_cost))
            )
            b_junk.clicked.connect(_junk)
            lay.addWidget(b_junk)
        b_cancel = QPushButton(self._tr("dialog.cancel", "Abbrechen"))
        b_cancel.clicked.connect(dlg.reject)
        lay.addWidget(b_cancel)
        dlg.exec()
        mode = str(pick["m"])
        if mode == "cancel":
            return
        cost = float(base_cost if mode == "oem" else used_cost if mode == "used" else junk_cost)
        pol = (
            app_meta_get(DB_PATH, "active_insurance_policy", INSURANCE_POLICY_LIABILITY)
            or ""
        ).strip()
        if pol == INSURANCE_POLICY_KASKO:
            cost = round(cost * 0.3, 1)
        stand_icao, _sla, _slo, _sts, _olv = read_persisted_aircraft_stand(DB_PATH)
        sli = str(stand_icao or "").strip().upper()[:4]
        if sli and airline_branch_office_level(DB_PATH, sli) >= 2:
            cost = round(cost * 0.9, 0)
        cr = load_credits(DB_PATH)
        if cr < cost:
            QMessageBox.warning(
                self,
                self._tr("hangar.msg_title", "Hangar"),
                self._tr("hangar.low_credits", "Zu wenig Credits."),
            )
            return
        conn = _conn(DB_PATH)
        try:
            conn.execute(
                "UPDATE pilot_stats SET credits = credits - ? WHERE id = 1;",
                (float(cost),),
            )
            conn.commit()
        finally:
            conn.close()
        try:
            economy_sync_shadow(DB_PATH)
        except Exception:
            pass
        if mode == "oem":
            set_part_condition(DB_PATH, model, part, 100.0)
            set_part_used_part_active(DB_PATH, model, part, False)
            if part == "ENGINES":
                set_part_black_market_engine(DB_PATH, model, part, False)
        elif mode == "used":
            set_part_condition(DB_PATH, model, part, float(used_target))
            set_part_used_part_active(DB_PATH, model, part, True)
            if part == "ENGINES":
                set_part_black_market_engine(DB_PATH, model, part, False)
        else:
            jt = round(rng.uniform(50.0, 70.0), 1)
            set_part_condition(DB_PATH, model, part, float(jt))
            set_part_used_part_active(DB_PATH, model, part, False)
            set_part_black_market_engine(DB_PATH, model, part, True)
        if part == "TIRES":
            self._tire_gear_fault_fired = False
        if part == "ENGINES":
            set_part_block_until(DB_PATH, model, part, time.time() + 7200.0)
        self._sync_preflight_checkbox_green(part)
        self._refresh_credits_label()
        self._refresh_hangar_parts_ui()
        if self._tablet_efb is not None:
            try:
                self._tablet_efb._tick()
            except Exception:
                pass
        self._append_log(
            self._tr(
                "hangar.repair_done_log",
                "Hangar: {part} an {model} repariert ({cost}).",
            ).format(part=part, model=model, cost=format_eur_de(cost))
        )

    def _build_cabin_snapshot_dict(self, job: dict | None) -> dict:
        if not job or str(job.get("typ")) != "PAX":
            return {"mode": "cargo", "caption": str(job.get("narrative", ""))[:200]}
        title_hint = str(job.get("req_model") or self._last_title or "A320")
        rows, cols, prof = CabinGenerator.profile_for_title(title_hint)
        pax = int(job.get("pax", 0) or 0)
        seats = rows * cols
        occupied_n = min(seats, max(0, int(pax * seats / 200))) if pax > 0 else 0
        rng = random.Random(abs(hash(str(job.get("id", "x")))) % (2**32))
        occ: set[int] = (
            set(rng.sample(range(seats), occupied_n)) if occupied_n else set()
        )
        grid: list[list[str]] = []
        for r in range(rows):
            rowv: list[str] = []
            for c in range(cols):
                i = r * cols + c
                rowv.append("X" if i in occ else "O")
            grid.append(rowv)
        return {
            "mode": "pax",
            "profile": prof,
            "pax": pax,
            "grid": grid,
            "caption": f"{pax} PAX · {prof}",
        }

    def _update_tech_log_label(self) -> None:
        if not hasattr(self, "label_tech_log"):
            return
        if not self._owned_model:
            self.label_tech_log.setText("Tech-Log: kein Hangar-Match.")
            return
        info = get_aircraft_parts(DB_PATH, self._owned_model)
        parts = info.get("parts") or {}
        bits = [f"{k}:{float(parts.get(k, 100.0)):.0f}%" for k in PART_CODES]
        ok = all(float(parts.get(k, 100.0)) >= 80.0 for k in PART_CODES)
        sym = "OK (>80 %)" if ok else "Wartung prüfen"
        self.label_tech_log.setText(
            f"Tech-Log ({self._owned_model}): {', '.join(bits)}  ·  {sym}"
        )

    def _apply_parts_touchdown_wear(self, model: str, vs_fpm: float | None, g_peak: float) -> None:
        tire = -0.6
        # Sinkrate negativ = Abstieg; „harte“ Landung bei ca. < -300 fpm
        if vs_fpm is not None and vs_fpm < -300.0:
            tire -= 2.8
        if vs_fpm is not None and vs_fpm < -500.0:
            tire -= 2.0
        if g_peak >= 2.2:
            tire -= 2.2
        adjust_aircraft_part(DB_PATH, model, "TIRES", tire)
        adjust_aircraft_part(DB_PATH, model, "BRAKES", -0.45)
        if (
            app_meta_get(DB_PATH, "realism_flex_toga", "0") == "1"
            and app_meta_get(DB_PATH, "leg_takeoff_thrust_profile", "flex") == "toga"
        ):
            adjust_aircraft_part(DB_PATH, model, "ENGINES", -0.55)
        elif random.random() < 0.08:
            adjust_aircraft_part(DB_PATH, model, "ENGINES", -0.15)

    def _merge_cargo_jobs_checked(self, jobs: list[dict]) -> dict | None:
        if not jobs:
            return None
        for j in jobs:
            if str(j.get("typ")) != "CARGO":
                QMessageBox.warning(self, self._tr("ui.auto.flug_b_rse_f6682b53", "Flug-Börse"), self._tr("ui.auto.multi_auswahl_ist_nur_im_fracht_reiter_f_r_cargo_ede6e463", "Multi-Auswahl ist nur im Fracht-Reiter für CARGO-Jobs vorgesehen."),
                )
                return None
        dep = str(jobs[0].get("dep", ""))
        arr = str(jobs[0].get("arr", ""))
        req = str(jobs[0].get("req_model", ""))
        for j in jobs[1:]:
            if (
                str(j.get("dep", "")) != dep
                or str(j.get("arr", "")) != arr
                or str(j.get("req_model", "")) != req
            ):
                QMessageBox.warning(self, self._tr("ui.auto.flug_b_rse_f6682b53", "Flug-Börse"), self._tr("ui.auto.kombination_nur_m_glich_bei_gleichem_dep_arr_un_b5b5be69", "Kombination nur möglich bei gleichem DEP, ARR und erforderlichem Modell."),
                )
                return None
        tcargo = sum(float(j.get("cargo_kg", 0) or 0.0) for j in jobs)
        cap = mtow_kg_for_model(req) * 0.38
        if tcargo > cap:
            QMessageBox.warning(self, self._tr("ui.auto.flug_b_rse_f6682b53", "Flug-Börse"), f"Gesamtfracht {tcargo:.0f} kg übersteigt die zulässige Summe (~{cap:.0f} kg, MTOW-Heuristik).",
            )
            return None
        merged = dict(jobs[0])
        merged["id"] = "MX-" + str(uuid.uuid4())[:10].upper()
        merged["cargo_kg"] = tcargo
        merged["reward"] = sum(float(j.get("reward", 0) or 0.0) for j in jobs)
        merged["reward_base"] = sum(
            float(j.get("reward_base", j.get("reward", 0)) or 0.0) for j in jobs
        )
        merged["narrative"] = " + ".join(
            str(j.get("narrative", ""))[:40] for j in jobs if j.get("narrative")
        )
        merged["merged_cargo_job_ids"] = [str(j.get("id", "")) for j in jobs]
        merged["smuggle_cargo"] = any(bool(j.get("smuggle_cargo")) for j in jobs)
        return merged

    def _ask_routing_provider_dialog(self) -> str | None:
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Icon.Question)
        box.setWindowTitle(
            self._tr("dispatch.choose_title", "Dispatch-System wählen")
        )
        box.setText(
            self._tr(
                "dispatch.choose_body",
                "🌐 Wähle dein Dispatch-System / Select Dispatch System",
            )
        )
        btn_sb = box.addButton(
            self._tr("dispatch.simbrief", "✈️ SimBrief (Standard)"),
            QMessageBox.ButtonRole.AcceptRole,
        )
        btn_st = box.addButton(
            self._tr(
                "dispatch.skytycoon",
                "🗺️ SkyTycoon Dispatch (+15% Credits & XP)",
            ),
            QMessageBox.ButtonRole.ActionRole,
        )
        box.addButton(QMessageBox.StandardButton.Cancel)
        box.exec()
        if box.clickedButton() == btn_st:
            return "sky_dispatch"
        if box.clickedButton() == btn_sb:
            return "simbrief"
        return None

    def _on_accept_job_clicked(self) -> None:
        rows_sel = sorted(
            {idx.row() for idx in self.table_jobs.selectionModel().selectedRows()},
            key=lambda x: x,
        )
        if self.job_board_tabs.currentIndex() == 1:
            if not rows_sel and self.table_jobs.currentRow() >= 0:
                rows_sel = [self.table_jobs.currentRow()]
        else:
            rows_sel = (
                [self.table_jobs.currentRow()]
                if self.table_jobs.currentRow() >= 0
                else []
            )
        if not rows_sel:
            QMessageBox.information(
                self,
                self._tr("job.board_title", "Flug-Börse"),
                self._tr(
                    "job.accept_select_rows",
                    "Bitte eine oder mehrere Zeilen auswählen.",
                ),
            )
            return
        jobs: list[dict] = []
        for r in rows_sel:
            it = self.table_jobs.item(r, 0)
            if it is None:
                continue
            raw = it.data(Qt.ItemDataRole.UserRole)
            if not raw:
                continue
            try:
                jobs.append(json.loads(str(raw)))
            except json.JSONDecodeError:
                QMessageBox.warning(self, self._tr("ui.msg.job_board", "Flug-Börse"), self._tr("ui.msg.invalid_row", "Ungültige Zeilendaten."))
                return
        if not jobs:
            return
        if len(jobs) > 1:
            if any(j.get("cloud_job") or j.get("server_job_id") for j in jobs):
                QMessageBox.warning(
                    self,
                    self._tr("job.board_title", "Flug-Börse"),
                    self._tr(
                        "job.cloud_single_only",
                        "Cloud-Aufträge können nur einzeln angenommen werden.",
                    ),
                )
                return
            job = self._merge_cargo_jobs_checked(jobs)
            if job is None:
                return
        else:
            job = jobs[0]
        models = set(list_owned_models(DB_PATH))
        req = str(job.get("req_model", ""))
        if req not in models:
            QMessageBox.warning(self, self._tr("ui.auto.flug_b_rse_f6682b53", "Flug-Börse"), f"Du besitzt „{req}“ nicht im Hangar."
            )
            return
        if not has_type_rating(DB_PATH, req):
            QMessageBox.warning(
                self,
                self._tr("job.board_title", "Flug-Börse"),
                self._tr(
                    "job.err_type_rating",
                    "Für „{req}“ fehlt das Type-Rating. Bitte im Tab „Pilot Profil“ unter "
                    "Type-Ratings (Prestige-XP) freischalten.",
                ).format(req=req),
            )
            return
        meta = get_pilot_meta(DB_PATH)
        lvl = rank_pilot_level(float(meta["xp"]))
        if lvl < int(job.get("min_level", 1)):
            QMessageBox.warning(self, self._tr("ui.auto.flug_b_rse_f6682b53", "Flug-Börse"), f"Dein Rang-Level ({lvl}) reicht nicht (benötigt {job.get('min_level')}).",
            )
            return
        dep_ok, dep_key = job_departure_hub_allowed(DB_PATH, str(job.get("dep", "")))
        if not dep_ok:
            QMessageBox.warning(
                self,
                self._tr("job.board_title", "Flug-Börse"),
                self._tr(
                    dep_key,
                    "Abflug nur von eigenen Hubs oder Allianz-geleasten Flughäfen "
                    "(Routen-Leasing im Web-Dashboard).",
                ),
            )
            return
        own, mm, _c = match_owned_for_title(DB_PATH, self._last_title)
        if not own or mm != req:
            QMessageBox.warning(self, self._tr("ui.auto.flug_b_rse_f6682b53", "Flug-Börse"), f"Im Simulator muss das passende Flugzeug geladen sein (erwartet: „{req}“).",
            )
            return
        sid = int(job.get("server_job_id") or 0)
        if sid > 0 or job.get("cloud_job"):
            if not self._ionos_cloud_ready():
                QMessageBox.warning(
                    self,
                    self._tr("job.board_title", "Flug-Börse"),
                    self._tr(
                        "job.cloud_auth_required",
                        "Für Cloud-Aufträge Cloud-Passwort unter Datei → Cloud-Passwort hinterlegen.",
                    ),
                )
                return
            self._pending_cloud_accept_job = dict(job)
            self._pending_cloud_accept_jobs_count = len(jobs)
            rp = self._ask_routing_provider_dialog()
            if rp is None:
                return
            self._alliance_post(
                "/api/v1/jobs/accept",
                {"job_id": sid, "routing_provider": rp},
                "cloud_jobs_accept",
            )
            return
        rp = self._ask_routing_provider_dialog()
        if rp is None:
            return
        job["routing_provider"] = rp
        job["use_sky_dispatch"] = 1 if rp == "sky_dispatch" else 0
        self._complete_job_acceptance(job, len(jobs))

    def _complete_job_acceptance(self, job: dict, jobs_count: int) -> None:
        raw_m, _err_m = fetch_metar_aviationweather(str(job.get("arr", "")))
        hard = False
        if raw_m:
            hard, _ = metar_hard_conditions(raw_m)
        job["dest_metar_hard"] = hard
        job["dest_metar_raw"] = raw_m or ""
        job["accepted_ts"] = time.time()
        job["payload_applied"] = False
        if jobs_count == 1 and str(job.get("typ")) == "PAX":
            job["manifest"] = generate_passenger_manifest(
                int(job.get("pax", 0) or 0),
                str(job.get("dep", "EDDF")),
                DB_PATH,
            )
        save_active_job(DB_PATH, job)
        accepted_jobs_upsert_row(
            DB_PATH,
            job,
            role="human",
            assigned_model=str(job.get("req_model", "") or ""),
            assigned_crew_id=(app_meta_get(DB_PATH, "dispatch_crew_id", "") or "").strip(),
        )
        if hasattr(self, "_refresh_active_dispatch_table"):
            self._refresh_active_dispatch_table()
        app_meta_set(DB_PATH, "forged_papers_active", "0")
        app_meta_set(DB_PATH, "vip_catering_leg_purchased", "0")
        app_meta_set(DB_PATH, "leg_fuel_purchased", "0")
        app_meta_set(DB_PATH, "leg_gsx_boarding_done", "0")
        app_meta_set(DB_PATH, "leg_gsx_realism_bonus_ok", "0")
        for pc in PART_CODES:
            app_meta_set(DB_PATH, f"preflight_maint_{pc}", "0")
        self._reload_active_job_from_db()
        self._tts_gsx_pushback_clear_done = False
        self._cabin_ready_spoken = False
        self._gsx_seat_fill_pct = 0.0
        self._gsx_seat_occ.clear()
        self._gsx_seat_order.clear()
        self._refresh_mission_and_metar_ui()
        if self.tab_widget is not None:
            self.tab_widget.setCurrentIndex(
                int(getattr(self, "_tab_ix_flight", 5))
            )
        self._append_log(
            self._tr(
                "job.accept_log",
                "Auftrag angenommen: {jid} {dep}→{arr}.",
            ).format(
                jid=job.get("id"),
                dep=job.get("dep"),
                arr=job.get("arr"),
            )
        )
        self._broadcast_msfs_flight_planner_sync(job)
        QMessageBox.information(
            self,
            self._tr("job.board_title", "Flug-Börse"),
            self._tr(
                "job.accept_done",
                "Auftrag übernommen – Details im Tab „Aktueller Flug“. Optional: "
                "„Flug jetzt starten (Payload ins MSFS)“ in der Flug-Börse.",
            ),
        )

    def _on_job_payload_to_sim(self) -> None:
        aj = self._active_job
        if not aj:
            QMessageBox.information(self, self._tr("ui.msg.loading", "Beladung"), self._tr("ui.msg.no_active_job", "Kein aktiver Auftrag."))
            return
        blk = self._blockers_text()
        if blk:
            QMessageBox.warning(self, self._tr("ui.msg.dispatch", "Dispatch"), blk)
            return
        if not self._preflight_complete():
            QMessageBox.warning(
                self,
                self._tr("hangar.preflight_block_title", "Pre-Flight Wartung"),
                self._tr(
                    "hangar.preflight_block_payload",
                    "Bitte zuerst alle Wartungs-Freigaben im Hangar oder auf dem EFB-Tablet setzen "
                    "(Reifen, Bremsen, Triebwerk/Flüssigkeiten) oder formal überspringen.",
                ),
            )
            return
        ok, msg = self._apply_job_payload_to_sim(aj)
        self.label_payload_status.setText(msg)
        if ok and aj:
            aj["payload_applied"] = True
            save_active_job(DB_PATH, aj)
            self._reload_active_job_from_db()

    def _apply_job_payload_to_sim(self, job: dict) -> tuple[bool, str]:
        if self._aq is None:
            return False, "SimConnect nicht verbunden."
        gal = float(app_meta_get(DB_PATH, "simbrief_plan_fuel_gal", "0") or "0")
        if gal >= 8.0 and app_meta_get(DB_PATH, "leg_fuel_purchased", "0") != "1":
            return (
                False,
                "Dispatch: SimBrief-Kraftstoff noch nicht gekauft (Karriere-Tab).",
            )
        try:
            nst_raw = self._aq.get("PAYLOAD STATION COUNT")
            nst = int(float(nst_raw)) if nst_raw is not None else 5
        except (TypeError, ValueError):
            nst = 5
        nst = max(2, min(12, nst))
        weights_lb: list[float] = [0.0] * nst
        if str(job.get("typ")) == "PAX":
            total_kg = float(job.get("pax", 0)) * 90.0
            share = (total_kg * 2.20462262) / float(nst)
            for i in range(nst):
                weights_lb[i] = max(0.0, share)
        else:
            total_lb = float(job.get("cargo_kg", 0)) * 2.20462262
            tail = min(3, nst)
            per = total_lb / float(tail) if tail else total_lb
            for i in range(nst - tail, nst):
                weights_lb[i] += max(0.0, per)
        applied = 0
        for idx, w in enumerate(weights_lb, start=1):
            if w <= 0:
                continue
            key = f"PAYLOAD STATION WEIGHT:{idx}"
            if self._aq.set(key, w):
                applied += 1
        kg_txt = int(
            float(job.get("pax", 0)) * 90.0
            if str(job.get("typ")) == "PAX"
            else float(job.get("cargo_kg", 0))
        )
        role = "Passagiere/Gepäck" if str(job.get("typ")) == "PAX" else "Fracht"
        msg = (
            f"Beladung abgeschlossen: ca. {kg_txt} kg ({role}) – "
            f"{applied} Payload-Station(en) beschrieben."
        )
        return applied > 0, msg

    def _refresh_mission_and_metar_ui(self) -> None:
        self._reload_active_job_from_db()
        aj = self._active_job
        if not aj:
            self.label_mission.setText(
                self._tr("sim.no_job", "Kein angenommener Auftrag.")
            )
            self.label_metar_raw.setText("METAR (raw): –")
            self.label_metar_human.setText("Lesbar: –")
            self.label_metar_human.setStyleSheet("")
            self._refresh_cabin_preview(None)
            self._fill_dispatch_crew_combo()
            self._update_boarding_enabled()
            return
        self.label_mission.setText(
            f"Aktiver Job {aj.get('id')}: {aj.get('dep')} → {aj.get('arr')} · "
            f"{aj.get('typ')} · {aj.get('narrative', '')} · "
            f"{format_eur_de(float(aj.get('reward', 0)))} · "
            f"Payload-MSFS: {'ja' if aj.get('payload_applied') else 'nein'}"
        )
        self._refresh_cabin_preview(aj)
        self._fill_dispatch_crew_combo()
        self._update_boarding_enabled()

    def _on_metar_refresh_clicked(self) -> None:
        self._reload_active_job_from_db()
        icao = (
            str(self._active_job.get("arr", "EDDF"))
            if self._active_job
            else "EDDF"
        )
        raw, err = fetch_metar_aviationweather(icao)
        if not raw:
            self.label_metar_raw.setText("METAR (raw): –")
            self.label_metar_human.setText(
                err or "Wetterdaten momentan nicht verfügbar."
            )
            self.label_metar_human.setStyleSheet("color: #ffb74d; font-weight: 600;")
            return
        self.label_metar_raw.setText(f"METAR (raw): {raw}")
        self.label_metar_human.setText(metar_human_summary(raw))
        hard, _ = metar_hard_conditions(raw)
        if hard:
            self.label_metar_human.setStyleSheet("color: #ff8a65; font-weight: 600;")
        else:
            self.label_metar_human.setStyleSheet("color: #69f0ae; font-weight: 500;")
        if self._active_job:
            self._active_job["dest_metar_hard"] = hard
            self._active_job["dest_metar_raw"] = raw
            save_active_job(DB_PATH, self._active_job)

