    def _simbrief_route_coords_for_map(self) -> list[list[float]]:
        raw = (app_meta_get(DB_PATH, "simbrief_nav_coords_json", "") or "").strip()
        if not raw:
            return []
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            return []
        if not isinstance(data, list):
            return []
        out: list[list[float]] = []
        for pt in data:
            if not isinstance(pt, (list, tuple)) or len(pt) < 2:
                continue
            la = _as_float(pt[0])
            lo = _as_float(pt[1])
            if la is None or lo is None:
                continue
            out.append([float(la), float(lo)])
        return out if len(out) >= 2 else []

    def _leaflet_live_payload(self, trail_slice: int) -> dict | None:
        if self._aq is None:
            return None
        la = _as_float(self._aq.get("PLANE LATITUDE"))
        lo = _as_float(self._aq.get("PLANE LONGITUDE"))
        if la is None or lo is None:
            return None
        aj = self._active_job
        dep_ll = arr_ll = None
        d_icao = "DEP"
        a_icao = "ARR"
        if aj:
            d_icao = str(aj.get("dep", ""))
            a_icao = str(aj.get("arr", ""))
            if d_icao in AIRPORT_COORDS and a_icao in AIRPORT_COORDS:
                dep_ll = AIRPORT_COORDS[d_icao]
                arr_ll = AIRPORT_COORDS[a_icao]
        sb = self._simbrief_route_coords_for_map()
        slc = max(8, int(trail_slice))
        branches: list[dict] = []
        for bic in list_airline_branch_icaos(DB_PATH):
            if bic in AIRPORT_COORDS:
                blla, bllo = AIRPORT_COORDS[bic]
                branches.append({"icao": bic, "lat": blla, "lon": bllo})
        payload: dict = {
            "lat": float(la),
            "lon": float(lo),
            "trail": [[x[0], x[1]] for x in self._map_trail[-slc:]],
            "peers": self._mp_peers_for_map(),
            "traffic": self._traffic_layer_for_map(float(la), float(lo)),
            "simbriefRoute": sb,
            "branches": branches,
        }
        if dep_ll and arr_ll:
            payload["dep"] = [dep_ll[0], dep_ll[1]]
            payload["arr"] = [arr_ll[0], arr_ll[1]]
            payload["dIcao"] = d_icao + " (Start)"
            payload["aIcao"] = a_icao + " (Ziel)"
        return payload

    def _on_map_timer_tick(self) -> None:
        if not self._map_live_wanted():
            return
        if not _WEBENGINE_AVAILABLE or self._map_view is None:
            return
        now_m = time.monotonic()
        if now_m - self._last_map_js_mono < 1.0 / GUI_MAP_MAX_FPS:
            return
        self._last_map_js_mono = now_m
        payload = self._leaflet_live_payload(180)
        if payload is None:
            return
        data = json.dumps(payload, separators=(",", ":"))
        try:
            self._map_view.page().runJavaScript(
                f"if(window.ctwApplyJSON)window.ctwApplyJSON({data});"
            )
        except Exception:
            pass

    def _efb_push_navigraph_token(self, view: object) -> None:
        """Setzt Navigraph-Badge/Overlay auf der EFB-Karte (MS110), gecacht."""
        if not _WEBENGINE_AVAILABLE or view is None:
            return
        try:
            tok = navigraph_get_valid_access_token(DB_PATH) or ""
        except Exception:
            tok = ""
        last = getattr(self, "_efb_nav_token_last", None)
        if tok == last:
            return
        self._efb_nav_token_last = tok
        js_tok = json.dumps(tok)
        try:
            view.page().runJavaScript(
                f"if(window.ctwSetNavigraphToken)window.ctwSetNavigraphToken({js_tok});"
            )
        except Exception:
            pass

    def _push_efb_map(self, view: object, efb_follow: bool) -> None:
        if not _WEBENGINE_AVAILABLE or view is None:
            return
        now_m = time.monotonic()
        if now_m - self._last_efb_map_js < 0.35:
            return
        self._last_efb_map_js = now_m
        self._efb_push_navigraph_token(view)
        pl = self._leaflet_live_payload(140)
        if pl is None:
            return
        pl["efbFollow"] = bool(efb_follow)
        data = json.dumps(pl, separators=(",", ":"))
        try:
            view.page().runJavaScript(
                f"if(window.ctwEfbApplyJSON)window.ctwEfbApplyJSON({data});"
            )
        except Exception:
            pass

    def _mp_peers_for_map(self) -> list[dict]:
        out: list[dict] = []
        my_hw = p2p_hardware_id(DB_PATH)
        for p in self._mp_peers:
            pid = str(p.get("id", ""))
            if pid == self._mp_client_id or pid == my_hw:
                continue
            try:
                out.append(
                    {
                        "lat": float(p["lat"]),
                        "lon": float(p["lon"]),
                        "pilot": str(p.get("pilot", "?"))[:40],
                        "route": str(p.get("route", "–"))[:48],
                    }
                )
            except (KeyError, TypeError, ValueError):
                continue
        return out

    def _mp_demo_peers(self, la: float, lo: float) -> list[dict]:
        rng = random.Random(int(time.time()) // 120)
        peers: list[dict] = []
        for i in range(3):
            brg = rng.random() * 360.0
            dnm = 25.0 + i * 30.0
            dlat = (dnm / 60.0) * math.cos(math.radians(brg))
            dlon = (
                (dnm / 60.0)
                * math.sin(math.radians(brg))
                / max(0.2, math.cos(math.radians(la)))
            )
            peers.append(
                {
                    "id": f"demo{i}",
                    "pilot": f"Demo-Pilot {i + 1}",
                    "lat": la + dlat,
                    "lon": lo + dlon,
                    "alt": 8000 + i * 2000,
                    "hdg": brg,
                    "route": "EDDF → EGLL",
                    "ts": time.time(),
                }
            )
        return peers

    def _sim_at_gate_parking(self) -> bool:
        """Am Gate: Boden + Triebwerke aus + Parkbremse gesetzt."""
        if self._aq is None:
            return False
        if _sim_on_ground_safe_int(self._aq.get("SIM_ON_GROUND")) != 1:
            return False
        eng_rpm = float(_as_float(self._aq.get("GENERAL ENG RPM:1")) or 0.0)
        if eng_rpm > 0.5:
            try:
                if int(float(self._aq.get("GENERAL ENG COMBUSTION:1") or 0)) != 0:
                    return False
            except (TypeError, ValueError):
                pass
        park = _as_float(self._aq.get("BRAKE PARKING POSITION"))
        if park is None:
            park = _as_float(self._aq.get("PARKING BRAKE"))
        if park is None:
            park = _as_float(self._aq.get("BRAKE PARKING INDICATOR"))
        return float(park or 0.0) >= 0.5

    def determine_current_flight_phase(self) -> str:
        """M194: Live-Flugphase aus SimConnect (interner Schlüssel für i18n)."""
        if self._aq is None:
            return "unknown"
        if self._sim_at_gate_parking():
            return "parked"
        try:
            gsx_board = int(float(self._aq.get("L:FSDT_GSX_BOARDING_STATE") or 0))
        except (TypeError, ValueError):
            gsx_board = 0
        if gsx_board == 4:
            return "boarding"
        on_ground = _sim_on_ground_safe_int(self._aq.get("SIM_ON_GROUND")) == 1
        try:
            eng_rpm = float(self._aq.get("GENERAL ENG RPM:1") or 0.0)
        except (TypeError, ValueError):
            eng_rpm = 0.0
        gvel = _as_float(self._aq.get("GROUND VELOCITY"))
        if gvel is None:
            gvel = _as_float(self._aq.get("GROUND_VELOCITY"))
        gvel = float(gvel or 0.0)
        vs = float(_as_float(self._aq.get("VERTICAL_SPEED")) or 0.0)
        try:
            gear = float(self._aq.get("GEAR HANDLE POSITION") or 0.0)
        except (TypeError, ValueError):
            gear = 0.0
        gear_down = gear >= 0.5
        if on_ground and eng_rpm <= 0.5:
            return "parked"
        if on_ground and eng_rpm > 0.5 and gvel > 2.0:
            return "taxi"
        if not on_ground and vs > 500:
            return "climb"
        if not on_ground and abs(vs) <= 500:
            return "cruise"
        if not on_ground and vs < -500 and not gear_down:
            return "descent"
        if not on_ground and vs < -200 and gear_down:
            return "approach"
        return "unknown"

    def _fids_phase_label(self, phase_key: str) -> str:
        key = (phase_key or "unknown").strip().lower()
        fids_map = {
            "boarding": ("fids.phase.boarding", "Boarding"),
            "parked": ("fids.phase.parked", "AM GATE / PARKING"),
            "climb": ("fids.phase.climb", "Steigflug"),
            "cruise": ("fids.phase.cruise", "Reiseflug"),
            "approach": ("fids.phase.approach", "Endanflug"),
        }
        if key in fids_map:
            fk, fd = fids_map[key]
            return self._tr(fk, fd)
        defaults = {
            "taxi": "Rollen",
            "descent": "Sinkflug",
            "unknown": "Unbekannt",
        }
        return self._tr(f"flight.phase.{key}", defaults.get(key, key))

    def _fids_phase_item_style(self, phase_key: str) -> str:
        pk = (phase_key or "").strip().lower()
        if pk == "boarding":
            return "color: #00e5ff; font-weight: bold;"
        if pk in ("cruise", "approach"):
            return "color: #00ff66; font-weight: bold;"
        if pk == "parked":
            return "color: #ffab40;"
        return "color: #ffcc00;"

    def fetch_global_online_pilots_fids(self) -> None:
        """M193: Weltweite Live-Flugtafel von skytycoon.info (QNAM, Zero-Freeze)."""
        if getattr(self, "_fids_fetch_inflight", False):
            return
        root = (ionos_server_url() or "").strip().rstrip("/")
        if not root:
            if hasattr(self, "label_fids_status"):
                self.label_fids_status.setText(
                    self._tr("fids.status_no_server", "Kein IONOS-Server konfiguriert.")
                )
            return
        self._fids_fetch_inflight = True
        if hasattr(self, "label_fids_status"):
            self.label_fids_status.setText(
                self._tr("fids.status_loading", "Lade weltweite Flugbewegungen…")
            )
        req = QNetworkRequest(QUrl(f"{root}/api/v1/web/radar/positions"))
        rep = self._nam.get(req)
        rep.setProperty("kind", "fids_radar_fetch")

    def _apply_fids_positions(self, positions: list) -> None:
        tbl = getattr(self, "table_fids_online", None)
        if tbl is None:
            return
        tbl.setRowCount(0)
        my_pilot = (
            pilot_handle(DB_PATH).strip().lower()
            or str(getattr(self, "pilot_display_name", "") or "").strip().lower()
        )
        my_hw = p2p_hardware_id(DB_PATH).strip().lower()
        if not positions:
            if hasattr(self, "label_fids_status"):
                self.label_fids_status.setText(
                    self._tr(
                        "fids.status_empty",
                        "Keine Piloten aktuell in der Luft (letzte 5 Min.).",
                    )
                )
            tbl.viewport().update()
            tbl.repaint()
            return
        for p in positions:
            if not isinstance(p, dict):
                continue
            pilot = str(p.get("pilot") or p.get("pilot_name") or "?")[:80]
            pid = str(p.get("id") or p.get("hardware_id") or "").strip().lower()
            is_self = bool(
                my_pilot
                and pilot.strip().lower() == my_pilot
            ) or bool(my_hw and pid == my_hw)
            aircraft = str(p.get("aircraft") or "—")[:80]
            route = str(p.get("route") or "—")[:120]
            phase_raw = str(
                p.get("flight_phase") or p.get("phase") or "unknown"
            ).strip().lower()
            try:
                alt = int(float(p.get("alt", 0) or 0))
            except (TypeError, ValueError):
                alt = 0
            gs = float(
                _as_float(p.get("ground_speed"))
                or _as_float(p.get("gs"))
                or _as_float(p.get("speed"))
                or 0.0
            )
            try:
                ts = float(p.get("ts", 0) or 0)
            except (TypeError, ValueError):
                ts = 0.0
            ping = (
                datetime.fromtimestamp(ts, tz=timezone.utc).strftime("%H:%M:%S")
                if ts > 0
                else "—"
            )
            row = tbl.rowCount()
            tbl.insertRow(row)
            phase_txt = self._fids_phase_label(phase_raw)
            cells = (
                pilot,
                aircraft,
                route,
                phase_txt,
                f"{alt:,d}",
                f"{int(round(gs)):,d}",
                ping,
            )
            for col, txt in enumerate(cells):
                it = QTableWidgetItem(txt)
                it.setTextAlignment(
                    int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
                )
                if col == 3:
                    it.setForeground(QColor("#00e5ff"))
                    it.setData(Qt.ItemDataRole.UserRole, phase_raw)
                    style = self._fids_phase_item_style(phase_raw)
                    if "00ff66" in style:
                        it.setForeground(QColor("#00ff66"))
                    elif "ffab40" in style:
                        it.setForeground(QColor("#ffab40"))
                    elif "00e5ff" in style:
                        it.setForeground(QColor("#00e5ff"))
                    f = it.font()
                    f.setBold("bold" in style)
                    it.setFont(f)
                if is_self:
                    it.setForeground(QColor("#ffff00"))
                    f_self = it.font()
                    f_self.setBold(True)
                    it.setFont(f_self)
                tbl.setItem(row, col, it)
        if hasattr(self, "label_fids_status"):
            self.label_fids_status.setText(
                self._tr("fids.status_ok", "{n} aktive Piloten (Live-FIDS).").format(
                    n=tbl.rowCount()
                )
            )
        tbl.viewport().update()
        tbl.repaint()

    def _retranslate_fids_table_headers(self) -> None:
        tbl = getattr(self, "table_fids_online", None)
        keys = getattr(self, "_fids_header_keys", ())
        defaults = getattr(self, "_fids_header_defaults", ())
        if tbl is None or not keys:
            return
        tbl.setHorizontalHeaderLabels(
            [self._tr(k, d) for k, d in zip(keys, defaults, strict=False)]
        )

