    def _apply_cloud_rank_display(self, data: dict[str, Any]) -> None:
        if not hasattr(self, "label_prof_rank"):
            return
        rank = data.get("rank") or {}
        next_rank = data.get("next_rank")
        miles = float(data.get("miles") or 0)
        prestige = int(data.get("prestige_level") or 0)
        lvl = int(rank.get("level") or 1)
        rname = str(rank.get("name") or "Flugschüler")
        self.label_prof_rank.setText(
            self._tr("profile.rank_line", "Rang Stufe {lvl}: {name}").format(lvl=lvl, name=rname)
        )
        if hasattr(self, "label_prof_miles"):
            self.label_prof_miles.setText(
                self._tr("profile.miles_line", "Geflogene Meilen: {m} NM").format(m=f"{miles:,.1f}")
            )
        if hasattr(self, "label_prof_prestige_badge"):
            if prestige > 0:
                self.label_prof_prestige_badge.setText(
                    f"👑 PRESTIGE {prestige} — {'Geheimränge aktiv' if prestige >= 1 else ''}"
                )
            else:
                self.label_prof_prestige_badge.setText("")
        if hasattr(self, "prog_rank_miles"):
            pct = float(data.get("progress_pct") or 0)
            self.prog_rank_miles.setValue(int(max(0, min(100, pct))))
            if next_rank:
                need = float(next_rank.get("min_miles") or 0) - miles
                self.prog_rank_miles.setFormat(
                    self._tr("profile.rank_progress", "{pct}% · noch {nm} NM bis {next}").format(
                        pct=int(pct),
                        nm=f"{max(0, need):,.0f}",
                        next=str(next_rank.get("name") or "?"),
                    )
                )
            else:
                self.prog_rank_miles.setFormat(self._tr("profile.rank_max", "Maximaler Rang erreicht"))

    def _on_buy_type_rating_class_clicked(self, cls: str, mod_key: str, cost: int) -> None:
        try:
            import skytycoon_prestige_pack as _pp

            hid = p2p_hardware_id(DB_PATH)
            if _pp.pg_has_module(hid, mod_key):
                QMessageBox.information(self, "Type-Rating", self._tr("hangar.type_rating_owned", "Bereits freigeschaltet."))
                self._refresh_type_rating_cards()
                return
            ok, msg = _pp.pg_buy_module(hid, mod_key)
            if not ok:
                QMessageBox.warning(self, "Type-Rating", msg)
                return
            for model in _pp.TYPE_RATING_CLASS_MODELS.get(cls, ()):
                grant_type_rating(DB_PATH, model)
            self._append_log(f"Type-Rating-Klasse {cls} freigeschaltet ({cost:,} CR).")
            self._refresh_type_rating_cards()
            self._refresh_credits_label()
            QMessageBox.information(self, "Type-Rating", self._tr("hangar.type_rating_ok", "Type-Rating gebucht."))
        except Exception as exc:
            QMessageBox.warning(self, "Type-Rating", str(exc))

    def _refresh_type_rating_cards(self) -> None:
        if not hasattr(self, "_type_rating_cards"):
            return
        try:
            import skytycoon_prestige_pack as _pp

            hid = p2p_hardware_id(DB_PATH)
            for cls, meta in self._type_rating_cards.items():
                mod = str(meta.get("module") or "")
                owned = _pp.pg_has_module(hid, mod)
                st: QLabel = meta["status"]
                btn: QPushButton = meta["button"]
                fr: QFrame = meta["frame"]
                if owned:
                    st.setText("🟢 FREIGESCHALTET / UNLOCKED")
                    st.setStyleSheet("color:#00ff66;font-weight:800;")
                    btn.setEnabled(False)
                    fr.setStyleSheet(
                        "QFrame { background:#0d1a12; border:2px solid #00ff66; border-radius:10px; padding:10px; }"
                    )
                else:
                    st.setText(
                        f"🔒 GESPERRT / LOCKED — {int(meta.get('cost', 250000)):,} CR"
                    )
                    st.setStyleSheet("color:#78909c;")
                    btn.setEnabled(True)
                    fr.setStyleSheet(
                        "QFrame { background:#0b0f19; border:2px solid #d4af37; border-radius:10px; padding:10px; opacity:0.92; }"
                    )
        except Exception:
            pass

    def _on_buy_type_rating_clicked(self, model: str, cost: int) -> None:
        if has_type_rating(DB_PATH, model):
            QMessageBox.information(
                self,
                self._tr("hangar.type_rating_title", "Type-Ratings (Prestige-XP)"),
                self._tr("hangar.type_rating_owned", "Bereits erworben."),
            )
            return
        meta = get_pilot_meta(DB_PATH)
        if float(meta["xp"]) < float(cost):
            QMessageBox.warning(
                self,
                self._tr("hangar.type_rating_title", "Type-Ratings (Prestige-XP)"),
                self._tr(
                    "hangar.type_rating_no_xp",
                    "Nicht genug Prestige-XP (benötigt {need}, vorhanden {have}).",
                ).format(need=cost, have=int(float(meta["xp"]))),
            )
            return
        add_xp(DB_PATH, -float(cost))
        grant_type_rating(DB_PATH, model)
        self._append_log(
            self._tr(
                "hangar.type_rating_purchased_log",
                "Type-Rating erworben: {model} (−{cost} XP).",
            ).format(model=model, cost=cost)
        )
        self._refresh_type_rating_shop_buttons()
        QMessageBox.information(
            self,
            self._tr("hangar.type_rating_title", "Type-Ratings (Prestige-XP)"),
            self._tr("hangar.type_rating_ok", "Type-Rating gebucht."),
        )

    def _refresh_type_rating_shop_buttons(self) -> None:
        self._refresh_type_rating_cards()

    def _set_status_safe(self, msg: str, timeout_ms: int = 8000) -> None:
        try:
            self.statusBar().showMessage(msg, timeout_ms)
        except Exception:
            pass

    def eventFilter(self, obj: QObject, event: QEvent) -> bool:  # noqa: ANN401
        if obj is getattr(self, "label_airline_logo_dash", None) and event.type() == QEvent.Type.MouseButtonDblClick:
            self._try_launch_admin_commander()
            return True
        return super().eventFilter(obj, event)

    def _try_launch_admin_commander(self) -> None:
        script = BASE_DIR / "Admin_Commander.py"
        if not script.is_file():
            QMessageBox.warning(self, self._tr("ui.auto.admin_e3afed00", "Admin"), f"Datei fehlt:\n{script}",
            )
            return
        QProcess.startDetached(
            sys.executable,
            [str(script)],
            str(BASE_DIR),
        )
        self._set_status_safe("Admin Commander gestartet.", 6000)

    def resizeEvent(self, event) -> None:  # type: ignore[override]
        super().resizeEvent(event)
        self._layout_maintenance_overlay()

    def _layout_maintenance_overlay(self) -> None:
        if not hasattr(self, "_maintenance_overlay"):
            return
        cw = self.centralWidget()
        if cw is None:
            return
        top_left = cw.mapTo(self, cw.rect().topLeft())
        self._maintenance_overlay.setGeometry(
            top_left.x(), top_left.y(), cw.width(), cw.height()
        )
        self._maintenance_overlay.raise_()

    def _sync_maintenance_overlay(self) -> None:
        if not hasattr(self, "_maintenance_overlay"):
            return
        on = app_meta_get(DB_PATH, "cloud_maintenance_active", "0") == "1"
        self._maint_ov_title.setText(
            self._tr(
                "maintenance.block_title",
                "SkyTycoon Pro – Wartungsarbeiten\nBitte später erneut starten.",
            )
        )
        msg = app_meta_get(DB_PATH, "ionos_maintenance_message", "").strip()
        if hasattr(self, "_maint_ov_body"):
            if msg:
                self._maint_ov_body.setText(msg)
            else:
                self._maint_ov_body.setText(
                    self._tr(
                        "maintenance.block_body_generic",
                        "Der Server meldet Wartungsarbeiten. Bitte versuchen Sie es später erneut.",
                    )
                )
        if on:
            self._maintenance_overlay.show()
            self._layout_maintenance_overlay()
            try:
                self.tab_widget.setEnabled(False)
            except Exception:
                pass
        else:
            self._maintenance_overlay.hide()
            try:
                self.tab_widget.setEnabled(True)
            except Exception:
                pass

    def _layout_support_inbox_style_idle(self) -> None:
        if not hasattr(self, "btn_support_inbox"):
            return
        self.btn_support_inbox.setStyleSheet(
            "QPushButton#btn_support_inbox { background-color:#37474f; color:#eceff1; "
            "font-size:22px; border-radius:8px; border:1px solid #546e7a; }"
            "QPushButton#btn_support_inbox:hover { background-color:#455a64; }"
        )
        self.btn_support_inbox.setToolTip(
            self._tr("support.inbox_idle_tip", "Support & Live-Chat öffnen")
        )

    def _on_support_blink_tick(self) -> None:
        if not hasattr(self, "btn_support_inbox"):
            return
        self._support_blink_on = not self._support_blink_on
        if self._support_blink_on:
            self.btn_support_inbox.setStyleSheet(
                "QPushButton#btn_support_inbox { background-color:#c62828; color:#ffffff; "
                "font-size:22px; border-radius:8px; border:2px solid #ff5252; font-weight:800;}"
            )
        else:
            self.btn_support_inbox.setStyleSheet(
                "QPushButton#btn_support_inbox { background-color:#263238; color:#90a4ae; "
                "font-size:22px; border-radius:8px; border:1px solid #455a64; }"
            )
        self.btn_support_inbox.setToolTip(
            self._tr(
                "support.inbox_new_tooltip",
                "Neue Nachricht vom Support verfügbar!",
            )
        )
        try:
            self.btn_support_inbox.repaint()
            self.btn_support_inbox.update()
        except Exception:
            pass

    def _stop_support_blink(self) -> None:
        self._support_blink_timer.stop()
        self._layout_support_inbox_style_idle()

    def _ack_support_read_firebase(self) -> None:
        hid = p2p_hardware_id(DB_PATH)
        url = _firebase_support_ticket_url(hid)
        _firebase_patch_json(url, {"status": "pending"}, timeout=12.0)

    def _poll_support_ticket_head_firebase(self) -> None:
        if self._support_dialog_open:
            return
        if not _firebase_support_base_url().strip():
            return
        hid = p2p_hardware_id(DB_PATH)
        url = _firebase_support_ticket_url(hid)
        data = _firebase_get_json(url, timeout=8.0)
        if not isinstance(data, dict):
            return
        st = str(data.get("status", "")).lower()
        if st == "replied":
            if not self._support_blink_timer.isActive():
                self._support_blink_on = False
                self._support_blink_timer.start()
        else:
            self._stop_support_blink()

    def _on_storm_warn_blink_tick(self) -> None:
        if not hasattr(self, "label_storm_landing_warn"):
            return
        if not self._storm_warn_visible:
            self._storm_warn_blink_timer.stop()
            return
        self._storm_ui_phase = not self._storm_ui_phase
        c = "#ff5252" if self._storm_ui_phase else "#78909c"
        self.label_storm_landing_warn.setStyleSheet(
            f"font-size:15px;font-weight:800;color:{c};padding:6px;"
            "background-color:#1a0000;border:1px solid #b71c1c;border-radius:6px;"
        )

    def _flight_storm_challenge_met(self, aj: dict | None) -> bool:
        mt = float(self._storm_snap_total)
        mc = float(self._storm_snap_cross)
        raw = ""
        if aj:
            raw = str(aj.get("dest_metar_raw", "") or "")
        if raw.strip():
            pk = metar_surface_wind_peak_kt(raw)
            ec = metar_est_max_crosswind_kt(raw)
            mt = max(mt, pk)
            mc = max(mc, ec)
        return (
            mt >= STORM_MIN_TOTAL_WIND_KT
            or mc >= STORM_MIN_CROSSWIND_KT
        )

    def _sync_preflight_checkbox_green(self, part: str) -> None:
        app_meta_set(DB_PATH, f"preflight_maint_{part}", "1")
        for c in self._maint_preflight_boxes.get(part, []):
            c.blockSignals(True)
            c.setChecked(True)
            c.blockSignals(False)
        self._update_boarding_enabled()

    def _open_support_troubleshoot_dialog(self) -> None:
        self._support_dialog_open = True
        self._stop_support_blink()
        try:
            d = _firebase_get_json(
                _firebase_support_ticket_url(p2p_hardware_id(DB_PATH)),
                timeout=6.0,
            )
            if isinstance(d, dict) and str(d.get("status", "")).lower() == "replied":
                self._ack_support_read_firebase()
        except Exception:
            pass
        self._layout_support_inbox_style_idle()
        dlg = QDialog(self)
        dlg.setWindowTitle(
            self._tr("help.support_title", "Support & Fehlerbehebung")
        )
        dlg.resize(760, 560)
        dlg.setStyleSheet(
            "QDialog { background-color: #1e1e1e; } "
            "QTextBrowser { background-color: #121212; color: #eceff1; border: 1px solid #444; } "
            "QLineEdit { background-color: #121212; color: #eceff1; border: 1px solid #444; }"
        )
        vl = QVBoxLayout(dlg)
        tabs = QTabWidget()
        tip = QWidget()
        tl = QVBoxLayout(tip)
        tb_tip = QTextBrowser()
        tb_tip.setReadOnly(True)
        tb_tip.setHtml(self._tr("help.support_html", "<p>Support-Inhalt.</p>"))
        tl.addWidget(tb_tip)
        tabs.addTab(tip, self._tr("help.support_tab_tips", "Tipps"))
        chat_w = QWidget()
        cl = QVBoxLayout(chat_w)
        chat_hist = QTextBrowser()
        chat_hist.setReadOnly(True)
        chat_hist.setObjectName("support_chat_history")
        cl.addWidget(chat_hist, 1)
        row = QHBoxLayout()
        inp = QLineEdit()
        inp.setObjectName("support_input_message")
        btn_send = QPushButton(self._tr("support.send_btn", "🚀 Senden"))
        row.addWidget(inp, 1)
        row.addWidget(btn_send)
        cl.addLayout(row)
        tabs.addTab(chat_w, self._tr("support.chat_tab", "Live-Chat"))
        vl.addWidget(tabs)

        hid = p2p_hardware_id(DB_PATH)
        pilot = (app_meta_get(DB_PATH, "pilot_display_name", "") or "Pilot").strip()
        seen_msg_keys: set[str] = set()
        first_poll = True

        def _append_chat_line(html: str) -> None:
            chat_hist.append(html)
            sb = chat_hist.verticalScrollBar()
            sb.setValue(sb.maximum())

        def _send_user() -> None:
            txt = inp.text().strip()
            if not txt:
                return
            inp.clear()
            ts = int(time.time())
            mid = f"m_{uuid.uuid4().hex[:12]}"
            msg = {
                "timestamp": ts,
                "sender": "user",
                "pilot_name": pilot[:80],
                "message_text": txt[:2000],
            }
            ok, err = _firebase_patch_json(
                f"{_firebase_support_base_url()}/support_tickets/{quote(hid, safe='')}/messages/{quote(mid, safe='')}.json",
                msg,
            )
            head_url = f"{_firebase_support_base_url()}/support_tickets/{quote(hid, safe='')}.json"
            _firebase_patch_json(
                head_url,
                {
                    "status": "open",
                    "pilot_name": pilot[:80],
                    "hardware_id": hid,
                    "last_message_ts": ts,
                },
            )
            if ok:
                seen_msg_keys.add(mid)
                _append_chat_line(
                    f"<span style='color:#aed581'>{pilot}: {msg['message_text']}</span>"
                )
            else:
                _append_chat_line(
                    self._tr(
                        "support.send_err",
                        "Senden fehlgeschlagen: {e}",
                    ).format(e=err or "?")
                )

        def _poll() -> None:
            nonlocal first_poll
            url = f"{_firebase_support_base_url()}/support_tickets/{quote(hid, safe='')}/messages.json"
            data = _firebase_get_json(url, timeout=8.0)
            if not isinstance(data, dict):
                return
            for k, v in data.items():
                if not isinstance(v, dict):
                    continue
                if first_poll:
                    seen_msg_keys.add(str(k))
                    continue
                if str(k) in seen_msg_keys:
                    continue
                seen_msg_keys.add(str(k))
                if str(v.get("sender")) == "admin":
                    mtxt = str(v.get("message_text", ""))
                    _append_chat_line(
                        f"<span style='color:#64b5f6'><b>Admin:</b> {mtxt}</span>"
                    )
            first_poll = False

        btn_send.clicked.connect(_send_user)
        inp.returnPressed.connect(_send_user)
        pol = QTimer(dlg)
        pol.setInterval(10_000)
        pol.timeout.connect(_poll)
        pol.start()
        try:
            dlg.exec()
        finally:
            pol.stop()
            self._support_dialog_open = False

    def _on_alliance_refresh_clicked(self) -> None:
        self._refresh_alliance_panel()
        self._request_alliance_check()

    def _on_menu_set_cloud_password(self) -> None:
        existing = self._cloud_password_stored()
        pw, ok = QInputDialog.getText(
            self,
            self._tr("menu.cloud_password_title", "Cloud-Passwort"),
            self._tr(
                "menu.cloud_password_prompt",
                "Passwort Ihres skytycoon.info-Kundenkontos (wie im Web-Login):",
            ),
            QLineEdit.EchoMode.Password,
            existing,
        )
        if not ok:
            return
        self._save_cloud_password(pw)
        em_existing = (app_meta_get(DB_PATH, "portal_email", "") or "").strip()
        em, ok_em = QInputDialog.getText(
            self,
            self._tr("menu.cloud_password_title", "Cloud-Passwort"),
            self._tr(
                "menu.portal_email_prompt",
                "E-Mail des Web-Kundenkontos (Dashboard/Admin-Abgleich):",
            ),
            QLineEdit.EchoMode.Normal,
            em_existing,
        )
        if ok_em and em.strip() and "@" in em.strip():
            try:
                app_meta_set(DB_PATH, "portal_email", em.strip().lower()[:200])
            except OSError:
                pass
        QMessageBox.information(
            self,
            self._tr("menu.cloud_password_title", "Cloud-Passwort"),
            self._tr("menu.cloud_password_saved", "Cloud-Passwort gespeichert."),
        )
        try:
            self._request_alliance_check()
        except Exception:
            pass

    def _local_profile_fallback_data(self) -> dict:
        meta = get_pilot_meta(DB_PATH)
        rep = float(app_meta_get(DB_PATH, "company_reputation", "72") or 72)
        key = (app_meta_get(DB_PATH, "license_key_installed", "") or "").strip()
        al_snap: dict = {"in_alliance": False}
        raw = (app_meta_get(DB_PATH, "alliance_snapshot_json", "") or "").strip()
        if raw:
            try:
                ad = json.loads(raw)
                if isinstance(ad, dict):
                    al_snap = ad
            except json.JSONDecodeError:
                pass
        return {
            "status": "local",
            "ok": True,
            "pilot_name": pilot_handle(DB_PATH),
            "email": (app_meta_get(DB_PATH, "portal_email", "") or "").strip(),
            "hardware_id": p2p_hardware_id(DB_PATH),
            "credits": float(meta.get("credits", 0)),
            "xp": float(meta.get("xp", 0)),
            "reputation": rep,
            "has_license": 1 if key else 0,
            "is_verified": 1,
            "alliance": al_snap,
        }

    def _open_customer_profile_dialog(self) -> None:
        if not self._ionos_cloud_ready():
            QMessageBox.warning(
                self,
                self._tr("profile.dialog_title", "Mein Kundenprofil"),
                self._tr(
                    "profile.cloud_credentials_required",
                    "Bitte unter Datei → Cloud-Passwort Ihr skytycoon.info-Passwort "
                    "und die Portal-E-Mail hinterlegen.",
                ),
            )
            self._on_menu_set_cloud_password()
            if not self._ionos_cloud_ready():
                PremiumKundenkontoDialog(
                    self, self._local_profile_fallback_data()
                ).exec()
                return
        cached = getattr(self, "_cached_server_profile_data", None)
        if isinstance(cached, dict) and profile_cloud_payload_ok(cached):
            PremiumKundenkontoDialog(self, cached).exec()
            self._profile_dialog_pending_open = False
            self._request_alliance_check()
            return
        self._profile_dialog_pending_open = True
        self._request_alliance_check()

    def _finish_customer_profile_dialog(self, server_json: dict | None) -> None:
        if not getattr(self, "_profile_dialog_pending_open", False):
            return
        self._profile_dialog_pending_open = False
        if isinstance(server_json, dict) and profile_cloud_payload_ok(server_json):
            self._cached_server_profile_data = dict(server_json)
            PremiumKundenkontoDialog(self, server_json).exec()
            return
        PremiumKundenkontoDialog(self, self._local_profile_fallback_data()).exec()
        if self._cloud_password_stored():
            QMessageBox.warning(
                self,
                self._tr("profile.dialog_title", "Mein Kundenprofil"),
                self._tr(
                    "profile.cloud_offline",
                    "Cloud nicht erreichbar — lokale Daten werden angezeigt. "
                    "Prüfen Sie Passwort und E-Mail (Datei → Cloud-Passwort).",
                ),
            )

    def _open_backup_restore_dialog(self) -> None:
        dlg = QDialog(self)
        dlg.setWindowTitle(
            self._tr("backup.dialog_title", "Datensicherung & Wiederherstellung")
        )
        dlg.resize(540, 440)
        v = QVBoxLayout(dlg)
        g1 = QGroupBox(self._tr("backup.sec_local", "Lokales Backup"))
        v1 = QVBoxLayout(g1)
        btn_local = QPushButton(
            self._tr("backup.btn_local", "🔧 Lokales Backup erstellen")
        )
        v1.addWidget(btn_local)
        g2 = QGroupBox(self._tr("backup.sec_cloud", "Cloud-Sicherung"))
        v2 = QVBoxLayout(g2)
        v2.addWidget(
            QLabel(self._tr("backup.cloud_pw_hint", "Cloud-Passwort (IONOS, gespeichert):"))
        )
        ed_pw = QLineEdit()
        ed_pw.setEchoMode(QLineEdit.EchoMode.Password)
        ed_pw.setText(self._cloud_password_stored())
        v2.addWidget(ed_pw)
        btn_save_pw = QPushButton(self._tr("backup.btn_save_pw", "Passwort speichern"))
        v2.addWidget(btn_save_pw)
        btn_cloud = QPushButton(
            self._tr("backup.btn_cloud_restore", "☁️ Letztes Cloud-Backup wiederherstellen")
        )
        v2.addWidget(btn_cloud)
        g3 = QGroupBox(self._tr("backup.sec_status", "Status"))
        v3 = QVBoxLayout(g3)
        lab_st = QLabel("—")
        lab_st.setWordWrap(True)
        v3.addWidget(lab_st)

        def _refresh_status() -> None:
            ts = app_meta_get(DB_PATH, "last_career_backup_ts", "").strip()
            txt = self._tr("backup.status_last_cloud", "Letztes Cloud-/Lande-Backup: {t}").format(
                t=ts or "—"
            )
            backs = sorted(
                BACKUP_DIR.glob("career_*.db"),
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            if backs:
                tloc = time.strftime(
                    "%d.%m.%Y %H:%M", time.localtime(backs[0].stat().st_mtime)
                )
                txt += "\n" + self._tr(
                    "backup.status_last_local_file",
                    "Neueste lokale Datei: {f} ({t})",
                ).format(f=backs[0].name, t=tloc)
            lab_st.setText(txt)

        def _do_local() -> None:
            try:
                backup_career_database(DB_PATH, BACKUP_MAX_KEEP)
            except OSError:
                QMessageBox.warning(
                    dlg,
                    self._tr("backup.dialog_title", "Datensicherung"),
                    self._tr("backup.local_fail", "Lokales Backup fehlgeschlagen."),
                )
                return
            app_meta_set(DB_PATH, "last_career_backup_ts", str(int(time.time())))
            QMessageBox.information(
                dlg,
                self._tr("backup.dialog_title", "Datensicherung"),
                self._tr("backup.local_ok", "Lokales Backup erfolgreich erstellt!"),
            )
            _refresh_status()

        def _save_pw() -> None:
            self._save_cloud_password(ed_pw.text())
            QMessageBox.information(
                dlg,
                self._tr("backup.dialog_title", "Datensicherung"),
                self._tr("backup.pw_saved", "Passwort gespeichert."),
            )

        def _do_cloud() -> None:
            self._save_cloud_password(ed_pw.text())
            base = ionos_api_base_url()
            pw = ed_pw.text().strip()
            if not base or not pw:
                QMessageBox.warning(
                    dlg,
                    self._tr("backup.dialog_title", "Datensicherung"),
                    self._tr(
                        "backup.cloud_no_config",
                        "Bitte SKYTYCOON_IONOS_API_BASE setzen und Passwort eingeben.",
                    ),
                )
                return
            okc = QMessageBox.question(
                dlg,
                self._tr("backup.cloud_confirm_title", "Cloud-Wiederherstellung"),
                self._tr(
                    "backup.cloud_confirm_body",
                    "Die lokale career.db wird überschrieben. Fortfahren?",
                ),
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if okc != QMessageBox.StandardButton.Yes:
                return
            hid = p2p_hardware_id(DB_PATH)
            try:
                r = requests.get(
                    f"{base}/api/v1/user/backup/download",
                    params={"hardware_id": hid, "password": pw},
                    timeout=120,
                    headers={"User-Agent": f"{SKYTYCOON_APP_NAME}/{APP_VERSION}"},
                )
            except Exception as exc:
                QMessageBox.warning(
                    dlg,
                    self._tr("backup.dialog_title", "Datensicherung"),
                    self._tr("backup.cloud_net_err", "Download fehlgeschlagen: {e}").format(
                        e=exc
                    ),
                )
                return
            if r.status_code != 200:
                QMessageBox.warning(
                    dlg,
                    self._tr("backup.dialog_title", "Datensicherung"),
                    self._tr("backup.cloud_http", "Server-Fehler (HTTP {c}).").format(
                        c=r.status_code
                    ),
                )
                return
            BACKUP_DIR.mkdir(parents=True, exist_ok=True)
            tmp = BACKUP_DIR / "_restore_cloud.db"
            tmp.write_bytes(r.content)
            if not _career_db_quick_check_ok(tmp):
                try:
                    tmp.unlink()
                except OSError:
                    pass
                QMessageBox.warning(
                    dlg,
                    self._tr("backup.dialog_title", "Datensicherung"),
                    self._tr("backup.cloud_bad_file", "Heruntergeladene Datei ist keine gültige DB."),
                )
                return
            try:
                shutil.copy2(DB_PATH, BACKUP_DIR / "pre_restore_backup.db")
            except OSError:
                pass
            try:
                shutil.copy2(tmp, DB_PATH)
                tmp.unlink(missing_ok=True)
            except OSError as exc:
                QMessageBox.warning(
                    dlg,
                    self._tr("backup.dialog_title", "Datensicherung"),
                    self._tr("backup.cloud_copy_fail", "Konnte DB nicht ersetzen: {e}").format(
                        e=exc
                    ),
                )
                return
            QMessageBox.information(
                dlg,
                self._tr("backup.dialog_title", "Datensicherung"),
                self._tr("backup.cloud_ok", "Wiederherstellung abgeschlossen. Bitte App neu starten."),
            )
            dlg.accept()

        btn_local.clicked.connect(_do_local)
        btn_save_pw.clicked.connect(_save_pw)
        btn_cloud.clicked.connect(_do_cloud)
        v.addWidget(g1)
        v.addWidget(g2)
        v.addWidget(g3)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Close)
        bb.rejected.connect(dlg.reject)
        v.addWidget(bb)
        _refresh_status()
        dlg.exec()

