    def _manifest_has_vip_or_first(self, job: dict | None) -> bool:
        if not isinstance(job, dict) or str(job.get("typ")) != "PAX":
            return False
        man = job.get("manifest")
        if not isinstance(man, list):
            return False
        return any(
            isinstance(x, dict) and (bool(x.get("vip")) or bool(x.get("first_class")))
            for x in man
        )

    def _on_vip_catering_order_clicked(self) -> None:
        if app_meta_get(DB_PATH, "realism_vip_catering", "0") != "1":
            return
        aj = load_active_job(DB_PATH)
        if not self._manifest_has_vip_or_first(aj):
            QMessageBox.information(
                self,
                self._tr("catering.vip_title", "VIP-Catering"),
                self._tr(
                    "catering.need_vip_manifest",
                    "Kein VIP- oder First-Class-Gast im aktuellen Manifest.",
                ),
            )
            return
        if not isinstance(aj, dict):
            return
        paxn = int(aj.get("pax", 0) or 0)
        if paxn <= 0:
            return
        d = self.combo_vip_catering_level.currentData()
        ix = int(d) if d is not None else 1
        ix = max(0, min(2, ix))
        unit = VIP_CATER_PRICE_PER_PAX[ix]
        total = float(paxn) * unit
        if load_credits(DB_PATH) < total:
            QMessageBox.warning(
                self,
                self._tr("catering.vip_title", "VIP-Catering"),
                self._tr("catering.no_credits", "Nicht genug Credits."),
            )
            return
        add_credits(DB_PATH, -total)
        app_meta_set(DB_PATH, "vip_catering_leg_purchased", "1")
        append_flight_log(
            DB_PATH,
            str(aj.get("req_model", "Catering"))[:48],
            0.0,
            None,
            None,
            -total,
            0.0,
            0.0,
            0,
            0,
            str(aj.get("dep", "-")),
            str(aj.get("arr", "-")),
        )
        self._refresh_credits_label()
        self._refresh_bank_tab()
        QMessageBox.information(
            self,
            self._tr("catering.vip_title", "VIP-Catering"),
            self._tr(
                "catering.ordered_ok",
                "Catering gebucht: {amt} Credits.",
            ).format(amt=format_eur_de(total)),
        )

