    def _bootstrap_local_jobs_at_startup(self) -> None:
        icao, _la, _lo, _ts, _olv = read_persisted_aircraft_stand(DB_PATH)
        if not icao or icao not in AIRPORT_COORDS:
            return
        batch = generate_random_jobs(DB_PATH, 15, JOB_FILTER_LOCAL, icao)
        seen = {str(j.get("id")) for j in self._job_cache}
        for j in batch:
            jid = str(j.get("id", ""))
            if jid and jid not in seen:
                self._job_cache.append(j)
                seen.add(jid)

