    def _refresh_gsx_lvar_console_if_due(self) -> None:
        if not hasattr(self, "text_gsx_lvar_console") or self._aq is None:
            return
        now = time.monotonic()
        if now - getattr(self, "_last_gsx_console_mono", 0.0) < 0.9:
            return
        self._last_gsx_console_mono = now
        lines: list[str] = []
        keys = (
            "L:FSDT_GSX_BOARDING_STATE",
            "L:FSDT_GSX_BOARDING_PROGRESS",
            "L:FSDT_GSX_FUEL_STATE",
            "L:FSDT_GSX_DEICING_STATE",
            "L:FSDT_GSX_PUSHBACK_STATE",
        )
        for k in keys:
            try:
                v = self._aq.get(k)
                lines.append(f"{k} = {v}")
            except Exception:
                lines.append(f"{k} = ?")
        self.text_gsx_lvar_console.setPlainText("\n".join(lines))

    def _gsx_lvar_state_pct(self, state: int | None) -> int:
        if state is None:
            return 0
        if state >= 6:
            return 100
        return max(0, min(100, int(round((float(state) / 6.0) * 100.0))))

    def _gsx_compute_phase_progress(self) -> tuple[int, int, int, int]:
        catering = self._gsx_lvar_state_pct(self._gsx_fuel_state)
        baggage = self._gsx_lvar_state_pct(self._gsx_deice_state)
        boarding = int(round(min(100.0, max(0.0, float(self._gsx_seat_fill_pct or 0)))))
        if self._gsx_boarding_state == 6:
            boarding = 100
        elif self._aq is not None:
            prog_lv = _as_float(self._sim_snap_get("L:FSDT_GSX_BOARDING_PROGRESS"))
            if prog_lv is not None:
                pv = float(prog_lv)
                if 0.0 <= pv <= 1.0:
                    pv *= 100.0
                boarding = max(boarding, int(min(100.0, pv)))
        if boarding < self._gsx_lvar_state_pct(self._gsx_boarding_state):
            boarding = self._gsx_lvar_state_pct(self._gsx_boarding_state)
        total = int(round((catering + baggage + boarding) / 3.0))
        return catering, baggage, boarding, total

    def _refresh_gsx_progress_bars(self) -> None:
        if not hasattr(self, "progress_gsx_catering"):
            return
        c, b, p, total = self._gsx_compute_phase_progress()
        self.progress_gsx_catering.setValue(c)
        self.progress_gsx_baggage.setValue(b)
        self.progress_gsx_boarding.setValue(p)
        ready = total >= 100 and (
            self._gsx_boarding_state == 6 or p >= 100
        )
        if ready:
            self._departure_ready = True
            app_meta_set(DB_PATH, "ground_service_status", "DEPARTURE_READY")
            if hasattr(self, "label_gsx_departure_lock"):
                self.label_gsx_departure_lock.setText(
                    self._tr(
                        "gsx.lock_released",
                        "✅ DEPARTURE_READY — Cockpit freigegeben (PostgreSQL).",
                    )
                )
                self.label_gsx_departure_lock.setStyleSheet(
                    "color:#66bb6a;font-weight:800;"
                )
        elif hasattr(self, "label_gsx_departure_lock"):
            self._departure_ready = False
            self.label_gsx_departure_lock.setText(
                self._tr(
                    "gsx.lock_active",
                    "🔒 Cockpit gesperrt — Bodenabfertigung läuft (PostgreSQL).",
                )
            )
            self.label_gsx_departure_lock.setStyleSheet(
                "color:#ff7043;font-weight:700;"
            )

    def _gsx_pilot_username(self) -> str:
        return (
            str(getattr(self, "pilot_display_name", "") or "").strip()
            or app_meta_get(DB_PATH, "pilot_display_name", "Pilot")
            or pilot_handle(DB_PATH)
        )[:80]

    def _gsx_post_update_status(self, *, start_command: bool = False) -> None:
        if not online_network_enabled(DB_PATH):
            return
        base = ionos_api_base_url().strip().rstrip("/")
        if not base or not self._ionos_cloud_ready():
            return
        c, b, p, total = self._gsx_compute_phase_progress()
        gsx_ready = total >= 100 and (self._gsx_boarding_state == 6 or p >= 100)
        status = "DEPARTURE_READY" if gsx_ready else "BOARDING_ACTIVE"
        body = {
            **self._ionos_cloud_body(),
            "username": self._gsx_pilot_username(),
            "catering_status": str(self._gsx_fuel_state or 0),
            "baggage_status": str(self._gsx_deice_state or 0),
            "boarding_status": str(self._gsx_boarding_state or 0),
            "catering_pct": c,
            "baggage_pct": b,
            "boarding_pct": p,
            "total_progress": total,
            "gsx_ready": gsx_ready,
            "status": status,
        }
        if start_command:
            body["command"] = "START_GSX"
        try:
            requests.post(
                f"{base}/api/v1/gsx/update_status",
                json=body,
                timeout=8,
                headers=ionos_auth_headers(DB_PATH),
            )
        except requests.RequestException:
            pass

    def _gsx_pull_status_from_cloud(self) -> None:
        if not online_network_enabled(DB_PATH) or not self._ionos_cloud_ready():
            return
        base = ionos_api_base_url().strip().rstrip("/")
        if not base:
            return
        q = urlencode(
            {
                "hardware_id": p2p_hardware_id(DB_PATH),
                "password": cloud_password_get(DB_PATH),
            }
        )
        try:
            r = requests.get(
                f"{base}/api/v1/gsx/status?{q}",
                timeout=8,
                headers=ionos_auth_headers(DB_PATH),
            )
            data = r.json()
        except (requests.RequestException, json.JSONDecodeError, ValueError):
            return
        if not isinstance(data, dict) or not data.get("ok"):
            return
        cmd = str(data.get("command_queue") or "").strip().upper()
        if cmd == "START_GSX" and ground_ops_is_gsx_realism(DB_PATH):
            self.radio_ground_gsx.setChecked(True)
            self._append_log(
                self._tr(
                    "gsx.remote_start",
                    "GSX: Start-Befehl vom Server — Abfertigung in MSFS anstoßen.",
                )
            )
        if data.get("gsx_ready") or str(data.get("status") or "") == "DEPARTURE_READY":
            self._departure_ready = True
            app_meta_set(DB_PATH, "ground_service_status", "DEPARTURE_READY")
        for attr, key in (
            ("progress_gsx_catering", "catering_pct"),
            ("progress_gsx_baggage", "baggage_pct"),
            ("progress_gsx_boarding", "boarding_pct"),
        ):
            if hasattr(self, attr):
                getattr(self, attr).setValue(
                    int(data.get(key, 0) or 0)
                )
        self._refresh_gsx_progress_bars()

    def _gsx_pg_sync_tick(self) -> None:
        on_gsx = self._gsx_tick_fast_wanted()
        if on_gsx and ground_ops_is_gsx_realism(DB_PATH) and getattr(
            self, "simconnect_connected", False
        ):
            self._refresh_gsx_progress_bars()
            self._gsx_post_update_status()
        elif on_gsx:
            self._refresh_gsx_progress_bars()
        now = time.monotonic()
        if on_gsx or (
            now - float(getattr(self, "_gsx_cloud_pull_last_mono", 0.0) or 0.0)
            >= 14.0
        ):
            self._gsx_pull_status_from_cloud()
            self._gsx_cloud_pull_last_mono = now

    def _on_gsx_start_handling_clicked(self) -> None:
        self.radio_ground_gsx.setChecked(True)
        app_meta_set(DB_PATH, "ground_ops_mode", "gsx")
