    def _make_hr_hired_card(self, h: dict) -> QFrame:
        card = QFrame()
        card.setStyleSheet(_CREW_CARD_FRAME_STYLE)
        vl = QVBoxLayout(card)
        tier = str(h.get("tier", "junior")).lower()
        badge = QLabel("JUNIOR" if tier == "junior" else "SENIOR")
        badge.setStyleSheet(_CREW_BADGE_STYLE)
        row = QHBoxLayout()
        row.addWidget(QLabel("👤"))
        row.addWidget(QLabel(str(h.get("name", "?"))))
        row.addStretch()
        row.addWidget(badge)
        vl.addLayout(row)
        xpv = float(h.get("xp_hours", 0))
        satv = float(h.get("satisfaction_pct", 100))
        vl.addWidget(
            QLabel(
                self._tr(
                    "crew.hired_line",
                    "Monatsgehalt: {sal} · Flugstunden (XP): {xp} h · Zufriedenheit: {sat} %",
                )
                .replace("{sal}", format_eur_de(float(h.get("salary_monthly", 0))))
                .replace("{xp}", f"{xpv:.0f}")
                .replace("{sat}", f"{satv:.0f}")
            )
        )
        btn_row = QHBoxLayout()
        dismiss = QPushButton(self._tr("crew.btn_dismiss", "Entlassen"))
        dismiss.clicked.connect(partial(self._on_hr_dismiss_clicked, str(h.get("id", ""))))
        btn_row.addWidget(dismiss)
        if tier == "junior" and float(h.get("xp_hours", 0)) >= HR_PROMOTE_XP_HOURS:
            prom = QPushButton(self._tr("crew.btn_promote", "Zum Senior befördern"))
            prom.clicked.connect(partial(self._on_hr_promote_clicked, str(h.get("id", ""))))
